/* ===== خطایابی و پایداری پاسخ API =====
   اگر PHP به خطای fatal (حافظه/زمان/باگ) بخورد، به‌جای پاسخ خالی 500 یک JSON با علت واقعی برمی‌گرداند. */
ini_set('display_errors', '0');
@ini_set('memory_limit', '256M');
@set_time_limit(150);
register_shutdown_function(function () {
    $e = error_get_last();
    if (!$e || !in_array($e['type'], [E_ERROR, E_PARSE, E_CORE_ERROR, E_COMPILE_ERROR, E_USER_ERROR], true)) return;
    error_log('[panel-fatal] ' . $e['message'] . ' @' . $e['file'] . ':' . $e['line']);
    if (!headers_sent()) { http_response_code(200); header('Content-Type: application/json; charset=utf-8'); header('Cache-Control: no-store'); }
    $msg = 'خطای داخلی سرور: ' . mb_substr((string)$e['message'], 0, 180, 'UTF-8') . ' (' . basename((string)$e['file']) . ':' . (int)$e['line'] . ')';
    echo json_encode(['ok' => false, 'error' => $msg], JSON_UNESCAPED_UNICODE | JSON_INVALID_UTF8_SUBSTITUTE);
});
