/* ==================== توابع کمکی ==================== */
function e($s) { return htmlspecialchars((string)$s, ENT_QUOTES, 'UTF-8'); }
function ip() {
    global $TRUST_CLOUDFLARE;
    if ($TRUST_CLOUDFLARE && !empty($_SERVER['HTTP_CF_CONNECTING_IP']) && filter_var($_SERVER['HTTP_CF_CONNECTING_IP'], FILTER_VALIDATE_IP)) return $_SERVER['HTTP_CF_CONNECTING_IP'];
    return $_SERVER['REMOTE_ADDR'] ?? '';
}
function body() { $j = json_decode(file_get_contents('php://input'), true); return is_array($j) ? $j : []; }
function out($a, $c = 200) { http_response_code($c); header('Content-Type: application/json; charset=utf-8'); header('Cache-Control: no-store'); echo json_encode($a, JSON_UNESCAPED_UNICODE); exit; }
function st($k, $d = '') { global $db; $s = $db->prepare('SELECT v FROM settings WHERE k=?'); $s->execute([$k]); $v = $s->fetchColumn(); return $v === false ? $d : (string)$v; }
function setst($k, $v) { global $db; $db->prepare('REPLACE INTO settings(k,v) VALUES(?,?)')->execute([$k, $v]); }
function teacher_bot_config_row() {
    global $db;
    try { return $db->query("SELECT * FROM teacher_bot_config WHERE id=1")->fetch(PDO::FETCH_ASSOC) ?: []; } catch (Throwable $e) { return []; }
}
function teacher_bot_set_enabled($enabled) {
    $tc=teacher_bot_config_row();
    $ct=aes_decrypt((string)($tc['cf_token_enc']??''));
    $acc=(string)($tc['account_id']??'');
    $d1=(string)($tc['d1_id']??'');
    if($ct===''||$acc===''||$d1==='') return ['ok'=>false,'error'=>'اطلاعات Worker ربات کامل نیست.'];
    $q=d1_q($ct,$acc,$d1,"CREATE TABLE IF NOT EXISTS settings(k TEXT PRIMARY KEY,v TEXT)");
    if(empty($q['success'])) return ['ok'=>false,'error'=>cf_err($q)];
    $q=d1_q($ct,$acc,$d1,"REPLACE INTO settings(k,v) VALUES(?,?)",['bot_enabled',$enabled?'1':'0']);
    if(empty($q['success'])) return ['ok'=>false,'error'=>cf_err($q)];
    global $db;
    $db->prepare("UPDATE teacher_bot_config SET status=?,updated=?,error='' WHERE id=1")->execute([$enabled?'on':'paused',time()]);
    setst('tg_bot_on',$enabled?'1':'0');
    return ['ok'=>true];
}
function teacher_bot_broadcast_state($enabled) {
    global $db;
    $tc=teacher_bot_config_row(); $bt=aes_decrypt((string)($tc['bot_token_enc']??''));
    if($bt==='') return ['sent'=>0,'failed'=>0];
    $rows=$db->query("SELECT chat_id FROM tg_users WHERE chat_id<>'' AND banned=0 ORDER BY rowid")->fetchAll(PDO::FETCH_COLUMN);
    $sent=0;$failed=0;
    $msg=$enabled?'<b>🟢 ربات روشن شد</b>\n\n<blockquote>ربات دوباره فعال شده است. حالا می‌توانید عملیات خود را انجام دهید.</blockquote>':'<b>🔴 ربات موقتاً خاموش شد</b>\n\n<blockquote>در حال حاضر ربات به کاربران پاسخ نمی‌دهد. مدیر می‌تواند همچنان از ربات استفاده کند.</blockquote>';
    foreach($rows as $chat){
        $r=http('https://api.telegram.org/bot'.$bt.'/sendMessage',['Content-Type'=>'application/json'],json_encode(['chat_id'=>(string)$chat,'text'=>$msg,'parse_mode'=>'HTML','disable_web_page_preview'=>true],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));
        if(is_array($r)&&!empty($r['ok']))$sent++;else$failed++;
        if($sent+$failed>=2000)break;
    }
    return ['sent'=>$sent,'failed'=>$failed];
}
function tg_force_channels() { $raw=st('tg_force_channels','[]'); $a=json_decode($raw,true); if(!is_array($a))$a=[]; $out=[]; foreach($a as $i=>$c){ if(!is_array($c))continue; $id=trim((string)($c['id']??'')); $url=trim((string)($c['url']??'')); $title=trim((string)($c['title']??$url)); if($id===''||$url==='')continue; $out[]=['id'=>$id,'url'=>$url,'title'=>$title,'enabled'=>!empty($c['enabled'])?1:0]; } return $out; }
function tg_force_save($rows) { setst('tg_force_channels', json_encode(array_values($rows), JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)); }
function logev($t, $d = '', $sid = '') {
    global $db;
    $db->prepare('INSERT INTO events(ts,sid,email,type,detail,ip) VALUES(?,?,?,?,?,?)')
       ->execute([time(), $sid, $_SESSION['email'] ?? '', $t, mb_substr((string)$d, 0, 300), ip()]);
}
function rl_count($kind, $win) { global $db; $n = $db->prepare('SELECT COUNT(*) FROM rl WHERE ip=? AND kind=? AND ts>?'); $n->execute([ip(), $kind, time() - $win]); return (int)$n->fetchColumn(); }
function rl_add($kind) { global $db; $db->prepare('INSERT INTO rl(ip,kind,ts) VALUES(?,?,?)')->execute([ip(), $kind, time()]); }
function rate($kind, $limit, $win) { if (rl_count($kind, $win) >= $limit) return false; rl_add($kind); return true; }
function http_raw($url, $headers = [], $post = null, $timeout = 30) {
    if (function_exists('curl_init')) {
        $ch = curl_init($url);
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => $timeout, CURLOPT_CONNECTTIMEOUT => 10, CURLOPT_FOLLOWLOCATION => true, CURLOPT_USERAGENT => 'Mozilla/5.0 (site-bot)', CURLOPT_HTTPHEADER => $headers, CURLOPT_SSL_VERIFYPEER => true, CURLOPT_SSL_VERIFYHOST => 2]);
        if ($post !== null) { curl_setopt($ch, CURLOPT_POST, true); curl_setopt($ch, CURLOPT_POSTFIELDS, $post); }
        $r = curl_exec($ch); curl_close($ch);
        return $r === false ? null : $r;
    }
    $o = ['http' => ['method' => $post !== null ? 'POST' : 'GET', 'header' => implode("\r\n", $headers), 'timeout' => $timeout, 'ignore_errors' => true]];
    if ($post !== null) $o['http']['content'] = $post;
    $r = @file_get_contents($url, false, stream_context_create($o));
    return $r === false ? null : $r;
}
function http($url, $headers = [], $post = null) { return json_decode((string)http_raw($url, $headers, $post), true); }

/* ==================== Cloudflare ==================== */

/* ===== مدیریت سهمیه‌ی D1 حساب Cloudflare =====
   هر حساب حداکثر CF_D1_LIMIT دیتابیس D1 دارد. قبل از ساخت دیتابیس جدید، اگر سهمیه پر است
   دیتابیس‌هایی حذف می‌شوند تا جا باز شود: اول دیتابیس‌های بی‌استفاده (قدیمی‌ترین اول)، بعد دیتابیس‌های
   در استفاده (قدیمی‌ترین اول). اگر حذف یک دیتابیس شکست بخورد، سراغ بعدی می‌رود. */
if (!defined('CF_D1_LIMIT')) define('CF_D1_LIMIT', 10);
function d1_referenced_ids() {
    global $db;
    $ids = [];
    $qs = ["SELECT d1_id AS x FROM panel_records", "SELECT d1_id AS x FROM vpn_nodes", "SELECT service_d1_id AS x FROM vpn_nodes",
           "SELECT d1_id AS x FROM teacher_bot_config", "SELECT d1_id AS x FROM user_bots", "SELECT d1_id AS x FROM cf_accts"];
    foreach ($qs as $q) {
        try { foreach ($db->query($q)->fetchAll(PDO::FETCH_COLUMN) as $v) { if ($v) $ids[(string)$v] = true; } } catch (Throwable $e) {}
    }
    return $ids;
}
/* returns array of databases, or null with $err set */
function d1_list_all($tok, $acc, &$err) {
    $all = []; $err = '';
    for ($page = 1; $page <= 20; $page++) {
        $r = cf_req($tok, 'GET', '/accounts/' . rawurlencode($acc) . '/d1/database?per_page=100&page=' . $page);
        if (!is_array($r) || empty($r['success'])) { $err = cf_err(is_array($r) ? $r : []); return null; }
        $list = is_array($r['result'] ?? null) ? $r['result'] : [];
        foreach ($list as $d) { if (!empty($d['uuid'])) $all[] = $d; }
        if (count($list) < 100) break;
    }
    return $all;
}
function d1_make_room($tok, $acc) {
    $skip = []; $lastErr = '';
    for ($round = 0; $round <= CF_D1_LIMIT + 5; $round++) {
        $err = '';
        $all = d1_list_all($tok, $acc, $err);
        if ($all === null) return ['ok' => false, 'error' => 'لیست دیتابیس‌های حساب خوانده نشد: ' . $err];
        if (count($all) < CF_D1_LIMIT) return ['ok' => true];
        $ref = d1_referenced_ids();
        usort($all, function ($x, $y) { return strcmp((string)($x['created_at'] ?? ''), (string)($y['created_at'] ?? '')); });
        $ordered = [];
        foreach ($all as $d) { if (empty($ref[(string)$d['uuid']]) && !isset($skip[(string)$d['uuid']])) $ordered[] = $d; }
        foreach ($all as $d) { if (!empty($ref[(string)$d['uuid']]) && !isset($skip[(string)$d['uuid']])) $ordered[] = $d; }
        if (!$ordered) return ['ok' => false, 'error' => 'هیچ دیتابیسی برای حذف پیدا نشد؛ ' . $lastErr];
        $pick = $ordered[0];
        $inUse = !empty($ref[(string)$pick['uuid']]);
        $del = cf_req($tok, 'DELETE', '/accounts/' . rawurlencode($acc) . '/d1/database/' . rawurlencode((string)$pick['uuid']));
        $ok = !empty($del['success']);
        logev('d1_evict', 'name=' . (string)($pick['name'] ?? '') . ' uuid=' . (string)$pick['uuid'] . ' in_use=' . ($inUse ? '1' : '0') . ' ok=' . ($ok ? '1' : '0') . ($ok ? '' : ' err=' . cf_err($del)));
        if (!$ok) { $lastErr = cf_err($del); $skip[(string)$pick['uuid']] = true; }
    }
    return ['ok' => false, 'error' => 'حذف دیتابیس قدیمی ناموفق بود: ' . $lastErr];
}
function cf_req($token, $method, $path, $body = null, $ctype = 'application/json', $timeout = 12, $max = 2) {
    $token = trim((string)$token);
    if ($method === 'POST' && $body !== null && preg_match('#^/accounts/([^/]+)/d1/database$#', (string)$path, $__dm)) {
        $__room = d1_make_room($token, rawurldecode($__dm[1]));
        if (empty($__room['ok'])) return ['success' => false, 'net' => false, 'errors' => [['message' => (string)$__room['error']]], '_http_code' => 0];
    }
    if ($token === '') return ['success'=>false,'net'=>false,'errors'=>[['message'=>'Cloudflare API Token خالی است']],'_http_code'=>0];
    $url = 'https://api.cloudflare.com/client/v4' . $path;
    $h = ['Authorization: Bearer ' . $token, 'Accept: application/json', 'User-Agent: DEMON-Panel/5.8'];
    if ($body !== null) $h[] = 'Content-Type: ' . $ctype;
    $payload = $body === null ? null : (is_array($body) ? json_encode($body, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) : $body);
    $last = ['success'=>false,'net'=>true,'errors'=>[['message'=>'ارتباط با Cloudflare برقرار نشد']],'_http_code'=>0];
    $max = max(1, min(3, (int)$max)); $timeout = max(4, min(15, (int)$timeout));
    for ($try=1; $try<=$max; $try++) {
        $ch = function_exists('curl_init') ? curl_init($url) : false;
        if ($ch) {
            curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>$timeout,CURLOPT_CONNECTTIMEOUT=>min(5,$timeout),CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_HTTPHEADER=>$h,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_ENCODING=>'',CURLOPT_HTTP_VERSION=>(defined('CURL_HTTP_VERSION_2TLS') ? CURL_HTTP_VERSION_2TLS : CURL_HTTP_VERSION_1_1),CURLOPT_USERAGENT=>'DEMON-Panel/5.8']);
            if($payload!==null) curl_setopt($ch,CURLOPT_POSTFIELDS,$payload);
            $r=curl_exec($ch); $errno=curl_errno($ch); $errstr=curl_error($ch); $code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE); curl_close($ch);
            if($r!==false && $r!=='') {
                $j=json_decode($r,true);
                if(is_array($j)) {
                    $j['_http_code']=$code;
                    if(!empty($j['success'])) return $j;
                    $last=$j;
                    if($code>=400 && $code<500 && $code!==429) return $j;
                } else $last=['success'=>false,'net'=>false,'errors'=>[['message'=>'Cloudflare پاسخ JSON معتبر برنگرداند']],'_http_code'=>$code,'_raw'=>mb_substr((string)$r,0,300)];
            } else $last=['success'=>false,'net'=>true,'errors'=>[['message'=>($errstr?:'خطای شبکه').' (cURL '.$errno.')']],'_http_code'=>$code];
        } else {
            $r=http_raw($url,$h,$payload,$timeout); $j=json_decode((string)$r,true);
            if(is_array($j)) { $last=$j; if(!empty($j['success'])) return $j; }
            else $last=['success'=>false,'net'=>true,'errors'=>[['message'=>'cURL روی سرور نصب نیست یا ارتباط HTTPS برقرار نشد']],'_http_code'=>0];
        }
        if($try<$max) usleep(250000*$try);
    }
    return $last;
}
function cf_err($j) { $m=mb_substr((string)($j['errors'][0]['message']??''),0,220); $c=(int)($j['errors'][0]['code']??0); $hc=(int)($j['_http_code']??0); return ($c?('['.$c.'] '):'').($m?:('HTTP '.($hc?:'نامشخص'))); }
function cf_worker_upload($token, $acc, $name, $source, $bindings, $keep = [], $region = '') {
    /* Fast deploy path: the successful PUT is authoritative. Do not perform a
       long verification loop here; shared hosting can kill long HTTP requests. */
    $bd = 'cfb' . bin2hex(random_bytes(8));
    $mm = ['main_module' => 'worker.js', 'compatibility_date' => '2025-01-01', 'bindings' => $bindings];
    if ($keep) $mm['keep_bindings'] = $keep;
    if ($region !== '') $mm['placement'] = ['region' => $region];
    $meta = json_encode($mm, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    $body = "--$bd\r\nContent-Disposition: form-data; name=\"metadata\"\r\nContent-Type: application/json\r\n\r\n$meta\r\n"
          . "--$bd\r\nContent-Disposition: form-data; name=\"worker.js\"; filename=\"worker.js\"\r\nContent-Type: application/javascript+module\r\n\r\n$source\r\n--$bd--\r\n";
    /* Worker uploads can legitimately take several seconds on Cloudflare.
       The old 6s/1-attempt limit caused cURL 28 before Cloudflare finished.
       Give the upload a bounded retry window instead of failing immediately. */
    $r = cf_req($token, 'PUT', '/accounts/' . rawurlencode($acc) . '/workers/scripts/' . rawurlencode($name), $body, 'multipart/form-data; boundary=' . $bd, 15, 2);
    if (empty($r['success'])) return $r;
    $r['_deployed'] = true;
    $r['_verified'] = false;
    $r['_verification_attempts'] = 0;
    return $r;
}

/* ==================== Legacy panel kill-switch ====================
 * با انتشار نسخه جدید، پنل‌های ساخته‌شده با نسخه قبلی عمداً غیرفعال می‌شوند.
 * اطلاعات D1 حذف نمی‌شود؛ فقط Worker قدیمی و مسیر دسترسی آن از کار می‌افتد.
 */
function invalidate_legacy_panels() {
    global $db, $PANEL_VERSION, $PANEL_RELEASE_MODE;
    if ($PANEL_RELEASE_MODE !== 'invalidate-legacy') return;
    $last = (string)($db->query("SELECT v FROM settings WHERE k='panel_release_version' LIMIT 1")->fetchColumn() ?: '');
    if ($last === $PANEL_VERSION) return;
    $rows = $db->query("SELECT * FROM panel_records WHERE active=1 AND COALESCE(panel_version,'3.1.0')<>" . $db->quote($PANEL_VERSION))->fetchAll(PDO::FETCH_ASSOC);
    foreach ($rows as $r) {
        $ok = false;
        $tok = aes_decrypt((string)($r['cf_token_enc'] ?? ''));
        if ($tok !== '' && !empty($r['account_id']) && !empty($r['worker'])) {
            $del = cf_req($tok, 'DELETE', '/accounts/' . rawurlencode((string)$r['account_id']) . '/workers/scripts/' . rawurlencode((string)$r['worker']) . '?force=true');
            $code = (int)($del['errors'][0]['code'] ?? 0);
            $ok = !empty($del['success']) || $code === 10007;
        }
        $st = $db->prepare("UPDATE panel_records SET active=0, invalidated_at=?, invalidation_reason=?, panel_version=? WHERE id=?");
        $st->execute([time(), 'نسخه قدیمی پس از انتشار نسخه ' . $PANEL_VERSION . ' غیرفعال شد', (string)($r['panel_version'] ?: '3.1.0'), (int)$r['id']]);
    }
    $db->prepare("REPLACE INTO settings(k,v) VALUES('panel_release_version',?)")->execute([$PANEL_VERSION]);
}

/* انتشار نسخه: پنل‌های قدیمی در اولین درخواست بعد از انتشار غیرفعال می‌شوند. */
invalidate_legacy_panels();

/* لیست IP/دامنهٔ تمیز (فشرده) برای Worker */
