body{min-height:100vh;background:#05070d;color:#e7e9ee;font-family:Morabba,Tahoma,sans-serif;font-size:14px;line-height:1.7;background-image:linear-gradient(rgba(4,7,13,.82),rgba(4,7,13,.92)),url("https://dorpic.ir/wp-content/uploads/2023/03/%D8%AA%D8%B5%D9%88%DB%8C%D8%B1-%D8%B2%D9%85%DB%8C%D9%86%D9%87-%D8%A2%D9%86%D8%A7%D9%86%DB%8C%D9%85%D9%88%D8%B3.webp");background-size:cover;background-position:center;background-attachment:fixed}
