var qb=document.getElementById("qrBtn"),qe=document.getElementById("qr");
qb.addEventListener("click",function(){
  if(!qe.dataset.done){
    try{var q=qrcode(0,"M");q.addData(SUB);q.make();qe.innerHTML=q.createSvgTag({cellSize:4,margin:2,scalable:true});qe.dataset.done="1"}
    catch(e){qe.textContent=SUB}
  }
  qe.hidden=!qe.hidden;
});
