.toast{position:fixed;bottom:18px;left:50%;transform:translateX(-50%) translateY(20px);background:#16a34a;color:#fff;padding:8px 16px;border-radius:99px;font-weight:700;opacity:0;transition:.2s;pointer-events:none}
.toast.on{opacity:1;transform:translateX(-50%) translateY(0)}
@media(max-width:640px){.hide-m{display:none}}
</style>
</head>
<body>
<div class="wrap">
  <h1>اسکنر پروکسی IP</h1>
  <div class="sub">IPهای پروکسی را تست کن، کشور و پینگ هرکدام را ببین و بهترین‌ها را برای کاربر انتخاب کن.</div>

  <div class="card">
    <div class="stats">
      <div class="stat"><span>کل IPها</span><b id="sTotal">0</b></div>
      <div class="stat"><span>تست‌شده (تازه)</span><b id="sTested">0</b></div>
      <div class="stat"><span>سالم</span><b id="sOk" style="color:#4ade80">0</b></div>
      <div class="stat"><span>خراب</span><b id="sBad" style="color:#f87171">0</b></div>
      <div class="stat"><span>میانگین پینگ سالم‌ها</span><b id="sAvg">—</b></div>
    </div>
    <div class="row" style="margin-top:12px">
      <button id="bLoad" type="button">بروزرسانی لیست</button>
      <button id="bTestAll" type="button">تست همه</button>
      <button id="bTestSel" type="button" class="gh">تست انتخاب‌شده‌ها</button>
      <button id="bStop" type="button" class="dg" disabled>توقف</button>
      <button id="bCopyOk" type="button" class="gh">کپی IPهای سالم</button>
      <button id="bCsv" type="button" class="gh">خروجی CSV</button>
      <button id="bClear" type="button" class="gh">پاک‌کردن کش</button>
      <span class="muted" id="cacheInfo"></span>
    </div>
    <div class="prog" id="prog"><i></i></div>
  </div>

  <div class="card">
    <div class="row">
      <input class="q" id="q" placeholder="جستجو: IP، کشور، شهر، ISP">
      <select id="cc"><option value="">همه کشورها</option></select>
      <select id="sf">
        <option value="all">همه وضعیت‌ها</option>
        <option value="ok">فقط سالم</option>
        <option value="bad">فقط خراب</option>
        <option value="untested">تست‌نشده</option>
      </select>
      <select id="so">
        <option value="lat">مرتب‌سازی: پینگ کم به زیاد</option>
        <option value="latd">مرتب‌سازی: پینگ زیاد به کم</option>
        <option value="country">مرتب‌سازی: کشور</option>
        <option value="ip">مرتب‌سازی: IP</option>
      </select>
    </div>
    <div class="row muted" style="margin-top:8px">
      <label><input type="checkbox" id="selAll"> انتخاب همه‌ی نمایش‌داده‌شده</label>
      <span id="shown"></span>
      <span id="selCount"></span>
    </div>
    <div class="wrapx">
      <table class="tbl">
        <thead><tr>
          <th style="width:30px"></th>
          <th>IP</th>
          <th>کشور</th>
          <th class="hide-m">ISP</th>
          <th>وضعیت</th>
          <th>پینگ</th>
          <th class="hide-m">موفقیت</th>
          <th></th>
        </tr></thead>
        <tbody id="rows"></tbody>
      </table>
    </div>
  </div>
</div>
<div class="toast" id="toast"></div>
<script>
const API = '__APIBASE__';
const CK = 'vexm_ps_v2', TTL_RES = 10 * 60000, TTL_GEO = 60 * 60000;
let geo = [], res = {}, sel = new Set(), running = false, stopFlag = false;
const $ = (q) => document.querySelector(q);
const $$ = (q) => Array.prototype.slice.call(document.querySelectorAll(q));
function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); }
function toast(m) { const t = $('#toast'); t.textContent = m; t.classList.add('on'); clearTimeout(toast.t); toast.t = setTimeout(() => t.classList.remove('on'), 2200); }
function saveCache() { try { localStorage.setItem(CK, JSON.stringify({ ts: Date.now(), geo: geo, res: res })); } catch (e) {} }
function loadCache() {
  try {
    const c = JSON.parse(localStorage.getItem(CK) || 'null');
    if (c && c.ts && Date.now() - c.ts < TTL_GEO) { geo = c.geo || []; res = c.res || {}; return true; }
  } catch (e) {}
  return false;
}
function st(ip) { const r = res[ip]; if (!r || Date.now() - r.t > TTL_RES) return 'untested'; return r.ok ? 'ok' : 'bad'; }
function ms(ip) { const r = res[ip]; return (r && r.ok && r.ms != null && Date.now() - r.t <= TTL_RES) ? r.ms : null; }
function mcls(v) { return v == null ? '' : (v < 150 ? 'm-g' : (v < 400 ? 'm-a' : 'm-r')); }
function setProg(done, total) {
  const p = $('#prog'); if (!total) { p.style.display = 'none'; return; }
  p.style.display = 'block'; p.firstChild.style.width = Math.round(done / total * 100) + '%';
}
function filtered() {
  const q = $('#q').value.trim().toLowerCase(), cc = $('#cc').value, sf = $('#sf').value, so = $('#so').value;
  let a = geo.filter((x) => {
    if (cc && x.countryCode !== cc) return false;
    if (sf !== 'all' && st(x.ip) !== sf) return false;
    if (q && (x.ip + ' ' + x.country + ' ' + x.city + ' ' + x.isp).toLowerCase().indexOf(q) < 0) return false;
    return true;
  });
  const L = (x) => (ms(x.ip) == null ? 1e9 : ms(x.ip));
  if (so === 'lat') a.sort((x, y) => L(x) - L(y));
  else if (so === 'latd') a.sort((x, y) => { const p = ms(x.ip), q2 = ms(y.ip); return (q2 == null ? -1 : q2) - (p == null ? -1 : p); });
  else if (so === 'country') a.sort((x, y) => (x.country || '').localeCompare(y.country || ''));
  else a.sort((x, y) => x.ip.localeCompare(y.ip));
  return a;
}
function renderStats() {
  let ok = 0, bad = 0, tested = 0, sum = 0, n = 0;
  geo.forEach((x) => { const s = st(x.ip); if (s === 'ok') { ok++; tested++; const v = ms(x.ip); if (v != null) { sum += v; n++; } } else if (s === 'bad') { bad++; tested++; } });
  $('#sTotal').textContent = geo.length; $('#sTested').textContent = tested; $('#sOk').textContent = ok; $('#sBad').textContent = bad;
  $('#sAvg').textContent = n ? Math.round(sum / n) + ' ms' : '—';
}
function fillCountries() {
  const cur = $('#cc').value; const map = {};
  geo.forEach((x) => { if (x.countryCode) map[x.countryCode] = x.country || x.countryCode; });
  const keys = Object.keys(map).sort((a, b) => map[a].localeCompare(map[b]));
  $('#cc').innerHTML = '<option value="">همه کشورها</option>' + keys.map((k) => '<option value="' + esc(k) + '">' + esc(map[k]) + ' (' + esc(k) + ')</option>').join('');
  $('#cc').value = cur;
}
function render(full) {
  if (full !== false) fillCountries();
  renderStats();
  const list = filtered();
  $('#shown').textContent = list.length + ' نمایش';
  $('#selCount').textContent = sel.size ? ('· ' + sel.size + ' انتخاب‌شده') : '';
  const rows = list.slice(0, 600).map((x) => {
    const s = st(x.ip), v = ms(x.ip), r = res[x.ip];
    const badge = s === 'ok' ? '<span class="badge b-ok">سالم</span>' : s === 'bad' ? '<span class="badge b-bad">خراب</span>' : '<span class="badge b-un">تست‌نشده</span>';
    const flag = x.countryCode ? '<img class="flag" loading="lazy" src="https://flagcdn.com/w40/' + esc(x.countryCode.toLowerCase()) + '.png" alt="">' : '';
    return '<tr>' +
      '<td><input type="checkbox" data-sel="' + esc(x.ip) + '"' + (sel.has(x.ip) ? ' checked' : '') + '></td>' +
      '<td class="ip">' + esc(x.ip) + '</td>' +
      '<td>' + flag + esc(x.country || '—') + (x.city ? '<div class="muted">' + esc(x.city) + '</div>' : '') + '</td>' +
      '<td class="hide-m muted">' + esc(x.isp || '—') + '</td>' +
      '<td>' + badge + '</td>' +
      '<td>' + (v == null ? '<span class="muted">—</span>' : '<span class="ms ' + mcls(v) + '">' + v + ' ms</span>') + '</td>' +
      '<td class="hide-m muted">' + (r && Date.now() - r.t <= TTL_RES ? esc(r.rate) : '—') + '</td>' +
      '<td><button class="gh" data-test="' + esc(x.ip) + '" type="button">تست</button> <button class="gh" data-copy="' + esc(x.ip) + '" type="button">کپی</button></td>' +
      '</tr>';
  }).join('');
  $('#rows').innerHTML = rows || '<tr><td colspan="8" class="muted" style="text-align:center;padding:20px">موردی پیدا نشد</td></tr>';
  $('#cacheInfo').textContent = 'کش: ' + (Object.keys(res).length) + ' نتیجه';
}
async function loadGeo(force) {
  if (!force && loadCache() && geo.length) { render(); return; }
  $('#bLoad').disabled = true; $('#bLoad').textContent = 'در حال دریافت...';
  try {
    const r = await fetch(API + '/proxy-ips/get', { credentials: 'same-origin' });
    const j = await r.json();
    geo = (j.body || []).filter((x) => x && x.ip);
    saveCache();
    toast(geo.length + ' IP دریافت شد');
  } catch (e) { toast('خطا در دریافت لیست'); }
  $('#bLoad').disabled = false; $('#bLoad').textContent = 'بروزرسانی لیست';
  render();
}
async function testOne(ip) {
  try {
    const r = await fetch(API + '/proxy-ips/test?target=' + encodeURIComponent(ip), { credentials: 'same-origin' });
    const j = await r.json(); const b = j.body || {};
    res[ip] = { ok: b.avgLatencyMs != null, ms: b.avgLatencyMs, rate: b.successRate || '0/5', t: Date.now() };
  } catch (e) { res[ip] = { ok: false, ms: null, rate: '0/5', t: Date.now() }; }
}
async function runTests(list) {
  if (running) { toast('تست در حال اجراست'); return; }
  if (!list.length) { toast('موردی برای تست نیست'); return; }
  running = true; stopFlag = false; setBtns(true);
  let idx = 0, done = 0; const total = list.length; setProg(0, total);
  const workers = [0, 1, 2, 3].map(async () => {
    while (idx < list.length && !stopFlag) {
      const ip = list[idx++];
      await testOne(ip);
      done++; setProg(done, total);
      if (done % 4 === 0) render(false);
    }
  });
  await Promise.all(workers);
  running = false; setBtns(false); saveCache(); render();
  setTimeout(() => setProg(0, 0), 800);
  toast(stopFlag ? 'متوقف شد (' + done + ' تست)' : 'تست تمام شد');
}
function setBtns(on) { $('#bStop').disabled = !on; $('#bTestAll').disabled = on; $('#bTestSel').disabled = on; }
function copy(text, msg) {
  if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(text).then(() => toast(msg), () => toast('کپی ناموفق'));
  else toast('کپی ناموفق');
}
function toCsv(list) {
  const head = ['ip', 'country', 'countryCode', 'city', 'isp', 'status', 'ping_ms', 'success'];
  const lines = [head.join(',')].concat(list.map((x) => {
    const s = st(x.ip), v = ms(x.ip), r = res[x.ip];
    return [x.ip, x.country, x.countryCode, x.city, x.isp, s, v == null ? '' : v, r ? r.rate : ''].map((c) => '"' + String(c == null ? '' : c).replace(/"/g, '""') + '"').join(',');
  }));
  return lines.join('\\n');
}
function download(name, text) {
  const a = document.createElement('a');
  a.href = URL.createObjectURL(new Blob(['\\ufeff' + text], { type: 'text/csv;charset=utf-8' }));
  a.download = name; document.body.appendChild(a); a.click(); setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 500);
}
$('#rows').addEventListener('click', (e) => {
  const t = e.target.closest('button'); if (t) {
    if (t.dataset.test) { runTests([t.dataset.test]); }
    if (t.dataset.copy) { copy(t.dataset.copy, 'IP کپی شد'); }
    return;
  }
  const cb = e.target.closest('input[data-sel]');
  if (cb) { cb.checked ? sel.add(cb.dataset.sel) : sel.delete(cb.dataset.sel); render(false); }
});
$('#selAll').addEventListener('change', (e) => { filtered().forEach((x) => e.target.checked ? sel.add(x.ip) : sel.delete(x.ip)); render(false); });
$('#bLoad').onclick = () => loadGeo(true);
$('#bTestAll').onclick = () => { const list = filtered().map((x) => x.ip).filter((ip) => st(ip) === 'untested' || Date.now() - (res[ip] ? res[ip].t : 0) > TTL_RES); runTests(list.slice(0, 300)); };
$('#bTestSel').onclick = () => { if (!sel.size) { toast('ابتدا IPها را انتخاب کن'); return; } runTests(Array.from(sel)); };
$('#bStop').onclick = () => { stopFlag = true; };
$('#bCopyOk').onclick = () => { const ok = filtered().filter((x) => st(x.ip) === 'ok').map((x) => x.ip); if (!ok.length) { toast('IP سالمی نیست'); return; } copy(ok.join('\\n'), ok.length + ' IP کپی شد'); };
$('#bCsv').onclick = () => download('proxy-ips.csv', toCsv(filtered()));
$('#bClear').onclick = () => { res = {}; geo = geo; saveCache(); render(); toast('نتایج تست پاک شد'); };
['q', 'cc', 'sf', 'so'].forEach((id) => $('#' + id).addEventListener('input', () => render(false)));
loadGeo(false);
</script>
</body>
</html>
`;


