async function dbInit(env){await env.BOT_DB.batch([env.BOT_DB.prepare('CREATE TABLE IF NOT EXISTS users(chat_id TEXT PRIMARY KEY,username TEXT,first_name TEXT,created INTEGER,last_seen INTEGER,banned INTEGER DEFAULT 0)'),env.BOT_DB.prepare('CREATE TABLE IF NOT EXISTS relay(owner_msg_id INTEGER PRIMARY KEY,user_chat TEXT)'),env.BOT_DB.prepare('CREATE TABLE IF NOT EXISTS settings(k TEXT PRIMARY KEY,v TEXT)'),env.BOT_DB.prepare("INSERT OR IGNORE INTO settings(k,v) VALUES('bot_enabled','1')")]);}
async function enabled(env){const r=await env.BOT_DB.prepare("SELECT v FROM settings WHERE k='bot_enabled'").first();return String(r?.v??'1')==='1'}
async function ownerMenu(chat,env){const on=await enabled(env);return tg('sendMessage',{chat_id:chat,text:'وضعیت ربات: '+(on?'روشن':'خاموش')+'\nپیام‌های کاربران به همین چت می‌آیند. برای پاسخ، روی پیام کاربر Reply بزن.',reply_markup:KB([[{text:on?'خاموش کردن':'روشن کردن',callback_data:on?'bot:0':'bot:1'}]])})}
async function handle(m,env){
  const chat=String(m.chat.id);
  if(isOwner(chat,env)){
    if(m.reply_to_message){const r=await env.BOT_DB.prepare('SELECT user_chat FROM relay WHERE owner_msg_id=?').bind(m.reply_to_message.message_id).first();if(r){await tg('copyMessage',{chat_id:r.user_chat,from_chat_id:chat,message_id:m.message_id});return tg('sendMessage',{chat_id:chat,text:'ارسال شد.',reply_to_message_id:m.message_id})}}
    return ownerMenu(chat,env);
  }
  if(!(await enabled(env)))return;
  const now=Date.now();
  await env.BOT_DB.prepare('INSERT INTO users(chat_id,username,first_name,created,last_seen,banned) VALUES(?,?,?,?,?,0) ON CONFLICT(chat_id) DO UPDATE SET username=excluded.username,first_name=excluded.first_name,last_seen=excluded.last_seen').bind(chat,String(m.from?.username||''),String(m.from?.first_name||''),now,now).run();
  const b=await env.BOT_DB.prepare('SELECT banned FROM users WHERE chat_id=?').bind(chat).first();
  if(b?.banned){return tg('sendMessage',{chat_id:chat,text:'حساب شما توسط مدیر از این ربات بند شده است و دیگر پاسخ داده نمی‌شود.'})}
  if(typeof m.text==='string'&&/^\/start/.test(m.text))return tg('sendMessage',{chat_id:chat,text:'سلام. پیام خود را بفرستید؛ به‌زودی پاسخ داده می‌شود.'});
  const f=await tg('forwardMessage',{chat_id:env.BOT_OWNER_ID,from_chat_id:chat,message_id:m.message_id});
  if(f&&f.ok)await env.BOT_DB.prepare('INSERT OR REPLACE INTO relay(owner_msg_id,user_chat) VALUES(?,?)').bind(f.result.message_id,chat).run();
}
