const J=(o,s=200)=>new Response(JSON.stringify(o),{status:s,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store'}});
async function tg(method,body,env){if(body&&typeof body==='object')for(const k of Object.keys(body))if(body[k]===null)delete body[k];const call=async b=>{const r=await fetch('https://api.telegram.org/bot'+env.BOT_TOKEN+'/'+method,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(b)});try{return await r.json()}catch(e){return {ok:false,description:'Telegram API response error'}}};let x=await call(body);if(x&&!x.ok&&body&&body.reply_markup&&body.reply_markup.inline_keyboard){const kb=body.reply_markup.inline_keyboard.map(row=>row.map(btn=>{const o={...btn};delete o.style;return o}));x=await call({...body,reply_markup:{inline_keyboard:kb}})}return x}
const esc=s=>String(s??'').replace(/[<>&]/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;'}[c]));
const B=(text,callback_data=null,url=null,style=null)=>{let st=style;if(!st){const x=String(callback_data||''),t=String(text||'');if(/^(del|ban|pud|close)/.test(x)||/حذف|بن |مسدود|خاموش/.test(t))st='danger';else if(/^(menu|help|guide|admin|users|panels|panel|pusers|u|admin_|userpanels|profile|status|settings|health)/.test(x)||/بازگشت|منو|اطلاعات|وضعیت|مدیریت/.test(t))st='primary';else st='success';}const o={text:String(text),style:st};if(url)o.url=String(url);else if(callback_data)o.callback_data=String(callback_data);return o};
const KB=rows=>({inline_keyboard:rows.filter(Boolean)}),sleep=ms=>new Promise(r=>setTimeout(r,ms));
