  }
  if(op==='pmrep'){await send(chat,'<b>ترمیم پنل؟</b>\n\n'+quote('Worker پنل دوباره ساخته و به یک دیتابیس جدید وصل می‌شود. اگر دیتابیس قبلی حذف شده باشد، اطلاعات کاربران آن از بین رفته است.'),env,KB([[B('بله، ترمیم کن','pmrepok:'+id,'','success'),B('خیر','pm:'+id,'','danger')]]));return true}
  if(op==='pmrepok'){const frames=['◐','◓','◑','◒'];const first=await send(chat,'<b>'+frames[0]+' در حال ترمیم پنل…</b>',env,null);const msg=first&&first.result?first.result.message_id:null;let done=false,i=0;const loop=(async()=>{while(!done&&msg){i++;await edit(chat,msg,'<b>'+frames[i%4]+' در حال ترمیم پنل'+'.'.repeat((i%3)+1)+'</b>',env,null);await sleep(1200)}})();let r;try{r=await api(env,{action:'panel_repair',chat_id:chat,id})}catch(e){r={ok:false,error:'خطای ارتباط'}}finally{done=true;await loop.catch(()=>{})}const t=r&&r.ok?'<b>✅ پنل ترمیم شد</b>\n\n'+quote('حالا می‌توانی وارد پنل شوی.'):'<b>❌ ترمیم ناموفق بود</b>\n\n'+quote((r&&r.error)||'خطا');const kb=KB([[B('📦 پنل‌ها','panels','','primary')]]);if(msg)await edit(chat,msg,t,env,kb);else await send(chat,t,env,kb);return true}
  if(op==='pmupd'){
    const r=await api(env,{action:'my_panels',chat_id:chat});
    await send(chat,'<b>آیا از آپدیت پنل به نسخهٔ '+esc(r.current||'جدید')+' مطمئنی؟</b>',env,KB([[B('بله','pmupdok:'+id,'','success'),B('خیر','pm:'+id,'','danger')]]));return true;
  }
  if(op==='pmupdok'){
    const frames=['◐','◓','◑','◒'];
    const first=await send(chat,'<b>'+frames[0]+' در حال آپدیت پنل…</b>',env,null);
    const msg=first&&first.result?first.result.message_id:null;
    let done=false,i=0;
    const loop=(async()=>{while(!done&&msg){i++;await edit(chat,msg,'<b>'+frames[i%4]+' در حال آپدیت پنل'+'.'.repeat((i%3)+1)+'</b>',env,null);await sleep(1200)}})();
    let r;try{r=await api(env,{action:'panel_update',chat_id:chat,id})}catch(e){r={ok:false,error:'خطای ارتباط'}}finally{done=true;await loop.catch(()=>{})}
    let kb=KB([[B('⬅️ پنل‌ها','panels','','primary')]]);
    if(r&&r.code==='db_missing')kb=KB([[B('🛠 ترمیم پنل','pmrep:'+id,'','primary')],[B('🗑 حذف پنل','del:'+id,'','danger')],[B('⬅️ پنل‌ها','panels','','primary')]]);
    if(r&&r.ok){const lp=await api(env,{action:'my_panels',chat_id:chat});const p=(lp.panels||[]).find(x=>String(x.id)===id);if(p&&p.worker)kb=KB([[B('ورود به پنل',null,String(p.worker),'success')],[B('⬅️ پنل‌ها','panels','','primary')]]);}
