async function tg(method,body,env){if(body&&typeof body==='object')for(const k of Object.keys(body))if(body[k]===null)delete body[k];const r=await fetch('https://api.telegram.org/bot'+env.BOT_TOKEN+'/'+method,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});try{return await r.json();}catch(e){return {ok:false};}}
export default {async fetch(req,env){if(req.method==='GET')return new Response('DEMON TELEGRAM BOT OK');if(req.method!=='POST')return new Response('Method Not Allowed',{status:405});if(env.WEBHOOK_SECRET&&req.headers.get('X-Telegram-Bot-Api-Secret-Token')!==env.WEBHOOK_SECRET)return new Response('forbidden',{status:403});let u={};try{u=await req.json();}catch(e){return new Response('ok');}const m=u.message||u.edited_message,cq=u.callback_query;if(cq?.id){try{await tg('answerCallbackQuery',{callback_query_id:cq.id},env);}catch(e){}}if(m?.chat){const text='سلام 👋\nاین یک ربات تست DEMON است.\nربات با موفقیت برای این پنل فعال شده است.';const kb={inline_keyboard:[[{text:'ورود به پنل',url:String(env.PANEL_URL||'')}]]};await tg('sendMessage',{chat_id:m.chat.id,text,reply_markup:kb},env);}return new Response('ok');}};`);
