    const token=await secretDec(env,r?.token_enc||''); if(token){try{await fetch('https://api.telegram.org/bot'+token+'/deleteWebhook',{method:'POST',body:new URLSearchParams({drop_pending_updates:'true'})});}catch(e){}}
