    await setSet(env, 'address', a); await setSet(env, 'proxy_ip', p); await setSet(env, 'block_ads', b.block_ads ? '1' : '0'); if (b.daily_cap !== undefined) await setSet(env, 'daily_cap', String(Math.max(0, Math.min(1000000, Number(b.daily_cap) || 95000))));
