<script>
var S = __STATE__;
var $ = function(i){ return document.getElementById(i); };
var fa = function(s){ return String(s).replace(/\d/g, function(d){ return '۰۱۲۳۴۵۶۷۸۹'[d]; }); };
function sz(b){ if (b < 0) return 'نامحدود'; if (b >= 1073741824) return fa((b / 1073741824).toFixed(2)) + ' GB'; if (b >= 1048576) return fa((b / 1048576).toFixed(1)) + ' MB'; return fa(Math.round(b / 1024)) + ' KB'; }
function esc(s){ return String(s).replace(/[&<>"']/g, function(c){ return {'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]; }); }
function cp(t, b){
  var done = function(){ if (b) { var o = b.getAttribute('data-o') || b.textContent; b.setAttribute('data-o', o); b.textContent = 'کپی شد ✓'; clearTimeout(b._t); b._t = setTimeout(function(){ b.textContent = o; }, 1300); } };
  if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(t).then(done, function(){ fb(t); done(); }); else { fb(t); done(); }
}
function fb(t){ var a = document.createElement('textarea'); a.value = t; a.style.cssText = 'position:fixed;left:-9999px'; document.body.appendChild(a); a.select(); try { document.execCommand('copy'); } catch (e) {} document.body.removeChild(a); }
var shown = 0;
function render(){
  $('nm').textContent = S.name;
  var pl = $('pl'), m = {ok: ['ok', '● فعال'], off: ['bad', '● غیرفعال'], expired: ['bad', '● منقضی شده'], full: ['bad', '● حجم تمام شده']}[S.status] || ['', ''];
  if (S.pending && S.status === 'ok') m = ['wa', '⏳ شروع زمان از اولین اتصال'];
  pl.className = 'pill ' + m[0]; pl.textContent = m[1];
  var p = S.limit > 0 ? S.pct : 0, c = 766.5;
  $('rg').style.strokeDashoffset = c - c * Math.max(S.limit > 0 ? 0.012 : 1, p / 100);
  var t0 = performance.now(), from = shown, to = p;
  (function f(t){ var k = Math.min(1, (t - t0) / 900), e = 1 - Math.pow(1 - k, 3); if (S.limit > 0) $('pc').textContent = fa((from + (to - from) * e).toFixed(to % 1 ? 1 : 0)) + '٪'; else $('pc').textContent = '∞'; if (k < 1) requestAnimationFrame(f); else shown = to; })(t0);
  $('ps').textContent = S.limit > 0 ? 'از حجم مصرف شده' : 'حجم نامحدود';
  $('tT').textContent = sz(S.limit > 0 ? S.limit : -1); $('tU').textContent = sz(S.used); $('tL').textContent = sz(S.left);
  $('tD').textContent = S.pending ? fa(S.days) + ' روز (از اولین اتصال)' : (S.days_left < 0 ? 'نامحدود' : (S.days_left === 0 ? 'تمام شده' : fa(S.days_left) + ' روز'));
  $('ls').innerHTML = S.links.map(function(l, i){ return '<div class="lk"><span dir="ltr">' + esc(l.name) + '</span><button class="ghost" data-i="' + i + '">کپی</button></div>'; }).join('') || '<div class="ft">کانفیگی نیست</div>';
}
$('ls').onclick = function(e){ var b = e.target.closest('button'); if (b) cp(S.links[+b.dataset.i].link, b); };
$('ca').onclick = function(){ cp(S.links.map(function(l){ return l.link; }).join('\n'), this); };
$('cs').onclick = function(){ cp(S.sub, this); };
render();
setInterval(function(){
  if (document.hidden) return;
