/* ==================== ساخت پنل روی اکانت کلودفلر کاربر (بدون ذخیره‌ی توکن) ==================== */
function pb_parse_token($raw, &$acc) {
    $acc = '';
    $parts = preg_split('/[\s,;|]+/', trim((string)$raw), -1, PREG_SPLIT_NO_EMPTY);
    if (isset($parts[1])) $acc = $parts[1];
    return (string)($parts[0] ?? '');
}
function pb_verify_token($tok, $accIn) {
    if (!preg_match('/^[A-Za-z0-9_\-]{30,80}$/', $tok)) return ['ok' => false, 'error' => 'فرمت توکن درست نیست'];
    if ($accIn !== '' && !preg_match('/^[a-f0-9]{32}$/i', $accIn)) return ['ok' => false, 'error' => 'Account ID باید ۳۲ کاراکتر هگزادسیمال باشه'];
    global $db;
    /* این مسیر عمومی است و کاربر هنوز وارد حساب سایت نشده؛ قبلاً متغیر $me
       اینجا تعریف نشده بود و باعث HTTP 500 می‌شد که مرورگر آن را «خطای شبکه» نشان می‌داد. */
    if ($accIn !== '') {
        $existing = $db->prepare('SELECT account_id FROM cf_accts WHERE account_id=? LIMIT 1');
        $existing->execute([$accIn]);
        if ($existing->fetchColumn()) return ['ok'=>false,'duplicate'=>true,'error'=>'این Account قبلاً روی روبات ثبت شده است'];
    }
    $v = cf_req($tok, 'GET', '/user/tokens/verify');
    if (!empty($v['net'])) return ['ok' => false, 'error' => 'ارتباط سرور با کلودفلر برقرار نشد'];
    $okTok = !empty($v['success']) && ($v['result']['status'] ?? '') === 'active';
    if (!$okTok && $accIn !== '') {
        $v2 = cf_req($tok, 'GET', '/accounts/' . rawurlencode($accIn) . '/tokens/verify');
        $okTok = !empty($v2['success']) && ($v2['result']['status'] ?? '') === 'active';
    }
    if (!$okTok) return ['ok' => false, 'error' => 'توکن نامعتبر یا غیرفعاله'];
    $accId = $accIn; $accName = 'Cloudflare';
    if ($accId === '') {
        $l = cf_req($tok, 'GET', '/accounts?per_page=5');
        $res = $l['result'] ?? [];
        if (empty($l['success']) || !is_array($res) || !count($res)) return ['ok' => false, 'error' => 'Account ID پیدا نشد؛ بعد از توکن یک فاصله بذار و Account ID رو هم بنویس'];
        $accId = (string)$res[0]['id']; $accName = (string)($res[0]['name'] ?? 'Cloudflare');
    }
    $t = cf_req($tok, 'GET', '/accounts/' . rawurlencode($accId) . '/workers/scripts');
    if (empty($t['success'])) return ['ok' => false, 'error' => 'دسترسی Workers Scripts: Edit لازمه؛ با «ساخت توکن سریع» توکن بساز. ' . cf_err($t)];
    $d1t = cf_req($tok, 'GET', '/accounts/' . rawurlencode($accId) . '/d1/database?per_page=1');
    if (empty($d1t['success'])) return ['ok' => false, 'error' => 'دسترسی D1: Edit لازمه؛ با «ساخت توکن سریع» توکن بساز'];
    $sd = cf_req($tok, 'GET', '/accounts/' . rawurlencode($accId) . '/workers/subdomain');
    $sub = (string)($sd['result']['subdomain'] ?? '');
    if ($sub === '') {
        $c = cf_req($tok, 'PUT', '/accounts/' . rawurlencode($accId) . '/workers/subdomain', ['subdomain' => 'u' . bin2hex(random_bytes(5))]);
        $sub = (string)($c['result']['subdomain'] ?? '');
        if ($sub === '') return ['ok' => false, 'error' => 'ساخت ساب‌دامین workers.dev ناموفق بود؛ یک‌بار وارد Workers & Pages داشبورد کلودفلر شو'];
    }
    return ['ok' => true, 'account_id' => $accId, 'account_name' => mb_substr($accName, 0, 60), 'subdomain' => $sub];
}
function pb_pass($n = 12) {
    $al = 'abcdefghjkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789'; $s = '';
    for ($i = 0; $i < $n; $i++) $s .= $al[random_int(0, strlen($al) - 1)];
    return $s;
}
function pb_worker_name() {
    $al = 'abcdefghijklmnopqrstuvwxyz0123456789'; $s = $al[random_int(0, 25)];
    for ($i = 0; $i < 11; $i++) $s .= $al[random_int(0, strlen($al) - 1)];
    return $s;
}
/* سورس ورکر فشرده می‌شه (حذف تورفتگی و کامنت‌های تک‌خطی) تا توی داشبورد کاربر خوانا نباشه */
function pb_worker_src() {
    /* سایت و ربات باید دقیقاً یک قالب Worker داشته باشند؛ قالب اصلی VPN/Panel استفاده می‌شود. */
    $s = cf_template('vpn');
    $s = preg_replace('#^[ \t]*/\*.*?\*/[ \t]*$#m', '', $s);
    $s = preg_replace('/^[ \t]+/m', '', $s);
    $s = preg_replace("/\n{2,}/", "\n", $s);
    return $s;
