function jdate($ts, $t = true) {
    $gy = (int)date('Y', $ts); $gm = (int)date('n', $ts); $gd = (int)date('j', $ts);
    $g = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];
    $gy2 = ($gm > 2) ? ($gy + 1) : $gy;
    $days = 355666 + (365 * $gy) + (int)(($gy2 + 3) / 4) - (int)(($gy2 + 99) / 100) + (int)(($gy2 + 399) / 400) + $gd + $g[$gm - 1];
    $jy = -1595 + (33 * (int)($days / 12053)); $days %= 12053;
    $jy += 4 * (int)($days / 1461); $days %= 1461;
    if ($days > 365) { $jy += (int)(($days - 1) / 365); $days = ($days - 1) % 365; }
    if ($days < 186) { $jm = 1 + (int)($days / 31); $jd = 1 + ($days % 31); } else { $jm = 7 + (int)(($days - 186) / 30); $jd = 1 + (($days - 186) % 30); }
    return sprintf('%04d/%02d/%02d', $jy, $jm, $jd) . ($t ? date(' H:i', $ts) : '');
}
function need_human() { return st('captcha_on', '1') !== '0'; }
function human() { return !empty($_SESSION['human']) && $_SESSION['human'] > time() - 1800; }
function human_ok() { return !need_human() || human(); }
function rand_str($n = 6) { $al = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789'; $s = ''; for ($i = 0; $i < $n; $i++) $s .= $al[random_int(0, strlen($al) - 1)]; return $s; }
function rand_num($n = 6) { $s = ''; for ($i = 0; $i < $n; $i++) $s .= random_int(0, 9); return $s; }

/* ==================== توابع امنیتی ==================== */
function aes_encrypt($plain) {
    if ($plain === '' || $plain === null) return '';
    $iv = random_bytes(12); $tag = '';
    $ct = openssl_encrypt($plain, AES_CIPHER, AES_KEY, OPENSSL_RAW_DATA, $iv, $tag, '', 16);
    if ($ct === false) return '';
    return base64_encode($iv . $tag . $ct);
}
function aes_decrypt($enc) {
    if ($enc === '' || $enc === null) return '';
    $raw = base64_decode($enc, true);
    if ($raw === false || strlen($raw) < 28) return '';
    $iv = substr($raw, 0, 12); $tag = substr($raw, 12, 16); $ct = substr($raw, 28);
    $pt = openssl_decrypt($ct, AES_CIPHER, AES_KEY, OPENSSL_RAW_DATA, $iv, $tag);
    return $pt === false ? '' : $pt;
}
function fp_hash() {
    $ua = $_SERVER['HTTP_USER_AGENT'] ?? '';
    $lang = $_SERVER['HTTP_ACCEPT_LANGUAGE'] ?? '';
    $enc = $_SERVER['HTTP_ACCEPT_ENCODING'] ?? '';
    return substr(hash('sha256', $ua . '|' . $lang . '|' . $enc), 0, 32);
}
function fp_check($stored) { if (!$stored) return true; return substr($stored, 0, 24) === substr(fp_hash(), 0, 24); }
function ip_rep_get($ipaddr = null) {
    global $db;
    $ipaddr = $ipaddr ?: ip();
    $s = $db->prepare('SELECT * FROM ip_reputation WHERE ip=?'); $s->execute([$ipaddr]);
    $r = $s->fetch(PDO::FETCH_ASSOC);
    if (!$r) return ['ip' => $ipaddr, 'score' => 0, 'fails' => 0, 'successes' => 0, 'banned_until' => 0];
    return $r;
}
function ip_rep_update($delta, $type = 'neutral') {
    global $db, $MAX_LOGIN_FAILS, $BAN_DURATION;
    $ipaddr = ip();
    $r = ip_rep_get($ipaddr);
    $newScore = max(-100, min(100, (int)$r['score'] + $delta));
    $fails = (int)$r['fails'] + ($type === 'fail' ? 1 : 0);
    $succ = (int)$r['successes'] + ($type === 'success' ? 1 : 0);
    $bannedUntil = (int)$r['banned_until'];
    if ($newScore <= -50 && $fails >= $MAX_LOGIN_FAILS) $bannedUntil = time() + $BAN_DURATION;
    $db->prepare('REPLACE INTO ip_reputation(ip,score,fails,successes,last_seen,banned_until,notes) VALUES(?,?,?,?,?,?,?)')
       ->execute([$ipaddr, $newScore, $fails, $succ, time(), $bannedUntil, $r['notes'] ?? '']);
}
function ip_is_bad() { $r = ip_rep_get(); return (int)$r['banned_until'] > time() || (int)$r['score'] <= -80; }
function audit($action, $detail = '', $severity = 'info') {
    global $db;
    $db->prepare('INSERT INTO audit_log(ts,email,guest_token,ip,fp,action,detail,severity) VALUES(?,?,?,?,?,?,?,?)')
       ->execute([time(), $_SESSION['email'] ?? '', $_SESSION['guest'] ?? '', ip(), fp_hash(), mb_substr($action, 0, 60), mb_substr((string)$detail, 0, 500), $severity]);
}
function session_register() {
    global $db;
    $sid = session_id(); if (!$sid) return;
    $ex = $db->prepare('SELECT created,revoked FROM sessions WHERE sid=?'); $ex->execute([$sid]);
    $exRow = $ex->fetch(PDO::FETCH_ASSOC);
    $created = $exRow ? (int)$exRow['created'] : 0;
    $revoked = $exRow ? (int)$exRow['revoked'] : 0; // وضعیت «باطل‌شده» با هر درخواست پاک نشود
    if (!$created) $created = time();
    $db->prepare('REPLACE INTO sessions(sid,email,guest_token,fp,ip,ua,created,last,revoked) VALUES(?,?,?,?,?,?,?,?,?)')
       ->execute([$sid, $_SESSION['email'] ?? '', $_SESSION['guest'] ?? '', fp_hash(), ip(), mb_substr($_SERVER['HTTP_USER_AGENT'] ?? '', 0, 200), $created, time(), $revoked]);
}
function session_validate() {
    global $db, $SESSION_TTL;
    $sid = session_id(); if (!$sid) return true;
    $s = $db->prepare('SELECT * FROM sessions WHERE sid=?'); $s->execute([$sid]);
    $r = $s->fetch(PDO::FETCH_ASSOC);
    if (!$r) return true;
    if ((int)$r['revoked']) return false;
    if ((int)$r['last'] < time() - $SESSION_TTL) return false;
    if (!fp_check($r['fp'])) return false;
    // چک تغییر IP
    $initialIp = $_SESSION['initial_ip'] ?? '';
    if ($initialIp && $initialIp !== ip()) return 'ip_change';
    $db->prepare('UPDATE sessions SET last=? WHERE sid=?')->execute([time(), $sid]);
    return true;
}
function totp_secret() {
    $a = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'; $s = '';
    for ($i = 0; $i < 32; $i++) $s .= $a[random_int(0, 31)];
    return $s;
}
function base32_decode($b32) {
    $map = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'; $b32 = strtoupper($b32); $bits = '';
    for ($i = 0; $i < strlen($b32); $i++) { $p = strpos($map, $b32[$i]); if ($p === false) continue; $bits .= str_pad(decbin($p), 5, '0', STR_PAD_LEFT); }
    $out = '';
    for ($i = 0; $i + 8 <= strlen($bits); $i += 8) $out .= chr(bindec(substr($bits, $i, 8)));
    return $out;
}
function totp_code($secret, $timeSlice = null) {
    $timeSlice = $timeSlice ?: floor(time() / 30);
    $key = base32_decode($secret);
    $data = pack('N*', 0) . pack('N*', $timeSlice);
    $hmac = hash_hmac('sha1', $data, $key, true);
    $offset = ord($hmac[strlen($hmac) - 1]) & 0x0F;
    $code = (((ord($hmac[$offset]) & 0x7F) << 24) | ((ord($hmac[$offset + 1]) & 0xFF) << 16) | ((ord($hmac[$offset + 2]) & 0xFF) << 8) | (ord($hmac[$offset + 3]) & 0xFF)) % 1000000;
    return str_pad((string)$code, 6, '0', STR_PAD_LEFT);
}
function totp_verify($secret, $code, $window = 1) {
    $code = preg_replace('/\D/', '', $code);
    if (strlen($code) !== 6) return false;
    $now = floor(time() / 30);
    for ($i = -$window; $i <= $window; $i++) if (hash_equals(totp_code($secret, $now + $i), $code)) return true;
    return false;
}
function totp_uri($secret, $email, $issuer = null) {
    global $TOTP_ISSUER;
    $issuer = $issuer ?: $TOTP_ISSUER;
    return 'otpauth://totp/' . rawurlencode($issuer . ':' . $email) . '?secret=' . $secret . '&issuer=' . rawurlencode($issuer) . '&algorithm=SHA1&digits=6&period=30';
}
function totp_backup_codes($n = 8) {
    $codes = [];
    for ($i = 0; $i < $n; $i++) $codes[] = strtoupper(bin2hex(random_bytes(5)));
    return $codes;
}
function is_likely_bot() {
    $ua = $_SERVER['HTTP_USER_AGENT'] ?? '';
    if ($ua === '' || strlen($ua) < 20) return true;
    $bots = ['curl', 'wget', 'python', 'scrapy', 'bot', 'spider', 'crawler', 'headless', 'phantom', 'selenium', 'puppeteer'];
    $uaL = strtolower($ua);
    foreach ($bots as $b) if (strpos($uaL, $b) !== false) return true;
    if (empty($_SERVER['HTTP_ACCEPT_LANGUAGE'])) return true;
    if (empty($_SERVER['HTTP_ACCEPT'])) return true;
    return false;
}
function csrf_token() {
    if (!empty($_SESSION['csrf_token'])) return $_SESSION['csrf_token'];
    /* GET صفحه اصلی با Session به‌صورت read-only باز می‌شود تا قفل Session باعث
       Timeout نشود؛ در این حالت توکن CSRF را در کوکی امن نگه می‌داریم. */
    if (session_status() !== PHP_SESSION_ACTIVE) {
        $t = bin2hex(random_bytes(32));
        @setcookie('csrf_ro', $t, [
            'expires' => time() + 86400, 'path' => '/', 'secure' => (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off'),
            'httponly' => true, 'samesite' => 'Lax'
        ]);
        return $t;
    }
    $_SESSION['csrf_token'] = bin2hex(random_bytes(32));
    return $_SESSION['csrf_token'];
}
function csrf_check($token) {
    $expected = (string)($_SESSION['csrf_token'] ?? '');
    if ($expected === '' && !empty($_COOKIE['csrf_ro'])) $expected = (string)$_COOKIE['csrf_ro'];
    return $expected !== '' && hash_equals($expected, (string)$token);
}
function guest_current() {
    return ''; // ورود مهمان حذف شد
    if (empty($_SESSION['guest'])) return '';
    global $db, $GUEST_TTL;
    $s = $db->prepare('SELECT * FROM guests WHERE token=?'); $s->execute([$_SESSION['guest']]);
    $r = $s->fetch(PDO::FETCH_ASSOC);
    if (!$r) { unset($_SESSION['guest']); return ''; }
    if ((int)$r['last'] < time() - $GUEST_TTL) { unset($_SESSION['guest']); return ''; }
    $db->prepare('UPDATE guests SET last=? WHERE token=?')->execute([time(), $r['token']]);
    return $r['token'];
}
function guest_create() {
    global $db;
    $token = bin2hex(random_bytes(24));
    $db->prepare('INSERT INTO guests(token,sid,ip,fp,created,last,data) VALUES(?,?,?,?,?,?,?)')
       ->execute([$token, session_id(), ip(), fp_hash(), time(), time(), '{}']);
    session_regenerate_id(true);
    $_SESSION['guest'] = $token;
    $_SESSION['initial_ip'] = ip();
    session_register();
    audit('guest_create', 'مهمان جدید', 'info');
    return $token;
