    global $db;
    $g = guest_current();
    if (!$g) return;
    $db->prepare('UPDATE guests SET converted_to=? WHERE token=?')->execute([$email, $g]);
    $db->prepare('UPDATE favorites SET email=?, guest_token=NULL WHERE guest_token=?')->execute([$email, $g]);
    $db->prepare('UPDATE notifications SET email=?, guest_token=NULL WHERE guest_token=?')->execute([$email, $g]);
    $db->prepare('UPDATE reports SET email=?, guest_token=NULL WHERE guest_token=?')->execute([$email, $g]);
    unset($_SESSION['guest']);
    audit('guest_convert', 'تبدیل مهمان به ' . $email, 'info');
}
function notify($title, $body = '', $mail = true) {
    global $db;
    $email = $_SESSION['email'] ?? '';
    $guest = $_SESSION['guest'] ?? '';
    if (!$email && !$guest) return;
    $db->prepare('INSERT INTO notifications(email,guest_token,title,body,created) VALUES(?,?,?,?,?)')
       ->execute([$email ?: null, $guest ?: null, mb_substr($title, 0, 100), mb_substr($body, 0, 500), time()]);
    if ($email && $mail) notify_mail($email, $title, $body);
}

/* ==================== 2FA کاربران ==================== */
function user_2fa_get($email) {
    global $db;
    $s = $db->prepare('SELECT * FROM user_2fa WHERE email=?'); $s->execute([$email]);
    return $s->fetch(PDO::FETCH_ASSOC);
}
function user_2fa_enabled($email) {
    $r = user_2fa_get($email);
    return $r && (int)$r['enabled'] === 1;
}
function user_2fa_verify_code($email, $code) {
    $r = user_2fa_get($email);
    if (!$r || !(int)$r['enabled']) return false;
    $rawCode = trim((string)$code);
    $numericCode = preg_replace('/\D/', '', $rawCode);
    if (strlen($numericCode) === 6 && totp_verify($r['secret'], $numericCode)) return true;
    if (!empty($r['backup_codes'])) {
        $codes = json_decode($r['backup_codes'], true) ?: [];
        $idx = array_search(strtoupper($rawCode), $codes, true);
        if ($idx !== false) {
            unset($codes[$idx]);
            global $db;
            $db->prepare('UPDATE user_2fa SET backup_codes=? WHERE email=?')->execute([json_encode(array_values($codes)), $email]);
            audit('user_2fa_backup_used', $email, 'warn');
            return true;
        }
    }
    return false;
}

