/* ==================== ورود کاربر ==================== */
function loginUser($email, $m, $name = '', $avatar = '') {
    global $db;
    $s = $db->prepare('SELECT blocked FROM users WHERE email=?'); $s->execute([$email]); $r = $s->fetch(PDO::FETCH_ASSOC);
    if ($r && (int)$r['blocked']) return 'حساب شما مسدود شده است';
    if (!$r && st('allow_reg', '1') === '0') return 'ثبت‌نام بسته است';

    if (user_2fa_enabled($email)) {
        $_SESSION['pending_2fa_email']  = $email;
        $_SESSION['pending_2fa_method'] = $m;
        $_SESSION['pending_2fa_name']   = $name;
        $_SESSION['pending_2fa_avatar'] = $avatar;
        $_SESSION['pending_2fa_time']   = time();
        $_SESSION['pending_2fa_fails']  = 0;
        audit('login_need_2fa', $email, 'info');
        return ['need_2fa' => true];
    }

    guest_to_user($email);
    session_regenerate_id(true);
    $_SESSION['email'] = $email;
    $_SESSION['initial_ip'] = ip();
    $db->prepare('INSERT OR IGNORE INTO users(email,method,first,last,logins,blocked,name,avatar) VALUES(?,?,?,?,0,0,?,?)')->execute([$email, $m, time(), time(), $name, $avatar]);
    $db->prepare('UPDATE users SET last=?,logins=logins+1,method=?,name=COALESCE(NULLIF(?,\'\'),name),avatar=COALESCE(NULLIF(?,\'\'),avatar) WHERE email=?')->execute([time(), $m, $name, $avatar, $email]);
    $isNewDev = !login_known_device($email);
    logev('login', $m);
    ip_rep_update(5, 'success');
    audit('login', $m, 'info');
    session_register();
    notify('ورود جدید به حساب', ua_label($_SERVER['HTTP_USER_AGENT'] ?? '', false) . ' — ' . ip(), false);
    login_alert($email, $m, $isNewDev);
    return true;
}
function cur_user() {
    global $db;
    if (empty($_SESSION['email'])) return '';
    $s = $db->prepare('SELECT blocked FROM users WHERE email=?'); $s->execute([$_SESSION['email']]);
    $r = $s->fetch(PDO::FETCH_ASSOC);
    if (!$r || (int)$r['blocked']) { unset($_SESSION['email']); return ''; }
    return $_SESSION['email'];
}
function is_guest() { return !cur_user() && !empty($_SESSION['guest']); }
function is_logged_in() { return (bool)cur_user(); }

/* ==================== ابزارهای امنیت حساب: دستگاه، لینک، ایمیل اطلاع‌رسانی ==================== */
function smtp_ready() {
    global $SMTP_HOST, $SMTP_USER, $SMTP_PASS;
    return st('smtp_host', $SMTP_HOST) !== '' && st('smtp_user', $SMTP_USER) !== '' && st('smtp_pass', $SMTP_PASS) !== '';
}
function ua_label($ua, $icon = true) {
    $ua = (string)$ua;
    if ($ua === '') return 'دستگاه ناشناس';
    $os = 'سیستم ناشناس';
    if (preg_match('/Windows/i', $ua)) $os = 'Windows';
    elseif (preg_match('/Android\s?([\d.]+)?/i', $ua, $mm)) $os = 'Android' . (!empty($mm[1]) ? ' ' . $mm[1] : '');
    elseif (preg_match('/iPhone|iPad|iPod/i', $ua)) $os = 'iOS';
    elseif (preg_match('/Mac OS X|Macintosh/i', $ua)) $os = 'macOS';
    elseif (preg_match('/CrOS/i', $ua)) $os = 'ChromeOS';
    elseif (preg_match('/Linux/i', $ua)) $os = 'Linux';
    $br = 'مرورگر ناشناس';
    if (preg_match('/Edg(e|A|iOS)?\//i', $ua)) $br = 'Edge';
    elseif (preg_match('/OPR\/|Opera/i', $ua)) $br = 'Opera';
    elseif (preg_match('/SamsungBrowser/i', $ua)) $br = 'Samsung Internet';
    elseif (preg_match('/Firefox|FxiOS/i', $ua)) $br = 'Firefox';
    elseif (preg_match('/Chrome|CriOS/i', $ua)) $br = 'Chrome';
    elseif (preg_match('/Safari/i', $ua)) $br = 'Safari';
    $ic = preg_match('/iPad|Tablet/i', $ua) ? '📲' : (preg_match('/Mobile|Android|iPhone|iPod/i', $ua) ? '📱' : '💻');
    return ($icon ? $ic . ' ' : '') . $br . ' روی ' . $os;
}
function geoip_cached($ipaddr) {
    if (!filter_var($ipaddr, FILTER_VALIDATE_IP)) return '';
    $f = __DIR__ . '/data/geo_' . md5($ipaddr) . '.json';
    if (!is_file($f)) return '';
    $c = json_decode((string)@file_get_contents($f), true);
    if (!is_array($c)) return '';
    return trim(($c['city'] ?? '') . '، ' . ($c['country'] ?? ''), '، ');
}
function sess_pub($sid) { return substr(hash_hmac('sha256', (string)$sid, AES_KEY ?: 'k'), 0, 20); }
function account_url() {
    global $https;
    $cfg = trim(st('site_url', ''));
    if ($cfg !== '' && preg_match('#^https?://[A-Za-z0-9.\-:\[\]]+(/[A-Za-z0-9._~/%\-]*)?$#', $cfg)) {
        $u = rtrim($cfg, '/');
        if (!preg_match('/\.php$/i', $u)) $u .= '/';
        return $u . '#account';
    }
    $host = (string)($_SERVER['HTTP_HOST'] ?? '');
    if (!preg_match('/^[A-Za-z0-9.\-]+(:\d{1,5})?$/', $host)) return '';
    $path = preg_replace('#[^A-Za-z0-9._~/%\-]#', '', (string)strtok((string)($_SERVER['REQUEST_URI'] ?? '/'), '?'));
    if ($path === '') $path = '/';
    return ($https ? 'https' : 'http') . '://' . $host . $path . '#account';
}
function login_known_device($email) {
    global $db;
    $s = $db->prepare("SELECT COUNT(*) FROM audit_log WHERE email=? AND fp=? AND action IN ('login','login_2fa')");
    $s->execute([$email, fp_hash()]);
    return (int)$s->fetchColumn() > 0;
}

/* اجرای کارها بعد از ارسال پاسخ به مرورگر (تا ارسال ایمیل ورود را کند نکند) */
$GLOBALS['__after_q'] = [];
function after_response(callable $fn) {
    $GLOBALS['__after_q'][] = $fn;
    static $reg = false;
    if ($reg) return;
    $reg = true;
    register_shutdown_function(function () {
        if (empty($GLOBALS['__after_q'])) return;
        ignore_user_abort(true);
        @set_time_limit(90);
        if (session_status() === PHP_SESSION_ACTIVE) @session_write_close();
        if (function_exists('fastcgi_finish_request')) @fastcgi_finish_request();
        foreach ($GLOBALS['__after_q'] as $f) { try { $f(); } catch (Throwable $t) {} }
    });
}

function mail_layout($title, $introHtml, $rows = [], $btnText = '', $btnUrl = '', $note = '') {
    $site = e(st('site_name', 'سایت من'));
    $h = '<div style="font-family:Tahoma,Arial,sans-serif;direction:rtl;text-align:right;background:#f4f6fc;padding:24px 12px">'
       . '<div style="max-width:520px;margin:auto;background:#ffffff;border-radius:18px;padding:28px;box-shadow:0 4px 20px rgba(0,0,0,.08)">'
       . '<h2 style="color:#2563eb;margin:0 0 14px;font-size:20px">' . e($title) . '</h2>'
       . '<div style="color:#444;line-height:1.9;font-size:14px">' . $introHtml . '</div>';
    if ($rows) {
        $h .= '<table style="width:100%;border-collapse:collapse;margin:18px 0;background:#f8faff;border-radius:12px">';
        foreach ($rows as $r) {
            $h .= '<tr><td style="padding:10px 14px;color:#777;font-size:13px;border-bottom:1px solid #e8ecf7;white-space:nowrap">' . e($r[0]) . '</td>'
                . '<td style="padding:10px 14px;color:#111;font-size:13px;border-bottom:1px solid #e8ecf7" dir="auto">' . e($r[1]) . '</td></tr>';
        }
        $h .= '</table>';
    }
    if ($btnText !== '' && $btnUrl !== '') {
        $h .= '<div style="text-align:center;margin:26px 0 10px"><a href="' . e($btnUrl) . '" style="display:inline-block;background:#2563eb;color:#ffffff;text-decoration:none;font-weight:bold;font-size:15px;padding:14px 36px;border-radius:12px">' . e($btnText) . '</a></div>';
    }
    if ($note !== '') $h .= '<p style="color:#888;font-size:12px;line-height:1.8;margin:14px 0 0">' . e($note) . '</p>';
    $h .= '<hr style="border:0;border-top:1px solid #eee;margin:22px 0 12px"><p style="color:#aaa;font-size:11px;text-align:center;margin:0">' . $site . '</p></div></div>';
    return $h;
}
function mail_text($title, $introHtml, $rows, $url) {
    $t = $title . "\n\n" . trim(html_entity_decode(strip_tags($introHtml), ENT_QUOTES, 'UTF-8')) . "\n\n";
    foreach ($rows as $r) $t .= $r[0] . ': ' . $r[1] . "\n";
    if ($url) $t .= "\n" . $url . "\n";
    return $t;
}
/* ایمیل امنیتی (ورود جدید، تغییر 2FA، حذف نشست …) — همیشه ارسال می‌شود */
function security_mail($email, $subject, $title, $introHtml, $rows = [], $button = true) {
    if (!smtp_ready()) return;
    $ip = ip();
    $ua = (string)($_SERVER['HTTP_USER_AGENT'] ?? '');
    $ts = time();
    $url = $button ? account_url() : '';
    after_response(function () use ($email, $subject, $title, $introHtml, $rows, $url, $ip, $ua, $ts) {
        $geo = geoip_lookup($ip);
        $place = $geo ? trim(($geo['city'] ?? '') . '، ' . ($geo['country'] ?? ''), '، ') : 'نامشخص';
        $all = array_merge([['دستگاه', ua_label($ua, false)], ['آی‌پی', $ip], ['موقعیت', $place], ['زمان', jdate($ts)]], $rows);
        $html = mail_layout($title, $introHtml, $all, $url !== '' ? 'مدیریت حساب' : '', $url, 'اگر این کار را شما انجام نداده‌اید، فوراً از «مدیریت حساب» نشست‌های ناشناس را حذف و تایید دو مرحله‌ای را فعال کنید.');
        smtp_send($email, $subject, $html, mail_text($title, $introHtml, $all, $url));
    });
}
function login_alert($email, $method, $isNewDevice) {
    $labels = ['google' => 'حساب گوگل', 'email' => 'کد ایمیل', 'google+2fa' => 'حساب گوگل + تایید دو مرحله‌ای', 'email+2fa' => 'کد ایمیل + تایید دو مرحله‌ای'];
    $mt = $labels[$method] ?? $method;
    $intro = '<p style="margin:0 0 10px">سلام 👋</p><p style="margin:0 0 10px">'
           . ($isNewDevice ? '<b style="color:#d97706">یک دستگاه جدید</b> وارد حساب شما شد.' : 'یک ورود جدید به حساب شما ثبت شد.')
           . '</p><p style="margin:0">اگر این شما بودید، کاری لازم نیست. اگر نبودید، با دکمه زیر نشست‌های فعال را ببینید و دستگاه ناشناس را حذف کنید.</p>';
    security_mail($email,
        ($isNewDevice ? 'ورود از دستگاه جدید' : 'ورود جدید') . ' به حساب شما',
        $isNewDevice ? '⚠️ ورود از دستگاه جدید' : '🔔 ورود جدید به حساب شما',
        $intro, [['روش ورود', $mt]], true);
}
/* ایمیل اعلان عادی (عملیات‌ها) — کاربر می‌تواند از «مدیریت حساب» خاموشش کند */
function notify_mail($email, $title, $body) {
    global $db;
    if (!smtp_ready()) return;
    $s = $db->prepare('SELECT mail_ops FROM users WHERE email=?'); $s->execute([$email]);
    $v = $s->fetchColumn();
    if ($v !== false && $v !== null && (int)$v === 0) return;
    after_response(function () use ($email, $title, $body) {
        $intro = '<p style="margin:0">' . e($body) . '</p>';
        $rows = [['زمان', jdate(time())]];
        $html = mail_layout($title, $intro, $rows, '', '', 'می‌توانید اعلان‌های ایمیلی را از بخش «مدیریت حساب» خاموش کنید.');
        smtp_send($email, $title, $html, mail_text($title, $intro, $rows, ''));
    });
}

/* ==================== ارسال ایمیل (SMTP) ==================== */
function smtp_send($to, $subject, $htmlBody, $textBody = '') {
    global $SMTP_HOST, $SMTP_PORT, $SMTP_USER, $SMTP_PASS, $SMTP_FROM, $SMTP_FROM_NAME;
    $host = st('smtp_host', $SMTP_HOST);
    $port = (int)st('smtp_port', (string)$SMTP_PORT);
    $user = st('smtp_user', $SMTP_USER);
    $pass = st('smtp_pass', $SMTP_PASS);
    $from = st('smtp_from', $SMTP_FROM) ?: $user;
    $fromName = st('smtp_from_name', $SMTP_FROM_NAME) ?: (st('site_name', 'سایت من'));
    if (!$host || !$user || !$pass) return ['ok' => false, 'error' => 'SMTP تنظیم نشده'];

    $socket = @fsockopen(($port === 465 ? 'ssl://' : '') . $host, $port, $errno, $errstr, 15);
    if (!$socket) return ['ok' => false, 'error' => "اتصال SMTP ناموفق: $errstr ($errno)"];
    stream_set_timeout($socket, 15);

    $read = function() use ($socket) { $data = ''; while ($line = fgets($socket, 515)) { $data .= $line; if (substr($line, 3, 1) === ' ') break; } return $data; };
    $write = function($cmd) use ($socket) { fwrite($socket, $cmd . "\r\n"); };

    $read();
    $write('EHLO ' . ($_SERVER['HTTP_HOST'] ?? 'localhost')); $r = $read();
    if ($port !== 465) {
        $write('STARTTLS'); $r = $read();
        if (strpos($r, '220') === 0) {
            if (!stream_socket_enable_crypto($socket, true, STREAM_CRYPTO_METHOD_TLS_CLIENT)) {
                fclose($socket); return ['ok' => false, 'error' => 'STARTTLS ناموفق'];
            }
            $write('EHLO ' . ($_SERVER['HTTP_HOST'] ?? 'localhost')); $read();
        }
    }
    $write('AUTH LOGIN'); $read();
    $write(base64_encode($user)); $read();
    $write(base64_encode($pass)); $r = $read();
    if (strpos($r, '235') !== 0) { fclose($socket); return ['ok' => false, 'error' => 'احراز هویت SMTP ناموفق']; }

    $write('MAIL FROM: <' . $from . '>'); $read();
    $write('RCPT TO: <' . $to . '>'); $read();
    $write('DATA'); $read();

    $boundary = 'b_' . bin2hex(random_bytes(8));
    $headers = "From: =?UTF-8?B?" . base64_encode($fromName) . "?= <$from>\r\n";
    $headers .= "To: <$to>\r\n";
    $headers .= "Subject: =?UTF-8?B?" . base64_encode($subject) . "?=\r\n";
    $headers .= "MIME-Version: 1.0\r\n";
    $headers .= "Content-Type: multipart/alternative; boundary=\"$boundary\"\r\n";
    $headers .= "Date: " . date('r') . "\r\n";

    $msg = $headers . "\r\n";
    $msg .= "--$boundary\r\nContent-Type: text/plain; charset=UTF-8\r\nContent-Transfer-Encoding: base64\r\n\r\n";
    $msg .= chunk_split(base64_encode($textBody ?: strip_tags($htmlBody))) . "\r\n";
    $msg .= "--$boundary\r\nContent-Type: text/html; charset=UTF-8\r\nContent-Transfer-Encoding: base64\r\n\r\n";
    $msg .= chunk_split(base64_encode($htmlBody)) . "\r\n";
    $msg .= "--$boundary--\r\n";

    $msg = preg_replace('/^\./m', '..', $msg);
    fwrite($socket, $msg . "\r\n.\r\n");
    $r = $read();
    $write('QUIT'); fclose($socket);
    return strpos($r, '250') === 0 ? ['ok' => true] : ['ok' => false, 'error' => 'ارسال ناموفق: ' . trim($r)];
}

