/* ==================== OTP ==================== */
function otp_hash($email, $code) { return hash_hmac('sha256', strtolower((string)$email) . '|' . $code, AES_KEY ?: 'k'); }
function otp_create($email, $purpose = 'login') {
    global $db, $OTP_TTL;
    $code = rand_num(6);
    // کدهای قبلیِ استفاده‌نشده باطل می‌شوند
    $db->prepare('UPDATE email_otp SET used=1 WHERE email=? AND purpose=? AND used=0')->execute([$email, $purpose]);
    $db->prepare('INSERT INTO email_otp(email,code,ts,ip,used,attempts,purpose) VALUES(?,?,?,?,0,0,?)')
       ->execute([$email, otp_hash($email, $code), time(), ip(), $purpose]);
    return $code;
}
function otp_verify($email, $code, $purpose = 'login') {
    global $db, $OTP_TTL;
    $code = preg_replace('/\D/', '', $code);
    if (strlen($code) !== 6) return ['ok' => false, 'error' => 'کد ۶ رقمی وارد کن'];
    $s = $db->prepare('SELECT * FROM email_otp WHERE email=? AND used=0 AND purpose=? ORDER BY id DESC LIMIT 1');
    $s->execute([$email, $purpose]);
    $r = $s->fetch(PDO::FETCH_ASSOC);
    if (!$r) return ['ok' => false, 'error' => 'کدی یافت نشد، دوباره درخواست بده'];
    if (time() - (int)$r['ts'] > $OTP_TTL) return ['ok' => false, 'error' => 'کد منقضی شده، دوباره درخواست بده'];
    if ((int)$r['attempts'] >= 5) return ['ok' => false, 'error' => 'تلاش زیاد، کد جدید بگیر'];
    if (!hash_equals((string)$r['code'], otp_hash($email, $code))) {
        $db->prepare('UPDATE email_otp SET attempts=attempts+1 WHERE id=?')->execute([$r['id']]);
        return ['ok' => false, 'error' => 'کد اشتباه است'];
    }
    $db->prepare('UPDATE email_otp SET used=1 WHERE id=?')->execute([$r['id']]);
    return ['ok' => true];
}

/* ==================== geoip ==================== */
function geoip_lookup($ipaddr) {
    if (!filter_var($ipaddr, FILTER_VALIDATE_IP) || $ipaddr === '127.0.0.1' || $ipaddr === '::1') return null;
    $cacheFile = __DIR__ . '/data/geo_' . md5($ipaddr) . '.json';
    if (is_file($cacheFile) && filemtime($cacheFile) > time() - 86400) {
        $c = json_decode(file_get_contents($cacheFile), true);
        if (is_array($c)) return $c;
    }
    $r = http_raw('http://ip-api.com/json/' . urlencode($ipaddr) . '?fields=status,country,countryCode,regionName,city,zip,lat,lon,timezone,isp,org,as,query', [], null, 5);
    if ($r === null) return null;
    $j = json_decode($r, true);
    if (!is_array($j) || ($j['status'] ?? '') !== 'success') return null;
    @file_put_contents($cacheFile, json_encode($j));
    return $j;
}
function is_iran_ip($ipaddr) {
    $g = geoip_lookup($ipaddr);
    if (!$g) return null;
    return ($g['countryCode'] ?? '') === 'IR';
}

/* ==================== AI ==================== */
function ai_free($msgs, $sys) {
    $full = array_merge([['role' => 'system', 'content' => $sys]], $msgs);
    $p = json_encode(['model' => 'openai', 'messages' => $full], JSON_UNESCAPED_UNICODE);
    foreach (['https://text.pollinations.ai/openai', 'https://gen.pollinations.ai/v1/chat/completions'] as $u) {
        for ($try = 0; $try < 2; $try++) {
            $r = http_raw($u, ['Content-Type: application/json'], $p, 40);
            if ($r === null) { usleep(300000); continue; }
            $j = json_decode($r, true);
            $t = $j['choices'][0]['message']['content'] ?? '';
            if (is_string($t) && trim($t) !== '') return trim($t);
            usleep(200000);
        }
    }
    return null;
}
function ai_reply($msgs, $last) {
    $site = st('site_name', 'سایت من');
    $sys = trim(st('ai_prompt')) ?: 'تو دستیار پشتیبانی سایت «' . $site . '» هستی. به فارسی، کوتاه، مودب و صمیمی جواب بده.';
    $mode = st('ai_mode', 'free');
    if ($mode === 'anthropic' && st('api_key') !== '') {
        $j = http('https://api.anthropic.com/v1/messages', ['Content-Type: application/json', 'x-api-key: ' . st('api_key'), 'anthropic-version: 2023-06-01'],
            json_encode(['model' => st('model', 'claude-haiku-4-5-20251001'), 'max_tokens' => 600, 'system' => $sys, 'messages' => $msgs], JSON_UNESCAPED_UNICODE));
        $t = $j['content'][0]['text'] ?? '';
        if (is_string($t) && trim($t) !== '') return $t;
    }
    if ($mode !== 'rules') { $t = ai_free($msgs, $sys); if ($t) return $t; }
    $t = mb_strtolower($last);
    $rules = ['سلام|درود|hi|hello' => 'سلام! 👋 چطور می‌تونم کمکت کنم؟', 'چطوری|حالت|خوبی' => 'مرسی، عالیم! 😊',
        'پشتیبانی|کمک|مشکل' => 'مشکلت رو بنویس تا راهنماییت کنم.', 'قیمت|هزینه' => 'برای اطلاع از قیمت‌ها از بخش «تماس با ما» پیام بذار.',
        'ممنون|مرسی' => 'خواهش می‌کنم! 🌹', 'خداحافظ|بای' => 'خدانگهدار! 👋'];
    foreach ($rules as $p => $ans) foreach (explode('|', $p) as $kw) if (mb_strpos($t, $kw) !== false) return $ans;
    return 'الان AI در دسترس نیست. کمی بعد امتحان کن.';
}

