function cap_shuffle(&$a) { for ($i = count($a) - 1; $i > 0; $i--) { $j = random_int(0, $i); $t = $a[$i]; $a[$i] = $a[$j]; $a[$j] = $t; } }
function cap_tile($fn) {
    $h = random_int(0, 359);
    $c = 'hsl(' . $h . ',72%,50%)'; $d = 'hsl(' . (($h + random_int(-25, 25) + 360) % 360) . ',70%,28%)';
    $b1 = 'hsl(' . random_int(0, 359) . ',40%,' . random_int(80, 92) . '%)'; $b2 = 'hsl(' . random_int(0, 359) . ',40%,' . random_int(72, 88) . '%)';
    $s = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" width="120" height="120"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="' . $b1 . '"/><stop offset="1" stop-color="' . $b2 . '"/></linearGradient></defs><rect width="100" height="100" fill="url(#g)"/>';
    for ($i = 0; $i < 4; $i++) $s .= '<path d="M' . random_int(0, 100) . ' ' . random_int(0, 100) . ' Q' . random_int(0, 100) . ' ' . random_int(0, 100) . ' ' . random_int(0, 100) . ' ' . random_int(0, 100) . '" stroke="hsl(' . random_int(0, 359) . ',50%,60%)" stroke-width="1.3" fill="none" opacity=".55"/>';
    for ($i = 0; $i < 16; $i++) $s .= '<circle cx="' . random_int(0, 100) . '" cy="' . random_int(0, 100) . '" r="' . (random_int(4, 12) / 10) . '" fill="hsl(' . random_int(0, 359) . ',50%,45%)" opacity=".5"/>';
    $s .= '<g transform="translate(' . random_int(-5, 5) . ' ' . random_int(-5, 5) . ') translate(50 50) rotate(' . random_int(-20, 20) . ') scale(' . (random_int(78, 98) / 100) . ') translate(-50 -50)">' . $fn($c, $d) . '</g>';
    for ($i = 0; $i < 3; $i++) $s .= '<line x1="' . random_int(0, 100) . '" y1="' . random_int(0, 100) . '" x2="' . random_int(0, 100) . '" y2="' . random_int(0, 100) . '" stroke="hsl(' . random_int(0, 359) . ',40%,40%)" stroke-width="0.9" opacity=".35"/>';
    return 'data:image/svg+xml;base64,' . base64_encode($s . '</svg>');
}

/* ==================== پردازش عکس ==================== */
function img_load($path, $mime) {
    global $hasGd, $hasImagick;
    if ($hasImagick) { try { return new Imagick($path); } catch (Exception $e) { return null; } }
    if (!$hasGd) return null;
    switch ($mime) {
        case 'image/jpeg': case 'image/jpg': return @imagecreatefromjpeg($path);
        case 'image/png': return @imagecreatefrompng($path);
        case 'image/webp': return function_exists('imagecreatefromwebp') ? @imagecreatefromwebp($path) : null;
        case 'image/gif': return @imagecreatefromgif($path);
    }
    return null;
}
function img_save($im, $path, $mime, $quality = 92) {
    global $hasImagick;
    if ($hasImagick && $im instanceof Imagick) {
        switch ($mime) {
            case 'image/jpeg': $im->setImageFormat('jpeg'); $im->setImageCompressionQuality($quality); break;
            case 'image/png': $im->setImageFormat('png'); break;
            case 'image/webp': $im->setImageFormat('webp'); $im->setImageCompressionQuality($quality); break;
        }
        return $im->writeImage($path);
    }
    switch ($mime) {
        case 'image/jpeg': return imagejpeg($im, $path, $quality);
        case 'image/png': return imagepng($im, $path, 8);
        case 'image/webp': return function_exists('imagewebp') ? imagewebp($im, $path, $quality) : imagejpeg($im, $path, $quality);
    }
    return false;
}
function img_destroy($im) {
    if ($im instanceof Imagick) { $im->clear(); return; }
    if (is_resource($im) || (is_object($im) && get_class($im) === 'GdImage')) @imagedestroy($im);
}
function img_dimensions($im) {
    if ($im instanceof Imagick) return [$im->getImageWidth(), $im->getImageHeight()];
    return [imagesx($im), imagesy($im)];
}
function img_upscale_gd($src_im, $factor) {
    global $hasImagick;
    if ($hasImagick && $src_im instanceof Imagick) {
        $w = $src_im->getImageWidth(); $h = $src_im->getImageHeight();
        $src_im->resizeImage($w * $factor, $h * $factor, Imagick::FILTER_LANCZOS, 1, false);
        $src_im->unsharpMaskImage(0, 0.6, 0.8, 0.05);
        return $src_im;
    }
    list($w, $h) = img_dimensions($src_im);
    $nw = $w * $factor; $nh = $h * $factor;
    $dst = imagecreatetruecolor($nw, $nh);
    imagealphablending($dst, false); imagesavealpha($dst, true);
    imagecopyresampled($dst, $src_im, 0, 0, 0, 0, $nw, $nh, $w, $h);
    $sharpen = [[0, -1, 0], [-1, 5, -1], [0, -1, 0]];
    @imageconvolution($dst, $sharpen, 1, 0);
    return $dst;
}

function short_url_base() {
    $scheme = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ? 'https' : 'http';
    $host = $_SERVER['HTTP_HOST'] ?? 'localhost';
    $path = dirname($_SERVER['SCRIPT_NAME']);
    if ($path === '/' || $path === '\\') $path = '';
    return $scheme . '://' . $host . $path . '/s.php';
}

/* ==================== VPN: هسته‌ی چنداکانتی + لینک ساب روی دامنه‌ی خودت ==================== */
const VPN_D1_SCHEMA = 'CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,uuid TEXT UNIQUE,token TEXT UNIQUE,limit_bytes INTEGER DEFAULT 0,used INTEGER DEFAULT 0,expire INTEGER DEFAULT 0,active INTEGER DEFAULT 1,created INTEGER,last INTEGER DEFAULT 0,cfgs TEXT DEFAULT "[]");CREATE TABLE IF NOT EXISTS settings(k TEXT PRIMARY KEY,v TEXT);CREATE TABLE IF NOT EXISTS sessions(t TEXT PRIMARY KEY,exp INTEGER);CREATE TABLE IF NOT EXISTS fails(ip TEXT,ts INTEGER);CREATE TABLE IF NOT EXISTS daily(day TEXT PRIMARY KEY,conns INTEGER DEFAULT 0,bytes INTEGER DEFAULT 0)';

function vpn_loc($code) {
    global $VPN_LOCATIONS;
    foreach ($VPN_LOCATIONS as $l) { if ($l['code'] === $code) return $l; }
    return null;
}
function vpn_uuid() {
    $d = random_bytes(16);
    $d[6] = chr((ord($d[6]) & 0x0f) | 0x40);
    $d[8] = chr((ord($d[8]) & 0x3f) | 0x80);
    $h = bin2hex($d);
    return substr($h, 0, 8) . '-' . substr($h, 8, 4) . '-' . substr($h, 12, 4) . '-' . substr($h, 16, 4) . '-' . substr($h, 20);
}
function vpn_base_url() {
    global $VPN_BASE_URL, $https;
    $cfg = trim(st('vpn_base_url', $VPN_BASE_URL));
    if ($cfg !== '' && preg_match('#^https?://[A-Za-z0-9.\-]+(:\d{1,5})?(/[A-Za-z0-9._~/\-]*)?$#', $cfg)) return rtrim($cfg, '/');
    $host = (string)($_SERVER['HTTP_HOST'] ?? '');
    if (!preg_match('/^[A-Za-z0-9.\-]+(:\d{1,5})?$/', $host)) $host = 'localhost';
    $dir = rtrim(str_replace('\\', '/', dirname((string)($_SERVER['SCRIPT_NAME'] ?? '/'))), '/');
    return ($https ? 'https' : 'http') . '://' . $host . $dir;
}
function vpn_sub_url($token) { return vpn_base_url() . '/' . basename((string)($_SERVER['SCRIPT_NAME'] ?? 'index.php')) . '?sub=' . rawurlencode((string)$token); }
function vpn_sub_url_alt($token) { return vpn_base_url() . '/' . basename((string)($_SERVER['SCRIPT_NAME'] ?? 'index.php')) . '?sub=' . $token . '&format=base64'; }
function panel_site_url($token) {
    global $db;
    $tok = (string)$token;
    try {
        $q = $db->prepare('SELECT id FROM vpn_services WHERE token=? LIMIT 1'); $q->execute([$tok]); $sid = $q->fetchColumn();
        if ($sid) { $n = vpn_nodes_of((int)$sid); $h = (string)($n[0]['host'] ?? ''); if ($h !== '') return 'https://' . rtrim($h, '/') . '/' . ltrim((string)($n[0]['panel'] ?? 'panel'), '/'); }
    } catch (Throwable $e) {}
    try {
        $q = $db->prepare('SELECT worker_url FROM panel_records WHERE public_token=? LIMIT 1'); $q->execute([$tok]); $u = (string)$q->fetchColumn();
        if ($u !== '') return $u;
    } catch (Throwable $e) {}
    return '';
}
function panel_save_record($worker, $workerUrl, $password, $publicToken = '', $cfToken = '', $accountId = '', $d1Id = '') {
    global $db, $PANEL_VERSION;
    $tok = $publicToken !== '' ? $publicToken : bin2hex(random_bytes(16));
    $db->prepare('INSERT INTO panel_records(public_token,worker,worker_url,site_url,password_hint,created,active,cf_token_enc,account_id,d1_id,panel_version) VALUES(?,?,?,?,?,?,?,?,?,?,?)')
       ->execute([$tok, $worker, $workerUrl, $workerUrl, $password !== '' ? password_hash($password, PASSWORD_DEFAULT) : '', time(), 1, $cfToken !== '' ? aes_encrypt($cfToken) : '', $accountId, $d1Id, $PANEL_VERSION]);
    return [$tok, $workerUrl];
}
function panel_update_endpoint_url() {
    $base = rtrim((string)st('site_url', ''), '/');
    if ($base === '') {
        $scheme = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ? 'https' : 'http';
        $base = $scheme . '://' . ($_SERVER['HTTP_HOST'] ?? '');
    }
    $base = preg_replace('#/index\.php$#i', '', $base);
    return rtrim($base, '/') . '/index.php?panel_update=1';
}

function d1_q($tok, $acc, $d1, $sql, $params = []) {
    $body = ['sql' => $sql];
    if ($params) $body['params'] = array_values($params);
    return cf_req($tok, 'POST', '/accounts/' . rawurlencode($acc) . '/d1/database/' . rawurlencode($d1) . '/query', $body);
}
function d1_rows($r) {
    $x = $r['result'][0]['results'] ?? [];
    return is_array($x) ? $x : [];
}

function panel_d1_admin_state($pr) {
    $ct=aes_decrypt((string)($pr['cf_token_enc']??'')); $acc=(string)($pr['account_id']??''); $d1=(string)($pr['d1_id']??'');
    if($ct===''||$acc===''||$d1==='') return ['ok'=>false,'error'=>'اطلاعات اتصال پنل ناقص است'];
    $q=d1_q($ct,$acc,$d1,"CREATE TABLE IF NOT EXISTS settings(k TEXT PRIMARY KEY,v TEXT)");
    if(empty($q['success'])) return ['ok'=>false,'error'=>cf_err($q)];
    d1_q($ct,$acc,$d1,"CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,uuid TEXT UNIQUE,token TEXT UNIQUE,limit_bytes INTEGER DEFAULT 0,used INTEGER DEFAULT 0,expire INTEGER DEFAULT 0,active INTEGER DEFAULT 1,created INTEGER,last INTEGER DEFAULT 0)");
    $qs=d1_q($ct,$acc,$d1,"SELECT k,v FROM settings WHERE k IN ('global_panel_enabled','global_servers_enabled','panel_theme')");
    $st=['global_panel_enabled'=>'1','global_servers_enabled'=>'1','panel_theme'=>'dark'];
    foreach(d1_rows($qs) as $r) $st[(string)$r['k']]=(string)$r['v'];
    $qu=d1_q($ct,$acc,$d1,"SELECT COUNT(*) c FROM users"); $ur=d1_rows($qu); $users=(int)($ur[0]['c']??0);
    return ['ok'=>true,'panel_open'=>$st['global_panel_enabled']!=='0','servers_open'=>$st['global_servers_enabled']!=='0','theme'=>$st['panel_theme'],'users'=>$users];
}
function panel_admin_set_all($key,$value) {
    global $db;
    $rows=$db->query("SELECT * FROM panel_records WHERE active=1 ORDER BY id")->fetchAll(PDO::FETCH_ASSOC); $ok=0;$fail=0;
    $started=microtime(true); foreach($rows as $pr){ if(microtime(true)-$started>24){$fail += max(0,count($rows)-$ok-$fail); break;} $ct=aes_decrypt((string)($pr['cf_token_enc']??''));$acc=(string)($pr['account_id']??'');$d1=(string)($pr['d1_id']??'');if($ct===''||$acc===''||$d1===''){$fail++;continue;} $q=d1_q($ct,$acc,$d1,"REPLACE INTO settings(k,v) VALUES(?,?)",[$key,$value]); if(!empty($q['success']))$ok++;else$fail++;}
    return [$ok,$fail,count($rows)];
}
function panel_admin_update_all() {
    global $db,$PANEL_VERSION;
    $rows=$db->query("SELECT * FROM panel_records WHERE active=1 ORDER BY id")->fetchAll(PDO::FETCH_ASSOC); $ok=0;$fail=0;
    foreach($rows as $pr){$ct=aes_decrypt((string)($pr['cf_token_enc']??''));$acc=(string)($pr['account_id']??'');$d1=(string)($pr['d1_id']??'');$wk=(string)($pr['worker']??'');if($ct===''||$acc===''||$d1===''||$wk===''){$fail++;continue;}
        $aq=$db->prepare("SELECT subdomain FROM cf_accts WHERE account_id=? AND status='ok' ORDER BY id LIMIT 1");$aq->execute([$acc]);$sub=(string)($aq->fetchColumn()?:'');
        $bind=[['type'=>'d1','name'=>'DB','id'=>$d1],['type'=>'secret_text','name'=>'CF_API_TOKEN','text'=>$ct],['type'=>'secret_text','name'=>'CF_ACCOUNT_ID','text'=>$acc],['type'=>'secret_text','name'=>'CF_SUBDOMAIN','text'=>$sub],['type'=>'secret_text','name'=>'PANEL_VERSION','text'=>$PANEL_VERSION]];
        $up=cf_worker_upload($ct,$acc,$wk,pb_worker_src(),$bind,['secret_text'],'');
        if(!empty($up['success'])){$db->prepare('UPDATE panel_records SET panel_version=? WHERE id=?')->execute([$PANEL_VERSION,(int)$pr['id']]);$ok++;}else{$fail++;}
    }
    return [$ok,$fail,count($rows)];
}

function vpn_status($svc) {
    $now = time();
    if (!(int)$svc['active']) return ['off', 'غیرفعال'];
    if ((int)$svc['expire'] > 0 && $now >= (int)$svc['expire']) return ['expired', 'منقضی شده'];
    if ((int)$svc['limit_bytes'] > 0 && (int)$svc['used'] >= (int)$svc['limit_bytes']) return ['full', 'حجم تمام شده'];
    return ['ok', 'فعال'];
}

function vpn_migrate_legacy($me) {
    global $db;
    $c = $db->prepare('SELECT COUNT(*) FROM cf_accts WHERE email=?'); $c->execute([$me]);
    if ((int)$c->fetchColumn() > 0) return;
    $o = $db->prepare('SELECT * FROM cf_accounts WHERE email=?'); $o->execute([$me]);
    $r = $o->fetch(PDO::FETCH_ASSOC);
    if (!$r) return;
    $db->prepare('INSERT INTO cf_accts(email,label,token_enc,account_id,account_name,subdomain,status,created) VALUES(?,?,?,?,?,?,?,?)')
       ->execute([$me, $r['account_name'] ?: 'Cloudflare', $r['token_enc'], $r['account_id'], $r['account_name'], $r['subdomain'], 'ok', (int)$r['created'] ?: time()]);
    $db->prepare('DELETE FROM cf_accounts WHERE email=?')->execute([$me]);
}

function vpn_acct_add_one($me, $tok, $accIn) {
    global $db;
    if (!preg_match('/^[A-Za-z0-9_\-]{30,80}$/', $tok)) return ['ok' => false, 'error' => 'فرمت توکن درست نیست'];
    if ($accIn !== '' && !preg_match('/^[a-f0-9]{32}$/i', $accIn)) return ['ok' => false, 'error' => 'Account ID باید ۳۲ کاراکتر هگزادسیمال باشه'];
    $v = cf_req($tok, 'GET', '/user/tokens/verify');
    if (!empty($v['net'])) return ['ok' => false, 'error' => 'ارتباط سرور با کلودفلر برقرار نشد'];
    $okTok = !empty($v['success']) && ($v['result']['status'] ?? '') === 'active';
    if (!$okTok && $accIn !== '') {
        $v2 = cf_req($tok, 'GET', '/accounts/' . rawurlencode($accIn) . '/tokens/verify');
        $okTok = !empty($v2['success']) && ($v2['result']['status'] ?? '') === 'active';
    }
    if (!$okTok) return ['ok' => false, 'error' => 'توکن نامعتبر یا غیرفعاله'];
    $accId = $accIn; $accName = 'Cloudflare';
    if ($accId === '') {
        $l = cf_req($tok, 'GET', '/accounts?per_page=5');
        $res = $l['result'] ?? [];
        if (empty($l['success']) || !is_array($res) || !count($res)) return ['ok' => false, 'need_account' => true, 'error' => 'Account ID پیدا نشد؛ بعد از توکن یک فاصله بذار و Account ID رو هم بنویس'];
        $accId = (string)$res[0]['id']; $accName = (string)($res[0]['name'] ?? 'Cloudflare');
    }
    $dup = $db->prepare('SELECT 1 FROM cf_accts WHERE email=? AND account_id=?'); $dup->execute([$me, $accId]);
    if ($dup->fetchColumn()) return ['ok' => false, 'error' => 'این اکانت قبلاً اضافه شده'];
    $t = cf_req($tok, 'GET', '/accounts/' . rawurlencode($accId) . '/workers/scripts');
    if (empty($t['success'])) return ['ok' => false, 'error' => 'دسترسی Workers Scripts: Edit لازمه. ' . cf_err($t)];
    $d1t = cf_req($tok, 'GET', '/accounts/' . rawurlencode($accId) . '/d1/database?per_page=1');
    if (empty($d1t['success'])) return ['ok' => false, 'error' => 'دسترسی D1: Edit لازمه؛ با «ساخت توکن هوشمند» توکن جدید بساز'];
    $sd = cf_req($tok, 'GET', '/accounts/' . rawurlencode($accId) . '/workers/subdomain');
    $sub = (string)($sd['result']['subdomain'] ?? '');
    if ($sub === '') {
        $c = cf_req($tok, 'PUT', '/accounts/' . rawurlencode($accId) . '/workers/subdomain', ['subdomain' => 'u' . bin2hex(random_bytes(5))]);
        $sub = (string)($c['result']['subdomain'] ?? '');
        if ($sub === '') return ['ok' => false, 'error' => 'ساخت ساب‌دامین workers.dev ناموفق بود؛ یک‌بار وارد Workers & Pages داشبورد کلودفلر شو'];
    }
    $db->prepare('INSERT INTO cf_accts(email,label,token_enc,account_id,account_name,subdomain,status,created) VALUES(?,?,?,?,?,?,?,?)')
       ->execute([$me, mb_substr($accName, 0, 60), aes_encrypt($tok), $accId, mb_substr($accName, 0, 80), $sub, 'ok', time()]);
    return ['ok' => true, 'label' => $accName];
}

function vpn_acct_ensure_d1(array &$a) {
    global $db;
    if (!empty($a['d1_id'])) return true;
    $tok = aes_decrypt($a['token_enc']); if ($tok === '') { $a['err'] = 'توکن خونده نشد'; return false; }
    $r = cf_req($tok, 'POST', '/accounts/' . rawurlencode($a['account_id']) . '/d1/database', ['name' => 'vpnhub-' . bin2hex(random_bytes(5))]);
    $id = (string)($r['result']['uuid'] ?? '');
    if (empty($r['success']) || $id === '') { $a['err'] = 'D1: ' . cf_err($r); return false; }
    $q = d1_q($tok, $a['account_id'], $id, VPN_D1_SCHEMA);
    if (empty($q['success'])) {
        $okAll = true;
        foreach (explode(';', VPN_D1_SCHEMA) as $stm) {
            $rr = d1_q($tok, $a['account_id'], $id, $stm);
            if (empty($rr['success'])) { $okAll = false; $a['err'] = 'D1 schema: ' . cf_err($rr); break; }
        }
        if (!$okAll) { cf_req($tok, 'DELETE', '/accounts/' . rawurlencode($a['account_id']) . '/d1/database/' . $id); return false; }
    }
    $a['d1_id'] = $id;
    $db->prepare('UPDATE cf_accts SET d1_id=? WHERE id=?')->execute([$id, $a['id']]);
    return true;
}

function vpn_node_create(array $svc, array $a, &$err = '', array $opt = []) {
    global $db;
    $tok = aes_decrypt($a['token_enc']);
    if ($tok === '') { $err = 'توکن اکانت خونده نشد'; return 0; }
    if (!vpn_acct_ensure_d1($a)) { $err = 'ساخت دیتابیس ناموفق: ' . ($a['err'] ?? ''); return 0; }
    $acc = rawurlencode($a['account_id']);
    $locCode = !empty($opt['loc']) && vpn_loc((string)$opt['loc']) ? (string)$opt['loc'] : (string)$svc['location'];
    $loc = vpn_loc($locCode);
    $region = $loc ? (string)$loc['region'] : '';
    $ppass = (isset($opt['pass']) && strlen((string)$opt['pass']) >= 4) ? (string)$opt['pass'] : '1234';
    $ppath = bin2hex(random_bytes(8));
    $name = 'v' . bin2hex(random_bytes(5));
    $vpnSrc=cf_template('vpn'); $vpnSrc=str_replace(['__SUPPORT__','__CHANNEL__'],[$GLOBALS['TELEGRAM_SUPPORT'],$GLOBALS['TELEGRAM_CHANNEL']],$vpnSrc);
    $up = cf_worker_upload($tok, $a['account_id'], $name, $vpnSrc, [
        ['type' => 'd1', 'name' => 'DB', 'id' => $a['d1_id']],
        ['type' => 'secret_text', 'name' => 'ADMIN_PASS', 'text' => $ppass],
        ['type' => 'secret_text', 'name' => 'PANEL_PATH', 'text' => $ppath],
        ['type' => 'secret_text', 'name' => 'PANEL_VERSION', 'text' => $GLOBALS['PANEL_VERSION']],
        ['type' => 'secret_text', 'name' => 'PANEL_SECRET', 'text' => bin2hex(random_bytes(32))],
    ], [], $region);
    if (empty($up['success'])) { $err = 'ساخت ورکر ناموفق: ' . cf_err($up); return 0; }
    cf_req($tok, 'POST', '/accounts/' . $acc . '/workers/scripts/' . rawurlencode($name) . '/subdomain', ['enabled' => true, 'previews_enabled' => false]);
    $ins = d1_q($tok, $a['account_id'], $a['d1_id'],
        'INSERT INTO users(name,uuid,token,limit_bytes,used,expire,active,created) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(uuid) DO UPDATE SET name=excluded.name,limit_bytes=excluded.limit_bytes,expire=excluded.expire,active=excluded.active',
        [(string)$svc['name'], (string)$svc['uuid'], bin2hex(random_bytes(12)), (int)$svc['limit_bytes'], 0, (int)$svc['expire'], (int)$svc['active'], time()]);
    if (empty($ins['success'])) {
        cf_req($tok, 'DELETE', '/accounts/' . $acc . '/workers/scripts/' . rawurlencode($name) . '?force=true');
        $err = 'ثبت کاربر در دیتابیس ناموفق: ' . cf_err($ins);
        return 0;
    }
    d1_q($tok, $a['account_id'], $a['d1_id'], 'REPLACE INTO settings(k,v) VALUES(?,?),(?,?),(?,?),(?,?),(?,?),(?,?),(?,?)', ['max_conn',(string)(int)($svc['max_conn']??0),'block_ads',(string)(int)($svc['block_ads']??0),'max_users',(string)(int)($svc['max_users']??0),'transport',(string)($svc['transport']??'ws'),'ports',(string)($svc['ports']??'443'),'fragment_enabled',(string)(int)($svc['fragment_enabled']??0),'fragment_packets',(string)($svc['fragment_packets']??'tlshello')]);
    $host = $name . '.' . $a['subdomain'] . '.workers.dev';
    $db->prepare('INSERT INTO vpn_nodes(service_id,acct_id,worker,host,created,push,loc,panel,service_d1_id) VALUES(?,?,?,?,?,?,?,?,?)')
       ->execute([(int)$svc['id'], (int)$a['id'], $name, $host, time(), '', $locCode, $ppath, (string)($a['d1_id']??'')]);
    return (int)$db->lastInsertId();
}

function vpn_node_destroy(array $n, array $svc) {
    $tok = aes_decrypt((string)$n['token_enc']);
    if ($tok === '') return false;
    $ok = true;
    $r = cf_req($tok, 'DELETE', '/accounts/' . rawurlencode($n['account_id']) . '/workers/scripts/' . rawurlencode($n['worker']) . '?force=true');
    if (empty($r['success']) && (int)($r['errors'][0]['code'] ?? 0) !== 10007) $ok = false;
    if (!empty($n['service_d1_id'])) { d1_q($tok, $n['account_id'], $n['service_d1_id'], 'DELETE FROM users WHERE uuid=?', [(string)$svc['uuid']]); try { cf_req($tok, 'DELETE', '/accounts/' . rawurlencode($n['account_id']) . '/d1/database/' . rawurlencode($n['service_d1_id'])); } catch (Throwable $e) {} } else if (!empty($n['d1_id'])) d1_q($tok, $n['account_id'], $n['d1_id'], 'DELETE FROM users WHERE uuid=?', [(string)$svc['uuid']]);
    return $ok;
}

function vpn_nodes_of($sid) {
    global $db;
    $q = $db->prepare('SELECT n.*, a.token_enc, a.account_id, COALESCE(n.service_d1_id,a.d1_id) AS d1_id, a.limited_until, a.status AS astatus, a.label AS alabel FROM vpn_nodes n LEFT JOIN cf_accts a ON a.id=n.acct_id WHERE n.service_id=? ORDER BY n.id');
    $q->execute([(int)$sid]);
    return $q->fetchAll(PDO::FETCH_ASSOC);
}

/* همگام‌سازی مصرف از D1 همه‌ی نودها + اعمال حجم/انقضا/وضعیت روی ورکرها */
function vpn_sync($sid, $force = false) {
    global $db, $VPN_DAILY_CAP;
    $s = $db->prepare('SELECT * FROM vpn_services WHERE id=?'); $s->execute([(int)$sid]);
    $svc = $s->fetch(PDO::FETCH_ASSOC);
    if (!$svc) return null;
    if (!$force && time() - (int)$svc['last_sync'] < 20) return $svc;
    $nodes = vpn_nodes_of($sid);
    $today = gmdate('Y-m-d');
    $nextMid = gmmktime(0, 0, 0, (int)gmdate('n'), (int)gmdate('j') + 1, (int)gmdate('Y'));
    $total = 0; $usedBy = [];
    foreach ($nodes as $n) {
        $tok = aes_decrypt((string)$n['token_enc']);
        $nu = (int)$n['used'];
        if ($tok !== '' && !empty($n['d1_id'])) {
            $r = d1_q($tok, $n['account_id'], $n['d1_id'], 'SELECT (SELECT used FROM users WHERE uuid=?) AS used, (SELECT conns FROM daily WHERE day=?) AS conns', [(string)$svc['uuid'], $today]);
            if (!empty($r['success'])) {
                $row = d1_rows($r)[0] ?? [];
                $nu = (int)($row['used'] ?? 0); $c = (int)($row['conns'] ?? 0);
                $db->prepare('UPDATE vpn_nodes SET used=?,state=? WHERE id=?')->execute([$nu, 'ok', (int)$n['id']]);
                $db->prepare('UPDATE cf_accts SET conns=?,conns_day=?,limited_until=?,status=CASE WHEN status=? THEN ? ELSE status END WHERE id=?')
                   ->execute([$c, $today, $c >= $VPN_DAILY_CAP ? $nextMid : 0, 'error', 'ok', (int)$n['acct_id']]);
            } else {
                $code = (int)($r['errors'][0]['code'] ?? 0);
                $db->prepare('UPDATE vpn_nodes SET state=? WHERE id=?')->execute(['err', (int)$n['id']]);
                if (in_array($code, [9109, 10000, 6003, 6111], true)) $db->prepare('UPDATE cf_accts SET status=?,err=? WHERE id=?')->execute(['error', mb_substr(cf_err($r), 0, 150), (int)$n['acct_id']]);
            }
        }
        $usedBy[(int)$n['id']] = $nu; $total += $nu;
    }
    $lim = (int)$svc['limit_bytes']; $exp = (int)$svc['expire'];
    $svc['used'] = $total;
    $st = vpn_status($svc);
    $act = $st[0] === 'ok' ? 1 : 0;
    $left = $lim > 0 ? max(0, $lim - $total) : 0;
    foreach ($nodes as $n) {
        $tok = aes_decrypt((string)$n['token_enc']);
        if ($tok === '' || empty($n['d1_id'])) continue;
        $nl = $lim > 0 ? $usedBy[(int)$n['id']] + $left : 0;
        $key = $nl . '|' . $exp . '|' . $act . '|' . $svc['name'];
        if ($key === (string)$n['push']) continue;
        $r = d1_q($tok, $n['account_id'], $n['d1_id'], 'UPDATE users SET limit_bytes=?,expire=?,active=?,name=? WHERE uuid=?', [$nl, $exp, $act, (string)$svc['name'], (string)$svc['uuid']]);
        if (!empty($r['success'])) $db->prepare('UPDATE vpn_nodes SET push=? WHERE id=?')->execute([$key, (int)$n['id']]);
    }
    $db->prepare('UPDATE vpn_services SET used=?,last_sync=? WHERE id=?')->execute([$total, time(), (int)$sid]);
    $svc['last_sync'] = time();
    return $svc;
}

function vpn_cloudflare_edge_ips($count = 20) {
    $count = max(0, min(100, (int)$count));
    if ($count === 0) return [];
    $ranges = [];
    foreach (['https://www.cloudflare.com/ips-v4','https://www.cloudflare.com/ips-v6'] as $u) {
        $raw = @http_raw($u, ['Accept: text/plain'], null, 12);
        if (!$raw) continue;
        foreach (preg_split('/\s+/', trim($raw)) as $cidr) if ($cidr !== '') $ranges[] = trim($cidr);
    }
    $out=[];
    foreach ($ranges as $cidr) {
        if (strpos($cidr, ':') !== false) continue; // IPv4 only for broad client compatibility
        [$net,$bits] = array_pad(explode('/', $cidr, 2), 2, 32);
        $bits=(int)$bits; $base=ip2long($net); if ($base===false || $bits<0 || $bits>32) continue;
        $size=1 << (32-$bits); if ($size < 4) continue;
        $usable=max(1,$size-2);
        // Deterministic spread across each published Cloudflare range.
        foreach ([1, (int)floor($usable/3), (int)floor($usable*2/3), $usable] as $off) {
            if (count($out) >= $count) break 2;
            $n = ($base + min($usable-1,max(1,$off))) & 0xffffffff;
            $ip=long2ip($n);
            if ($ip && !in_array($ip,$out,true)) $out[]=$ip;
        }
    }
    return array_slice($out,0,$count);
}
function vpn_refresh_clean_ips($sid, $count = 0) {
    global $db;
    $sid=(int)$sid; $count=max(0,min(100,(int)$count));
    $db->prepare('DELETE FROM vpn_service_ips WHERE service_id=?')->execute([$sid]);
    if ($count===0) return [];
    // Safe catalog only: Cloudflare published Edge ranges. No public port scanning is performed.
    $ips=vpn_cloudflare_edge_ips($count);
    $q=$db->prepare('INSERT OR IGNORE INTO vpn_service_ips(service_id,ip,kind,active,created) VALUES(?,?,?,?,?)');
    foreach($ips as $ip)$q->execute([$sid,$ip,'cloudflare-edge-catalog',1,time()]);
    return $ips;
}
function vpn_parse_fallback_ips($raw) {
    $out=[];
    foreach(preg_split('/[
,;\s]+/',(string)$raw) as $v){
        $v=trim($v); if($v==='') continue;
        // Accept IP:port input but keep only the IP here; ports are configured separately.
        if(preg_match('/^\[?([^\]]+)\]:(\d{1,5})$/',$v,$m)) $v=$m[1];
        if(!filter_var($v,FILTER_VALIDATE_IP)) continue;
        if(!in_array($v,$out,true)) $out[]=$v;
    }
    return array_slice($out,0,100);
}
function vpn_effective_ips(array $svc) {
    $ips=vpn_service_ips((int)($svc['id']??0));
    if($ips) return $ips;
    $fb=vpn_parse_fallback_ips((string)($svc['fallback_ips']??''));
    if($fb) return $fb;
    return vpn_parse_fallback_ips((string)st('vpn_fallback_ips',''));
}

function vpn_service_ips($sid) {
    global $db;
    try { $q=$db->prepare('SELECT ip FROM vpn_service_ips WHERE service_id=? AND active=1 ORDER BY id');$q->execute([(int)$sid]);return array_values(array_filter(array_map('strval',$q->fetchAll(PDO::FETCH_COLUMN)))); } catch(Throwable $e){return [];}
}

function vpn_links(array $svc, array $nodes) {
    global $VPN_ADDRESS;
    $addr = trim((string)($svc['cip'] ?? '')) !== '' ? trim((string)$svc['cip']) : trim(st('vpn_address', $VPN_ADDRESS));
    $pr = (string)($svc['proto'] ?? 'vless'); if (!in_array($pr, ['vless', 'trojan', 'both'], true)) $pr = 'vless';
    $transport = (string)($svc['transport'] ?? 'ws'); if ($transport !== 'ws') $transport='ws';
    $ports = array_values(array_unique(array_filter(array_map('intval', preg_split('/[,\s;]+/', (string)($svc['ports'] ?? '443'))), function($x){return $x>=1&&$x<=65535;})));
    if (!$ports) $ports=[443];
    if (!preg_match('/^[A-Za-z0-9.\-:\[\]]{1,100}$/', $addr)) $addr = '';
    $ips=vpn_effective_ips($svc);
    $targets=$ips ?: ($addr!=='' ? [$addr] : []);
    $loc = vpn_loc((string)$svc['location']); $flag = $loc ? $loc['flag'] : '🌐';
    $now = time(); $out = []; $i = 0;
    foreach ($nodes as $n) {
        $i++; $host=(string)$n['host']; $limited=(int)($n['limited_until']??0)>$now;
        $bad=((string)($n['state']??'ok')!=='ok')||((string)($n['astatus']??'ok')!=='ok');
        $nl=!empty($n['loc'])?vpn_loc((string)$n['loc']):null; $nflag=$nl?$nl['flag']:$flag;
        if (!$targets) $targets=[$host];
        $j=0;
        foreach($targets as $target){$j++; foreach($ports as $port){$label=$nflag.' '.$svc['name'].' · '.$i.($j>1?' · IP'.$j:'').' · P'.$port.($limited?' (پر)':'');
            $link='vless://'.$svc['uuid'].'@'.$target.':'.$port.'?encryption=none&security=tls&sni='.rawurlencode($host).'&fp=chrome&type=ws&host='.rawurlencode($host).'&path=%2Fws#'.rawurlencode($label);
            $state=$limited?'limited':($bad?'error':'ok');
            if($pr!=='trojan')$out[]=['n'=>$i,'p'=>'vless','name'=>$label.($pr==='both'?' [VLESS]':''),'link'=>$link,'host'=>$host,'addr'=>$target,'port'=>$port,'state'=>$state,'transport'=>$transport];
            if($pr!=='vless')$out[]=['n'=>$i,'p'=>'trojan','name'=>$label.($pr==='both'?' [Trojan]':''),'link'=>'trojan://'.$svc['uuid'].'@'.$target.':'.$port.'?security=tls&sni='.rawurlencode($host).'&fp=chrome&type=ws&host='.rawurlencode($host).'&path=%2Ftj#'.rawurlencode($label.' Trojan'),'host'=>$host,'addr'=>$target,'port'=>$port,'state'=>$state,'transport'=>$transport];
        }}
    }
    usort($out,function($x,$y){$a=$x['state']==='ok'?0:1;$b=$y['state']==='ok'?0:1;return $a===$b?($x['n']<=>$y['n']):($a<=>$b);});
    return $out;
}

function vpn_clash(array $svc, array $links) {
    $q = function ($s) { return '"' . str_replace(['\\', '"'], ['\\\\', '\\"'], (string)$s) . '"'; };
    $y = "mixed-port: 7890\nallow-lan: false\nmode: rule\nlog-level: warning\nproxies:\n";
    $names = [];
    foreach ($links as $l) {
        $names[] = $q($l['name']);
        if (($l['p'] ?? 'vless') === 'trojan') { $y .= '  - {name: ' . $q($l['name']) . ', type: trojan, server: ' . $q($l['addr']) . ', port: ' . (int)($l['port'] ?? 443) . ', password: ' . $q($svc['uuid']) . ', udp: false, sni: ' . $q($l['host']) . ', network: ws, client-fingerprint: chrome, ws-opts: {path: "/tj", headers: {Host: ' . $q($l['host']) . '}}}' . "\n"; continue; }
        $y .= '  - {name: ' . $q($l['name']) . ', type: vless, server: ' . $q($l['addr']) . ', port: ' . (int)($l['port'] ?? 443) . ', uuid: ' . $q($svc['uuid']) . ', udp: false, tls: true, servername: ' . $q($l['host']) . ', network: ws, client-fingerprint: chrome, ws-opts: {path: "/ws", headers: {Host: ' . $q($l['host']) . '}}}' . "\n";
    }
    if (!$names) $names[] = 'DIRECT';
    $y .= "proxy-groups:\n  - {name: \"Auto\", type: fallback, proxies: [" . implode(', ', $names) . "], url: \"http://www.gstatic.com/generate_204\", interval: 300}\nrules:\n  - MATCH,Auto\n";
    return $y;
}

function vpn_public_state(array $svc, array $nodes) {
    $links = vpn_links($svc, $nodes);
    $st = vpn_status($svc);
    $lim = (int)$svc['limit_bytes']; $used = (int)$svc['used']; $exp = (int)$svc['expire']; $now = time();
    $loc = vpn_loc((string)$svc['location']);
    $srv = [];
    foreach ($links as $l) $srv[$l['n']] = ['n'=>$l['n'],'state'=>$l['state'],'link'=>$l['link']]; $srv = array_values($srv);
    $cl = [];
    foreach ($links as $l) $cl[] = ['name' => $l['name'], 'link' => $l['link']];
    $rq=0; $qq=$GLOBALS['db']->prepare('SELECT COALESCE(SUM(a.conns),0) FROM vpn_nodes n JOIN cf_accts a ON a.id=n.acct_id WHERE n.service_id=?'); $qq->execute([(int)$svc['id']]); $rq=(int)$qq->fetchColumn();
    return [
        'name' => $svc['name'], 'flag' => $loc ? $loc['flag'] : '🌐', 'loc' => $loc ? $loc['name'] : 'خودکار',
        'status' => $st[0], 'status_text' => $st[1],
        'used' => $used, 'limit' => $lim, 'left' => $lim > 0 ? max(0, $lim - $used) : -1,
        'pct' => $lim > 0 ? min(100, round($used / $lim * 100, 1)) : 0,
        'expire' => $exp, 'expire_text' => $exp > 0 ? jdate($exp, false) : 'نامحدود',
        'days_left' => $exp > 0 ? max(0, (int)ceil(($exp - $now) / 86400)) : -1,
        'days_total' => (int)$svc['days_total'],
        'created' => jdate((int)$svc['created'], false),
        'updated' => (int)$svc['last_sync'] > 0 ? jdate((int)$svc['last_sync']) : '—',
        'requests_used'=>$rq,'requests_left'=>max(0,(int)$VPN_DAILY_CAP-$rq),'stale'=>($now-(int)$svc['last_sync'])>90,'request_quota'=>0,
        'servers' => $srv, 'links' => $cl, 'sub' => vpn_sub_url($svc['token']),
    ];
}

function vpn_sub_page(array $state, $token) {
    global $TELEGRAM_SUPPORT, $TELEGRAM_CHANNEL;
    $js = json_encode($state, JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_UNESCAPED_SLASHES);
    $page = <<<'VPNSUBHTML'
<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#070b14">
<title>__TITLE__</title>
<link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;800&display=swap" rel="stylesheet">
<style>
:root{--bg:#070b14;--c1:#0f1730;--c2:#16213f;--bd:rgba(255,255,255,.09);--tx:#eef2ff;--mu:#8b97b8;--ok:#2ee6a6;--warn:#ffb84d;--bad:#ff5d73;--ac:#6c8cff;--ac2:#b06cff}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
html,body{margin:0}
body{background:radial-gradient(900px 520px at 85% -8%,rgba(60,90,200,.30),transparent),radial-gradient(800px 500px at -10% 105%,rgba(150,60,200,.22),transparent),var(--bg);color:var(--tx);font-family:Vazirmatn,Tahoma,sans-serif;min-height:100vh;padding:max(18px,env(safe-area-inset-top)) 14px 44px;line-height:1.8}
.wrap{max-width:520px;margin:auto}
a{color:inherit;text-decoration:none;-webkit-touch-callout:none}
button{font:inherit;color:inherit;border:0;outline:none;cursor:pointer;-webkit-appearance:none;appearance:none;user-select:none;-webkit-user-select:none;touch-action:manipulation;background:none}
button:focus,button:focus-visible,a:focus,a:focus-visible{outline:none;box-shadow:none}
::selection{background:rgba(108,140,255,.35)}
.top{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:6px 2px 16px}
.brand{display:flex;align-items:center;gap:10px;min-width:0}
.logo{width:44px;height:44px;border-radius:14px;background:#111;display:grid;place-items:center;font-size:22px;box-shadow:0 8px 24px rgba(108,140,255,.35)}
.brand h1{font-size:17px;margin:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.brand small{color:var(--mu);font-size:12px}
.pill{padding:4px 12px;border-radius:99px;font-size:12px;font-weight:600;border:1px solid var(--bd);background:rgba(255,255,255,.05);white-space:nowrap}
.pill.ok{color:var(--ok);border-color:rgba(46,230,166,.35);background:rgba(46,230,166,.1)}
.pill.bad{color:var(--bad);border-color:rgba(255,93,115,.35);background:rgba(255,93,115,.1)}
.pill.warn{color:var(--warn);border-color:rgba(255,184,77,.35);background:rgba(255,184,77,.1)}
.card{background:linear-gradient(180deg,rgba(255,255,255,.055),rgba(255,255,255,.025));border:1px solid var(--bd);border-radius:22px;padding:18px;margin-bottom:12px;backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px)}
.ringbox{display:flex;align-items:center;gap:18px}
.ring{position:relative;width:150px;height:150px;flex:none}
.ring svg{width:100%;height:100%;transform:rotate(-90deg)}
.ring .bg{stroke:rgba(255,255,255,.08)}
.ring .fg{transition:stroke-dashoffset 1s cubic-bezier(.2,.8,.2,1),stroke .4s}
.ring .mid{position:absolute;inset:0;display:grid;place-content:center;text-align:center}
.ring .mid b{font-size:30px;line-height:1.1;font-weight:800}
.ring .mid span{font-size:11px;color:var(--mu)}
.tiles{flex:1;display:grid;gap:8px}
.tile{background:rgba(255,255,255,.05);border:1px solid var(--bd);border-radius:14px;padding:8px 12px;display:flex;justify-content:space-between;align-items:center;font-size:13px}
.tile span{color:var(--mu)} .tile b{font-weight:600}
h3{font-size:14px;margin:0 0 10px;display:flex;align-items:center;gap:6px}
.bar{height:10px;border-radius:9px;background:rgba(255,255,255,.08);overflow:hidden}
.bar i{display:block;height:100%;border-radius:9px;background:linear-gradient(90deg,var(--ac),var(--ac2));transition:width 1s cubic-bezier(.2,.8,.2,1)}
.row{display:flex;justify-content:space-between;font-size:12.5px;color:var(--mu);margin-top:8px}
.row b{color:var(--tx);font-weight:600}
.srv{display:flex;flex-wrap:wrap;gap:8px}
.chip{display:flex;align-items:center;gap:7px;background:rgba(255,255,255,.05);border:1px solid var(--bd);border-radius:12px;padding:6px 12px;font-size:12.5px}
.dot{width:8px;height:8px;border-radius:50%;background:var(--ok);box-shadow:0 0 10px var(--ok)}
.dot.limited{background:var(--warn);box-shadow:0 0 10px var(--warn)} .dot.error{background:var(--bad);box-shadow:0 0 10px var(--bad)}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.btn{display:flex;align-items:center;justify-content:center;gap:8px;padding:13px 10px;border-radius:16px;font-weight:600;font-size:14px;background:rgba(255,255,255,.06);border:1px solid var(--bd);transition:transform .12s,background .2s,border-color .2s}
.btn:active{transform:scale(.96);background:rgba(255,255,255,.1)}
.btn.main{background:#111;border-color:transparent;box-shadow:0 10px 26px rgba(108,140,255,.3)}
.btn.done{background:rgba(46,230,166,.16);border-color:rgba(46,230,166,.45);color:var(--ok)}
.btn.wide{grid-column:1/-1}
.btn[disabled]{opacity:.6;pointer-events:none}
.cfgs{display:none;margin-top:10px}.cfgs.open{display:block;animation:fd .25s}
@keyframes fd{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:none}}
.cfg{display:flex;align-items:center;gap:10px;background:rgba(0,0,0,.22);border:1px solid var(--bd);border-radius:14px;padding:10px 12px;margin-bottom:8px}
.cfg>div{min-width:0;flex:1}.cfg b{display:block;font-size:13px}
.cfg code{display:block;direction:ltr;text-align:left;color:var(--mu);font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cfg button{padding:8px 14px;border-radius:12px;background:rgba(108,140,255,.16);border:1px solid rgba(108,140,255,.35);font-size:12.5px;font-weight:600;flex:none}
.cfg button.done{background:rgba(46,230,166,.16);border-color:rgba(46,230,166,.45);color:var(--ok)}
.how{font-size:12.5px;color:var(--mu);margin:0;padding:0 18px}.how li{margin-bottom:4px}
.foot{text-align:center;color:var(--mu);font-size:11.5px;margin-top:14px}
.warnbox{display:none;background:rgba(255,93,115,.1);border:1px solid rgba(255,93,115,.35);color:#ffb3be;border-radius:16px;padding:12px 14px;font-size:13px;margin-bottom:12px}
@media(max-width:400px){.ringbox{flex-direction:column}.tiles{width:100%}}
body{background:#050306!important;overflow-x:hidden}body:before{content:"";position:fixed;inset:-20%;z-index:-2;background:radial-gradient(circle at 20% 30%,rgba(255,0,45,.25),transparent 25%),radial-gradient(circle at 80% 70%,rgba(120,0,20,.28),transparent 28%),linear-gradient(120deg,#030205,#21030a 45%,#050306);animation:demonglow 9s ease-in-out infinite alternate}body:after{content:"";position:fixed;inset:0;z-index:-1;opacity:.28;background-image:radial-gradient(circle,rgba(255,70,90,.8) 1px,transparent 2px);background-size:70px 70px;animation:demondots 18s linear infinite}@keyframes demonglow{to{transform:translate3d(3%,-2%,0) scale(1.08)}}@keyframes demondots{to{transform:translate3d(70px,70px,0)}}
</style></head><body><div class="wrap">
<div class="top"><div class="brand"><div class="logo">D</div><div style="min-width:0"><h1 id="nm"></h1><small id="lc"></small></div></div><span class="pill" id="st"></span></div>
<div class="warnbox" id="wb"></div>
<div class="card"><div class="ringbox">
 <div class="ring"><svg viewBox="0 0 120 120"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#6c8cff"/><stop offset="1" stop-color="#b06cff"/></linearGradient></defs><circle class="bg" cx="60" cy="60" r="52" fill="none" stroke-width="10"/><circle class="fg" id="rg" cx="60" cy="60" r="52" fill="none" stroke="url(#g)" stroke-width="10" stroke-linecap="round" stroke-dasharray="326.7" stroke-dashoffset="326.7"/></svg><div class="mid"><b id="pc">0٪</b><span id="pcs">مصرف شده</span></div></div>
 <div class="tiles"><div class="tile"><span>مصرف‌شده</span><b id="u"></b></div><div class="tile"><span>باقی‌مانده</span><b id="l"></b></div><div class="tile"><span>حجم کل</span><b id="t"></b></div><div class="tile"><span>ریکوئست مصرف‌شده</span><b id="rq"></b></div><div class="tile"><span>ریکوئست باقی‌مانده</span><b id="rql"></b></div></div>
</div></div>
<div class="card"><h3>⏳ زمان اشتراک</h3><div class="bar"><i id="db" style="width:0"></i></div><div class="row"><span><b id="dl"></b> باقی‌مانده</span><span>از <b id="dt"></b></span></div><div class="row"><span>شروع: <b id="cr"></b></span><span>پایان: <b id="ex"></b></span></div></div>
<div class="card"><h3>📈 سرعت لحظه‌ای</h3><div class="row"><span>الان: <b id="lvS">—</b></span><span>اوج: <b id="lvM">—</b></span></div><svg id="lvC" viewBox="0 0 300 64" preserveAspectRatio="none" style="width:100%;height:84px;display:block;margin-top:6px"></svg></div>
<div class="card"><h3>🌍 سرورها</h3><div class="srv" id="sv"></div></div>
<div class="card"><div class="grid">
 <button class="btn main wide" id="bSub" type="button">📋 کپی لینک اشتراک</button>
 <button class="btn" id="bCfg" type="button">📦 کانفیگ‌ها</button>
 <button class="btn" id="bRef" type="button" data-o="🔄 بروزرسانی">🔄 بروزرسانی</button>
 <a class="btn" id="bSup" href="__SUPPORT__" target="_blank" rel="noopener noreferrer">❗ پشتیبانی</a><a class="btn" id="bTg" href="__CHANNEL__" target="_blank" rel="noopener noreferrer">✈️ تلگرام</a>
</div>
<div class="cfgs" id="cf"><div style="display:flex;justify-content:space-between;align-items:center;margin:14px 0 8px"><b style="font-size:13px">کانفیگ‌های شما</b><button class="btn" id="bAll" type="button" style="padding:7px 14px;font-size:12.5px;border-radius:12px">کپی همه</button></div><div id="cl"></div></div></div>
<div class="card"><h3>📱 راهنمای اتصال</h3><ol class="how"><li>«کپی لینک اشتراک» رو بزن.</li><li>برنامه‌ی v2rayNG / Hiddify / Streisand / Shadowrocket رو باز کن.</li><li>گزینه‌ی افزودن اشتراک (Subscription) رو بزن و لینک رو بچسبون.</li><li>بروزرسانی اشتراک رو بزن و به اولین سرور وصل شو؛ اگه پر شد خودکار به بعدی می‌ره.</li></ol></div>
<div class="foot">آخرین بروزرسانی: <span id="up"></span> · <a href="__CHANNEL__" target="_blank" rel="noopener noreferrer">کانال تلگرام</a></div>
</div>
<script>
var S = __STATE__, TK = "__TOKEN__";
var $ = function(i){ return document.getElementById(i); };
function fa(s){ return String(s).replace(/\d/g, function(d){ return '۰۱۲۳۴۵۶۷۸۹'[d]; }); }
function sz(b){ if (b < 0) return 'نامحدود'; if (b >= 1073741824) return fa((b / 1073741824).toFixed(2)) + ' GB'; if (b >= 1048576) return fa((b / 1048576).toFixed(1)) + ' MB'; return fa(Math.round(b / 1024)) + ' KB'; }
var LV = {p: null, t: 0, a: []};
function live(d){
  var n = Date.now();
  if (LV.p !== null && n > LV.t) { var v = Math.max(0, (d.used - LV.p) / ((n - LV.t) / 1000)); LV.a.push(v); if (LV.a.length > 45) LV.a.shift(); lvDraw(v); }
  LV.p = d.used; LV.t = n;
}
function lvDraw(v){
  var mx = Math.max.apply(0, LV.a) || 1, k = LV.a.length, pts = LV.a.map(function(y, i){ return (i / 44 * 300).toFixed(1) + ',' + (60 - y / mx * 54).toFixed(1); });
  var x0 = ((k - 1) / 44 * 300).toFixed(1);
  $('lvC').innerHTML = '<polygon points="0,62 ' + pts.join(' ') + ' ' + x0 + ',62" fill="rgba(108,140,255,.18)"/><polyline points="' + pts.join(' ') + '" fill="none" stroke="#6c8cff" stroke-width="2" stroke-linejoin="round"/>';
  $('lvS').textContent = sz(v) + '/s'; $('lvM').textContent = sz(mx) + '/s';
}
function flash(btn, txt){ var o = btn.getAttribute('data-o') || btn.textContent; btn.setAttribute('data-o', o); btn.textContent = txt; btn.classList.add('done'); clearTimeout(btn._t); btn._t = setTimeout(function(){ btn.textContent = o; btn.classList.remove('done'); }, 1400); btn.blur(); }
function cp(t, btn, msg){
  var ok = function(){ flash(btn, msg || '✓ کپی شد'); };
  if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(t).then(ok, function(){ fb(t); ok(); });
  else { fb(t); ok(); }
}
function fb(t){ var a = document.createElement('textarea'); a.value = t; a.style.cssText = 'position:fixed;left:-9999px;top:0'; document.body.appendChild(a); a.focus(); a.select(); try { document.execCommand('copy'); } catch (e) {} document.body.removeChild(a); }
function esc(s){ return String(s).replace(/[&<>"']/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); }
var shown = 0;
function ring(p){ var c = 326.7; $('rg').style.strokeDashoffset = c - c * Math.max(0, Math.min(100, p)) / 100; $('rg').setAttribute('stroke', p >= 90 ? '#ff5d73' : (p >= 70 ? '#ffb84d' : 'url(#g)')); }
function count(to, unl){
  if (unl) { $('pc').textContent = '∞'; return; }
  var from = shown, t0 = performance.now(), d = 900;
  (function f(t){ var k = Math.min(1, (t - t0) / d), e = 1 - Math.pow(1 - k, 3); $('pc').textContent = fa((from + (to - from) * e).toFixed(to % 1 ? 1 : 0)) + '٪'; if (k < 1) requestAnimationFrame(f); else shown = to; })(t0);
}
function render(){
  $('nm').textContent = S.name; $('lc').textContent = S.flag + ' ' + S.loc;
  var st = $('st'); st.textContent = S.status_text; st.className = 'pill ' + (S.status === 'ok' ? 'ok' : (S.status === 'off' ? 'warn' : 'bad'));
  var unl = S.limit <= 0;
  ring(unl ? 100 : S.pct); count(unl ? 0 : S.pct, unl); $('pcs').textContent = unl ? 'حجم نامحدود' : 'مصرف شده';
  $('u').textContent=sz(S.used);$('l').textContent=unl?'نامحدود':sz(S.left);$('t').textContent=unl?'نامحدود':sz(S.limit);$('rq').textContent=fa(S.requests_used||0);$('rql').textContent=fa(S.requests_left||0);
  var dl = S.days_left, dt = S.days_total;
  $('dl').textContent = dl < 0 ? 'نامحدود' : fa(dl) + ' روز'; $('dt').textContent = dt > 0 ? fa(dt) + ' روز' : 'نامحدود';
  $('db').style.width = (dl < 0 || dt <= 0 ? 100 : Math.max(0, Math.min(100, dl / dt * 100))) + '%';
  $('cr').textContent = fa(S.created); $('ex').textContent = fa(S.expire_text); $('up').textContent = fa(S.updated);
  $('sv').innerHTML=S.servers.map(function(x){var u=x.link||'';var q='https://quickchart.io/qr?size=150&text='+encodeURIComponent(u);return '<div class="chip" style="width:100%;justify-content:space-between"><span><i class="dot '+(x.state==='ok'?'':x.state)+'"></i>سرور '+fa(x.n)+(x.state==='limited'?' · پر':(x.state==='error'?' · خطا':''))+'</span>'+(u?'<a href="'+esc(q)+'" target="_blank" rel="noopener"><img src="'+esc(q)+'" style="width:54px;height:54px;border-radius:8px"></a>':'')+'</div>';}).join('')||'<span style="color:var(--mu);font-size:13px">هنوز سروری فعال نشده</span>';
  $('cl').innerHTML = S.links.map(function(x, i){ return '<div class="cfg"><div><b>' + esc(x.name) + '</b><code>' + esc(x.link) + '</code></div><button type="button" data-i="' + i + '">کپی</button></div>'; }).join('');
  var wb = $('wb'), w = '';
  if (S.status === 'expired') w = 'اشتراک تموم شده؛ برای تمدید به پشتیبانی پیام بده.'; else if (S.status === 'full') w = 'حجم اشتراک تموم شده؛ برای افزایش حجم به پشتیبانی پیام بده.'; else if (S.status === 'off') w = 'این اشتراک غیرفعال شده.'; else if (S.limit > 0 && S.pct >= 90) w = 'کمتر از ۱۰٪ حجم باقی مونده.'; else if (S.days_left >= 0 && S.days_left <= 3) w = 'کمتر از ۳ روز به پایان اشتراک مونده.';
  wb.style.display = w ? 'block' : 'none'; wb.textContent = w;
}
$('cl').onclick = function(e){ var b = e.target.closest('button'); if (!b) return; cp(S.links[+b.dataset.i].link, b); };
$('bAll').onclick = function(){ cp(S.links.map(function(x){ return x.link; }).join('\n'), this, '✓ همه کپی شد'); };
$('bSub').onclick = function(){ cp(S.sub, this, '✓ لینک کپی شد'); };
$('bCfg').onclick = function(){ var c = $('cf'); c.classList.toggle('open'); this.blur(); };
function load(refresh){
  var b = $('bRef'); if (refresh) { b.disabled = true; b.textContent = '⏳ در حال بروزرسانی...'; }
  var opt = refresh ? {method: 'POST', headers: {'X-Req': '1'}, cache: 'no-store'} : {cache: 'no-store'};
  return fetch('?sub=' + TK + '&act=' + (refresh ? 'refresh' : 'state'), opt).then(function(r){ return r.json(); }).then(function(d){
    if (d && d.name) { S = d; render(); if (refresh) flash(b, '✓ بروز شد'); }
    b.disabled = false; if (!b.classList.contains('done')) b.textContent = '🔄 بروزرسانی'; b.blur();
    return d;
  }).catch(function(){ b.disabled = false; b.textContent = '🔄 بروزرسانی'; });
}
$('bRef').onclick = function(){ load(true); };
render();
if (S.stale) load(true);
setInterval(function(){ if (document.hidden) return; fetch('?sub=' + TK + '&act=refresh', {method: 'POST', headers: {'X-Req': '1'}, cache: 'no-store'}).then(function(r){ return r.json(); }).then(function(d){ if (d && d.name) { S = d; render(); live(d); } }).catch(function(){}); }, 4000);
document.addEventListener('visibilitychange', function(){ if (!document.hidden) load(false); });
</script></body></html>
VPNSUBHTML;
    $sup = (string)($TELEGRAM_SUPPORT ?: '#');
    $ch = (string)($TELEGRAM_CHANNEL ?: '#');
    return str_replace(['__TITLE__', '__SUPPORT__', '__CHANNEL__', '__TOKEN__', '__STATE__'], [e($state['name']) . ' · وضعیت اشتراک', e($sup), e($ch), $token, $js], $page);
}

/* ---------- مسیر /sub/TOKEN و ساخت خودکار قانون .htaccess ---------- */
if (!isset($_GET['sub']) && preg_match('#/sub/([A-Za-z0-9]{12,64})/?$#', (string)strtok((string)($_SERVER['REQUEST_URI'] ?? ''), '?'), $__m)) $_GET['sub'] = $__m[1];
if (st('vpn_ht', '') === '') {
    $__sw = strtolower((string)($_SERVER['SERVER_SOFTWARE'] ?? ''));
    if ($__sw !== '' && strpos($__sw, 'nginx') === false) {
        $__ht = __DIR__ . '/.htaccess';
        $__cur = is_file($__ht) ? (string)@file_get_contents($__ht) : '';
        if (strpos($__cur, '# VPN-SUB-ROUTE') === false) {
            @file_put_contents($__ht, $__cur . "\n# VPN-SUB-ROUTE\n<IfModule mod_rewrite.c>\nRewriteEngine On\nRewriteRule ^sub/([A-Za-z0-9]+)/?\$ " . basename((string)($_SERVER['SCRIPT_NAME'] ?? 'index.php')) . "?sub=\$1 [L,QSA]\n</IfModule>\n");
        }
        setst('vpn_ht', '1');
    }
}

/* ---------- کرون همگام‌سازی (اختیاری): ?vpn_cron=KEY ---------- */
if (isset($_GET['vpn_cron'])) {
    $__k = st('vpn_cron_key', '');
    if ($__k === '') { $__k = bin2hex(random_bytes(12)); setst('vpn_cron_key', $__k); }
    header('Content-Type: text/plain; charset=utf-8');
    if (!hash_equals($__k, (string)$_GET['vpn_cron'])) { http_response_code(403); exit('forbidden'); }
    @set_time_limit(120);
    $__n = 0;
    foreach ($db->query('SELECT id FROM vpn_services ORDER BY last_sync ASC LIMIT 15')->fetchAll(PDO::FETCH_COLUMN) as $__id) { try { vpn_sync((int)$__id, true); $__n++; } catch (Throwable $__e) {} }
    exit('ok ' . $__n);
}

/* ---------- پنل مدیریت سرویس پیشرفته ---------- */
if(isset($_GET['vpanel'])){
    $vt=preg_replace('/[^A-Za-z0-9]/','',(string)$_GET['vpanel']);
    $qq=$db->prepare('SELECT * FROM vpn_services WHERE token=? LIMIT 1');$qq->execute([$vt]);$vs=$qq->fetch(PDO::FETCH_ASSOC);
    if(!$vs){http_response_code(404);exit('پنل پیدا نشد.');}
    $nodes=vpn_nodes_of((int)$vs['id']);$vn=$nodes[0]??null;
    $ct=$vn?aes_decrypt((string)$vn['token_enc']):'';$d1=$vn?(string)$vn['d1_id']:'';
    $msg='';$msgType='ok';
    if($_SERVER['REQUEST_METHOD']==='POST' && hash_equals($vt,(string)($_POST['service_token']??''))){
        $act=(string)($_POST['vact']??'');$uid=(int)($_POST['uid']??0);
        try{
            if($act==='toggle'){
                $new=!(int)$vs['active'];$db->prepare('UPDATE vpn_services SET active=? WHERE id=?')->execute([$new?1:0,$vs['id']]);
                foreach(vpn_nodes_of((int)$vs['id']) as $nn){$tk=aes_decrypt((string)$nn['token_enc']);if($tk&&$nn['d1_id'])d1_q($tk,$nn['account_id'],$nn['d1_id'],'REPLACE INTO settings(k,v) VALUES(?,?)',['global_panel_enabled',$new?'1':'0']);}
                header('Location: '.vpn_base_url().'/index.php?vpanel='.rawurlencode($vt));exit;
            }
            if($act==='svc_save'){
                $name=mb_substr(trim(preg_replace('/[\\r\\n\\t]+/',' ',(string)($_POST['svc_name']??$vs['name']))),0,40);if($name==='')$name=$vs['name'];
