    }
    $__act = (string)($_GET['act'] ?? '');
    $__nodes = vpn_nodes_of((int)$__svc['id']);
    if ($__act === 'refresh' && $_SERVER['REQUEST_METHOD'] === 'POST' && ($_SERVER['HTTP_X_REQ'] ?? '') === '1') {
        try { $__f = vpn_sync((int)$__svc['id'], false); if ($__f) $__svc = $__f; } catch (Throwable $__e) {}
        $__nodes = vpn_nodes_of((int)$__svc['id']);
        out(vpn_public_state($__svc, $__nodes));
    }
    if ($__act === 'state') out(vpn_public_state($__svc, $__nodes));

    $__ua = (string)($_SERVER['HTTP_USER_AGENT'] ?? ''); $__acc = (string)($_SERVER['HTTP_ACCEPT'] ?? '');
    $__fmt = (string)($_GET['format'] ?? '');
    if ($__fmt === '') {
        if (preg_match('/clash|stash|mihomo|flclash/i', $__ua)) $__fmt = 'clash';
        elseif (preg_match('/v2ray|hiddify|sing-?box|streisand|nekobox|nekoray|shadowrocket|v2box|karing|happ|foxray|surge|quantumult|loon|husi|exclave|okhttp|go-http|curl|wget|python/i', $__ua) || stripos($__acc, 'text/html') === false) $__fmt = 'raw';
        else $__fmt = 'page';
    }
    $__stale = (time() - (int)$__svc['last_sync']) > 120;
    if ($__fmt !== 'page') {
        $db->prepare('UPDATE vpn_services SET hits=hits+1,last_seen=? WHERE id=?')->execute([time(), (int)$__svc['id']]);
    }
    if ($__stale) { $__sid = (int)$__svc['id']; after_response(function () use ($__sid) { vpn_sync($__sid, true); }); }
    $__links = vpn_links($__svc, $__nodes);
    if ($__fmt === 'page') {
        header('Content-Type: text/html; charset=utf-8'); header('Cache-Control: no-store'); header('Referrer-Policy: no-referrer');
        $__wh = !empty($__nodes[0]['host']) ? 'https://' . rtrim((string)$__nodes[0]['host'], '/') . '/' . ltrim((string)($__nodes[0]['panel'] ?? 'panel'), '/') : '';
        if ($__wh !== '') { header('Location: ' . $__wh); exit; }
        echo '<!DOCTYPE html><html lang="fa" dir="rtl"><meta charset="utf-8"><title>پنل</title><body style="font-family:Tahoma;background:#000;color:#e7e7e5;display:flex;align-items:center;justify-content:center;min-height:100vh;margin:0">پنل هنوز آماده نیست.</body></html>'; exit;
    }
    if ($__fmt === 'json') out(vpn_public_state($__svc, $__nodes));
    $__ui = 'upload=0; download=' . (int)$__svc['used'] . '; total=' . (int)$__svc['limit_bytes'] . '; expire=' . (int)$__svc['expire'];
    header('Subscription-Userinfo: ' . $__ui);
    header('Profile-Update-Interval: 2');
    header('Profile-Title: base64:' . base64_encode((string)$__svc['name']));
    header('Profile-Web-Page-Url: ' . vpn_sub_url($__tk));
    header('Cache-Control: no-store');
    if ($__fmt === 'clash') {
        header('Content-Type: text/yaml; charset=utf-8');
        header('Content-Disposition: attachment; filename="' . preg_replace('/[^A-Za-z0-9_\-]/', '_', (string)$__svc['name']) . '.yaml"');
        echo vpn_clash($__svc, $__links); exit;
    }
    header('Content-Type: text/plain; charset=utf-8');
    echo base64_encode(implode("\n", array_map(function ($x) { return $x['link']; }, $__links))); exit;
}

