    $u = $s->fetch(PDO::FETCH_ASSOC);
    if (!$u) { http_response_code(404); echo 'not found'; exit; }
    if ((int)$u['expire'] < time()) { http_response_code(410); echo 'expired'; exit; }
    $ext = $u['mime'] === 'image/png' ? 'png' : ($u['mime'] === 'image/webp' ? 'webp' : 'jpg');
    $path = __DIR__ . '/data/uploads/' . $token . '.' . $ext;
    if (!is_file($path)) { http_response_code(404); echo 'missing'; exit; }
    header('Content-Type: ' . $u['mime']);
    header('Content-Length: ' . filesize($path));
    header('Cache-Control: private, max-age=3600');
    $disposition = isset($_GET['dl']) ? 'attachment' : 'inline';
    header('Content-Disposition: ' . $disposition . '; filename="' . ($u['orig_name'] ?: ('image.' . $ext)) . '"');
    readfile($path); exit;
