    $ext = 'mp3';
    if (strpos($m['mime'], 'mpeg') !== false) $ext = 'mp3';
    elseif (strpos($m['mime'], 'wav') !== false) $ext = 'wav';
    elseif (strpos($m['mime'], 'ogg') !== false) $ext = 'ogg';
    elseif (strpos($m['mime'], 'mp4') !== false || strpos($m['mime'], 'm4a') !== false) $ext = 'm4a';
    $path = __DIR__ . '/data/audio/' . $token . '.' . $ext;
    if (!is_file($path)) { http_response_code(404); echo 'missing'; exit; }
    header('Content-Type: ' . $m['mime']);
    header('Content-Length: ' . filesize($path));
    header('Accept-Ranges: bytes');
    header('Cache-Control: private, max-age=3600');
    header('Content-Disposition: inline; filename="' . ($m['orig_name'] ?: ('audio.' . $ext)) . '"');
    readfile($path); exit;
}

