var CACHE_NAME = 'site-v<?= $SITE_VERSION ?>';
self.addEventListener('install', function(e){
    e.waitUntil(caches.open(CACHE_NAME).then(function(c){ return c.addAll(['./', './?manifest=1']).catch(function(){}); }));
    self.skipWaiting();
});
self.addEventListener('activate', function(e){
    e.waitUntil(caches.keys().then(function(keys){
        return Promise.all(keys.filter(function(k){ return k !== CACHE_NAME; }).map(function(k){ return caches.delete(k); }));
    }));
    self.clients.claim();
});
self.addEventListener('fetch', function(e){
    var url = new URL(e.request.url);
    if (e.request.method !== 'GET' || url.searchParams.has('a')) return;
    e.respondWith(
        fetch(e.request).then(function(res){
            var clone = res.clone();
            caches.open(CACHE_NAME).then(function(c){ c.put(e.request, clone).catch(function(){}); });
            return res;
        }).catch(function(){
            return caches.match(e.request).then(function(r){ return r || caches.match('./'); });
        })
    );
});
