/* ===================== پنل روی دامنه اصلی: پروکسی PHP به Worker ===================== */
/*
 * مسیر /panel/<token> دیگر Redirect نمی‌شود. تمام درخواست‌های HTML/API همان Worker
 * از داخل PHP عبور می‌کنند تا روی هاست معمولی PHP هم بدون Route اختصاصی Cloudflare باز شود.
 */
function panel_proxy($token, $suffix = '') {
    global $db;
    $q = $db->prepare('SELECT worker_url,active FROM panel_records WHERE public_token=? LIMIT 1');
    $q->execute([$token]);
    $pr = $q->fetch(PDO::FETCH_ASSOC);
    if (!$pr || !(int)$pr['active']) { http_response_code(404); exit('Panel not found'); }
    $base = rtrim((string)$pr['worker_url'], '/');
    $suffix = '/' . ltrim($suffix, '/');
    $query = $_SERVER['QUERY_STRING'] ?? '';
    $url = $base . ($suffix === '/' ? '' : $suffix) . ($query !== '' ? '?' . $query : '');

    $method = strtoupper($_SERVER['REQUEST_METHOD'] ?? 'GET');
    $body = file_get_contents('php://input');
    $headers = [];
    foreach (['Content-Type','Accept','Accept-Language','X-Req','Cache-Control','Pragma','Origin'] as $hn) {
        $key = 'HTTP_' . strtoupper(str_replace('-', '_', $hn));
        if (isset($_SERVER[$key]) && $_SERVER[$key] !== '') $headers[] = $hn . ': ' . $_SERVER[$key];
    }
    if (!empty($_SERVER['HTTP_COOKIE'])) $headers[] = 'Cookie: ' . $_SERVER['HTTP_COOKIE'];
    $headers[] = 'X-Panel-Host: ' . ($_SERVER['HTTP_HOST'] ?? '');
    $headers[] = 'X-Forwarded-Proto: ' . ((!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ? 'https' : 'http');

    $ch = curl_init($url);
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_FOLLOWLOCATION => false,
        CURLOPT_CONNECTTIMEOUT => 10,
        CURLOPT_TIMEOUT => 45,
        CURLOPT_CUSTOMREQUEST => $method,
        CURLOPT_HTTPHEADER => $headers,
        CURLOPT_SSL_VERIFYPEER => true,
        CURLOPT_SSL_VERIFYHOST => 2,
        CURLOPT_HEADER => true,
        CURLOPT_USERAGENT => $_SERVER['HTTP_USER_AGENT'] ?? 'Mozilla/5.0',
    ]);
    if ($method !== 'GET' && $method !== 'HEAD') curl_setopt($ch, CURLOPT_POSTFIELDS, $body);
    $raw = curl_exec($ch);
    $status = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
    $hsz = (int)curl_getinfo($ch, CURLINFO_HEADER_SIZE);
    $err = curl_error($ch);
    curl_close($ch);
    if ($raw === false || $status === 0) { http_response_code(502); exit('Panel upstream error' . ($err ? ': ' . $err : '')); }
    $rh = substr($raw, 0, $hsz); $rb = substr($raw, $hsz);
    http_response_code($status);
    foreach (preg_split("/\r?\n/", $rh) as $line) {
        if ($line === '' || strpos($line, ':') === false) continue;
        [$k,$v] = array_map('trim', explode(':', $line, 2));
        $kl = strtolower($k);
        if (in_array($kl, ['content-length','transfer-encoding','connection','content-encoding','location'], true)) continue;
        if ($kl === 'set-cookie') {
            $v = preg_replace('/;\s*Path=\//i', '; Path=/index.php', $v);
            header('Set-Cookie: ' . $v, false);
        } else header($k . ': ' . $v, false);
    }
    header('Cache-Control: no-store');
    echo $rb;
    exit;
}
