/* ================================ API ================================ */
if (isset($_GET['a'])) {
    $a = (string)$_GET['a']; $b = body();

    /* ==================== ساخت پنل (بدون ورود؛ توکن هیچ‌جا ذخیره نمی‌شه) ==================== */
    if (strpos($a, 'pb_') === 0) {
        if ($_SERVER['REQUEST_METHOD'] !== 'POST' || ($_SERVER['HTTP_X_REQ'] ?? '') !== '1') out(['ok' => false, 'error' => 'درخواست نامعتبر'], 400);
        @set_time_limit(90);
        $accIn = '';
        $tok = pb_parse_token($b['token'] ?? '', $accIn);
        $acc = (string)($b['account_id'] ?? '');
        if ($a !== 'pb_verify' && ($acc === '' || !preg_match('/^[a-f0-9]{32}$/i', $acc))) out(['ok' => false, 'error' => 'Account ID نامعتبر'], 400);
        if ($a === 'pb_verify') {
            if (!rate('pb_verify', 20, 600)) out(['ok' => false, 'error' => 'تلاش زیاد؛ چند دقیقه بعد دوباره امتحان کن'], 429);
            out(pb_verify_token($tok, $accIn));
        }
        if (!preg_match('/^[A-Za-z0-9_\-]{30,80}$/', $tok)) out(['ok' => false, 'error' => 'فرمت توکن درست نیست'], 400);
        $accE = rawurlencode($acc);
        if ($a === 'pb_d1') {
            if (!rate('pb_d1', 8, 3600)) out(['ok' => false, 'error' => 'تلاش زیاد؛ بعداً دوباره امتحان کن'], 429);
            $r = cf_req($tok, 'POST', '/accounts/' . $accE . '/d1/database', ['name' => 'db-' . bin2hex(random_bytes(6))]);
            $id = (string)($r['result']['uuid'] ?? '');
            if (empty($r['success']) || $id === '') out(['ok' => false, 'error' => 'ساخت دیتابیس ناموفق: ' . cf_err($r)]);
            out(['ok' => true, 'd1_id' => $id]);
        }
        if ($a === 'pb_deploy') {
            if (!rate('pb_deploy', 8, 3600)) out(['ok' => false, 'error' => 'تلاش زیاد؛ بعداً دوباره امتحان کن'], 429);
            $d1 = (string)($b['d1_id'] ?? ''); $sub = (string)($b['subdomain'] ?? '');
            if (!preg_match('/^[a-f0-9\-]{30,40}$/i', $d1) || !preg_match('/^[a-z0-9\-]{1,63}$/i', $sub)) out(['ok' => false, 'error' => 'ورودی نامعتبر'], 400);
            $name = pb_worker_name(); $pass = ''; $path = bin2hex(random_bytes(8)); $publicToken = bin2hex(random_bytes(16)); $sitePanelUrl = panel_site_url($publicToken);
            $up = cf_worker_upload($tok, $acc, $name, pb_worker_src(), [
                ['type' => 'd1', 'name' => 'DB', 'id' => $d1],
                ['type' => 'secret_text', 'name' => 'ADMIN_PASS', 'text' => ''],
                ['type' => 'secret_text', 'name' => 'PANEL_PATH', 'text' => $path],
                ['type' => 'secret_text', 'name' => 'PANEL_PUBLIC_TOKEN', 'text' => $publicToken],
                ['type' => 'secret_text', 'name' => 'PANEL_UPDATE_URL', 'text' => panel_update_endpoint_url()],
                ['type' => 'secret_text', 'name' => 'PANEL_SECRET', 'text' => bin2hex(random_bytes(32))],
                ['type' => 'secret_text', 'name' => 'PANEL_VERSION', 'text' => $PANEL_VERSION],
                ['type' => 'secret_text', 'name' => 'CF_API_TOKEN', 'text' => $tok],
                ['type' => 'secret_text', 'name' => 'CF_ACCOUNT_ID', 'text' => $acc],
                ['type' => 'secret_text', 'name' => 'CF_SUBDOMAIN', 'text' => $sub],
            ], [], '');
            if (empty($up['success'])) {
                /* A short cURL timeout is NOT treated as a failed deployment.
                   Cloudflare may still finish the Worker upload after PHP has
                   stopped waiting. Never delete the freshly-created D1 here.
                   The browser will poll pb_deploy_status using the same Worker name. */
                if (!empty($up['net'])) {
                    out(['ok'=>true,'pending'=>true,'worker'=>$name,'host'=>$name.'.'.$sub.'.workers.dev',
                         'path'=>$path,'url'=>'https://'.$name.'.'.$sub.'.workers.dev/'.$path,
                         'd1_id'=>$d1,'message'=>'ارسال Worker شروع شد اما هاست PHP بیشتر از زمان مجاز منتظر نماند؛ در حال بررسی انتشار واقعی Worker هستیم.']);
                }
                cf_req($tok, 'DELETE', '/accounts/' . $accE . '/d1/database/' . rawurlencode($d1), null, 'application/json', 4, 1);
                out(['ok' => false, 'error' => 'نصب پنل ناموفق: ' . cf_err($up)]);
            }
            $host = $name . '.' . $sub . '.workers.dev';
            $workerUrl = 'https://' . $host . '/' . $path;
            [$publicToken, $sitePanelUrl] = panel_save_record($name, $workerUrl, $pass, $publicToken, $tok, $acc, $d1);
            out(['ok' => true, 'worker' => $name, 'host' => $host, 'path' => $path, 'password' => null,
                 'url' => $workerUrl, 'worker_url' => $workerUrl, 'site_url' => $sitePanelUrl, 'public_token' => $publicToken,
                 'cloudflare_deployed' => !empty($up['_deployed']), 'cloudflare_verified' => !empty($up['_verified']),
                 'verification_note' => !empty($up['_verified']) ? 'Worker در Cloudflare تأیید شد' : 'Worker ثبت شد؛ Cloudflare هنوز در حال انتشار است']);
        }
        if ($a === 'pb_deploy_status') {
            $wk = (string)($b['worker'] ?? '');
            if (!preg_match('/^[a-z0-9]{6,63}$/', $wk)) out(['ok'=>false,'error'=>'نام Worker نامعتبر'],400);
            $r = cf_req($tok, 'GET', '/accounts/' . $accE . '/workers/scripts/' . rawurlencode($wk), null, 'application/json', 4, 1);
            if (!empty($r['success'])) {
                out(['ok'=>true,'deployed'=>true,'worker'=>$wk]);
            }
            $code=(int)($r['_http_code']??0); $ec=(int)($r['errors'][0]['code']??0);
            if ($code===404 || $ec===10090 || !empty($r['net'])) {
                out(['ok'=>true,'deployed'=>false,'pending'=>true,'error'=>!empty($r['net'])?'بررسی موقتاً زمان‌بر بود':null]);
            }
            out(['ok'=>false,'error'=>'Cloudflare Worker هنوز آماده نیست: '.cf_err($r)],502);
        }
        if ($a === 'pb_enable') {
            $wk = (string)($b['worker'] ?? '');
            if (!preg_match('/^[a-z0-9]{6,63}$/', $wk)) out(['ok' => false, 'error' => 'نام Worker نامعتبر'], 400);
            $path = '/accounts/' . $accE . '/workers/scripts/' . rawurlencode($wk) . '/subdomain';
            $r = null;
            for ($i=0; $i<4; $i++) {
                $r = cf_req($tok, 'POST', $path, ['enabled' => true, 'previews_enabled' => false]);
                if (!empty($r['success'])) break;
                if (($r['errors'][0]['code'] ?? 0) === 10090 || (int)($r['_http_code'] ?? 0) === 404) usleep(500000 * ($i+1));
                else break;
            }
            if (empty($r['success'])) out(['ok' => false, 'error' => 'فعال‌سازی workers.dev ناموفق: ' . cf_err($r)], 502);
            $sd = cf_req($tok, 'GET', '/accounts/' . $accE . '/workers/subdomain');
            $sub = (string)($sd['result']['subdomain'] ?? ($b['subdomain'] ?? ''));
            if ($sub === '') out(['ok' => false, 'error' => 'ساب‌دامین workers.dev قابل تأیید نیست'], 502);
            out(['ok' => true, 'subdomain' => $sub]);
        }
        if ($a === 'pb_check') {
            $u = trim((string)($b['url'] ?? ''));
            if (!preg_match('#^https://[a-z0-9][a-z0-9-]{0,62}\.[a-z0-9-]{1,63}\.workers\.dev/[a-f0-9]{16}$#i', $u)) out(['ok' => false, 'error' => 'آدرس Worker نامعتبر'], 400);
            $last = ['status'=>0,'body'=>''];
            for ($i = 0; $i < 3; $i++) {
                $body=''; $status=0;
                if (function_exists('curl_init')) {
                    $ch=curl_init($u); curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>4,CURLOPT_CONNECTTIMEOUT=>2,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_USERAGENT=>'DEMON-Panel/5.8']); $body=(string)curl_exec($ch); $status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE); curl_close($ch);
                } else { $body=(string)http_raw($u,['Accept: text/html,application/json,text/plain;q=0.9,*/*;q=0.8'],null,4); $status=$body!==''?200:0; }
                $last=['status'=>$status,'body'=>mb_substr($body,0,180)];
                if ($status >= 200 && $status < 500 && $body !== '') out(['ok'=>true,'verified'=>true,'status'=>$status,'attempts'=>$i+1]);
                if($i<2) usleep(350000);
            }
            out(['ok'=>true,'verified'=>false,'status'=>$last['status'],'attempts'=>3,'message'=>'Worker روی Cloudflare ثبت شده؛ انتشار workers.dev ممکن است کمی زمان ببرد.'], 200);
        }
        out(['ok' => false, 'error' => 'نامعتبر'], 404);
    }
    out(['ok' => false, 'error' => 'ورود حذف شده؛ نیازی به ورود نیست'], 410);


    /* CSRF برای POSTها */
    $csrf_protected = ['logout', 'account_info', 'sessions_list', 'session_revoke_mine', 'session_revoke_others', 'security_log', 'account_prefs', 'user_2fa_backup_regen', 'chat', 'chat_del', 'contact', 'img_upload', 'img_convert', 'img_del', 'short_create', 'short_del', 'short_stats', 'cf_status', 'cf_connect', 'cf_disconnect', 'cf_bot_create', 'cf_worker_del', 'vpn_state', 'vpn_acct_add', 'vpn_acct_check', 'vpn_acct_del', 'vpn_svc_create', 'vpn_node_add', 'vpn_svc_edit', 'vpn_svc_del', 'vpn_svc_cip', 'vpn_svc_opts', 'vpn_svc_sync', 'vpn_svc_configs', 'note_save', 'note_del', 'pw_gen', 'qr_data', 'color_save', 'ip_info', 'market_data', 'market_chart', 'my_location', 'favorite_toggle', 'notifications_list', 'notification_read', 'search_global', 'text_tool', 'date_convert', 'uuid_gen', 'report_submit', 'speed_save', 'speed_upload', 'site_report_submit', 'user_2fa_setup', 'user_2fa_verify', 'user_2fa_disable', 'user_2fa_login', 'email_otp_start', 'email_otp_verify', 'music_upload', 'music_del', 'game_save_score', 'translate_text', 'weather', 'movie_search', 'movie_files', 'music_search', 'mp_list', 'mp_create', 'mp_join', 'mp_state', 'mp_move', 'mp_leave'];
    if ($_SERVER['REQUEST_METHOD'] === 'POST' && in_array($a, $csrf_protected, true)) {
        if (!csrf_check($b['_csrf'] ?? '')) {
            audit('csrf_fail', $a, 'warn'); ip_rep_update(-5, 'fail');
            out(['ok' => false, 'error' => 'توکن امنیتی نامعتبر'], 403);
        }
    }

    /* ==================== کپچا ==================== */
    if ($a === 'captcha') {
        if (!rate('capimg', 40, 600)) out(['ok' => false, 'error' => 'تلاش زیاد؛ چند دقیقه بعد دوباره امتحان کن'], 429);
        $icons = cap_icons(); $keys = array_keys($icons);
        $target = $keys[random_int(0, count($keys) - 1)];
        $others = array_values(array_diff($keys, [$target])); cap_shuffle($others);
        $nt = random_int(2, 4);
        $cells = array_merge(array_fill(0, $nt, $target), array_slice($others, 0, 9 - $nt));
        cap_shuffle($cells);
        $ans = []; $tiles = [];
        foreach ($cells as $i => $k) { if ($k === $target) $ans[] = $i; $tiles[] = cap_tile($icons[$k][1]); }
        $_SESSION['cap'] = ['ans' => $ans, 'ts' => time(), 'mt' => microtime(true), 't' => 0];
        out(['ok' => true, 'label' => $icons[$target][0], 'tiles' => $tiles]);
    }

    /* ==================== رویدادها ==================== */
    if ($a === 'evt') {
        $sid = mb_substr(preg_replace('/[^a-z0-9]/i', '', (string)($b['sid'] ?? '')), 0, 40);
        $t = $b['type'] ?? '';
        if (!$sid || !in_array($t, ['visit', 'page', 'close', 'click', 'ping', 'offline', 'online'], true)) out(['ok' => false], 400);
        if (!rate('evt', 400, 600)) out(['ok' => false], 429);
        if ($t === 'ping' || $t === 'visit' || $t === 'online') {
            $g = geoip_lookup(ip());
            $db->prepare('REPLACE INTO live(sid,email,ts,ip,country,city,lat,lon) VALUES(?,?,?,?,?,?,?,?)')
               ->execute([$sid, $_SESSION['email'] ?? '', time(), ip(), $g['country'] ?? '', $g['city'] ?? '', $g['lat'] ?? null, $g['lon'] ?? null]);
        }
        if ($t === 'close' || $t === 'offline') $db->prepare('DELETE FROM live WHERE sid=?')->execute([$sid]);
        if ($t !== 'ping' && $t !== 'offline' && $t !== 'online') logev($t, (string)($b['detail'] ?? ''), $sid);
        out(['ok' => true]);
    }

    if ($_SERVER['REQUEST_METHOD'] !== 'POST' || ($_SERVER['HTTP_X_REQ'] ?? '') !== '1') out(['ok' => false, 'error' => 'درخواست نامعتبر'], 400);

    /* ==================== آمار زنده سایت ==================== */

    /* ==================== کپچا چک ==================== */
    if ($a === 'captcha_check') {
        if (!rate('cap', 20, 600)) out(['ok' => false, 'error' => 'تلاش زیاد'], 429);
        if (!empty($b['hp'])) { logev('captcha_fail', 'honeypot'); ip_rep_update(-10, 'fail'); out(['ok' => false, 'error' => 'تایید ناموفق'], 400); }
        $cap = $_SESSION['cap'] ?? null;
        if (!$cap || !isset($cap['ans']) || time() - $cap['ts'] > 300) out(['ok' => false, 'error' => 'چالش منقضی شد', 'refresh' => true], 400);
        $sel = $b['sel'] ?? [];
        if (!is_array($sel)) $sel = [];
        $sel = array_values(array_unique(array_filter(array_map('intval', $sel), function ($x) { return $x >= 0 && $x <= 8; })));
        sort($sel);
        $ans = $cap['ans']; sort($ans);
        if (microtime(true) - (float)($cap['mt'] ?? 0) < 0.8) { unset($_SESSION['cap']); logev('captcha_fail', 'خیلی سریع'); ip_rep_update(-5, 'fail'); out(['ok' => false, 'error' => 'خیلی سریع بود؛ دوباره امتحان کن', 'refresh' => true], 400); }
        if ($sel !== $ans) {
            $_SESSION['cap']['t']++; logev('captcha_fail', 'انتخاب اشتباه');
            ip_rep_update(-3, 'fail');
            if ($_SESSION['cap']['t'] >= 3) { unset($_SESSION['cap']); out(['ok' => false, 'error' => 'انتخاب اشتباه بود؛ تصاویر جدید', 'refresh' => true], 400); }
            out(['ok' => false, 'error' => 'انتخاب اشتباه است، دوباره امتحان کن'], 400);
        }
        unset($_SESSION['cap']); $_SESSION['human'] = time();
        logev('captcha', 'تایید شد');
        ip_rep_update(2, 'success');
        out(['ok' => true]);
    }

    /* ==================== ورود گوگل ==================== */
    if ($a === 'google') {
        if (!human_ok()) out(['ok' => false, 'error' => 'اول تایید کن که ربات نیستی'], 403);
        if (!rate('google', 15, 600)) out(['ok' => false, 'error' => 'تلاش زیاد'], 429);
        if (is_likely_bot()) { ip_rep_update(-15, 'fail'); out(['ok' => false, 'error' => 'دسترسی نامعتبر'], 403); }
        $cid = st('google_id');
        if (!$cid) out(['ok' => false, 'error' => 'ورود با گوگل فعال نشده'], 400);
        $raw = http_raw('https://oauth2.googleapis.com/tokeninfo?id_token=' . urlencode((string)($b['credential'] ?? '')));
        if ($raw === null) out(['ok' => false, 'error' => 'اتصال به گوگل ممکن نشد'], 502);
        $j = json_decode($raw, true);
        if (!$j || ($j['aud'] ?? '') !== $cid || !in_array($j['iss'] ?? '', ['accounts.google.com', 'https://accounts.google.com'], true)
            || (int)($j['exp'] ?? 0) < time() || !in_array($j['email_verified'] ?? '', ['true', true], true) || empty($j['email'])) {
            logev('google_fail', 'توکن نامعتبر');
            ip_rep_update(-5, 'fail');
            $db->prepare('INSERT INTO login_attempts(ts,ip,email,success,method,fp) VALUES(?,?,?,?,?,?)')->execute([time(), ip(), '', 0, 'google', fp_hash()]);
            out(['ok' => false, 'error' => 'ورود گوگل ناموفق'], 401);
        }
        $em = strtolower($j['email']);
        $r = loginUser($em, 'google', (string)($j['name'] ?? ''), (string)($j['picture'] ?? ''));
        $db->prepare('INSERT INTO login_attempts(ts,ip,email,success,method,fp) VALUES(?,?,?,?,?,?)')->execute([time(), ip(), $em, $r === true ? 1 : 0, 'google', fp_hash()]);
        if ($r === true) {
            out(['ok' => true, 'email' => $em]);
        } elseif (is_array($r) && !empty($r['need_2fa'])) {
            out(['ok' => false, 'need_2fa' => true, 'email' => $em, 'message' => 'کد تایید دو مرحله‌ای رو وارد کن']);
        } else {
            ip_rep_update(-3, 'fail');
            out(['ok' => false, 'error' => $r], 403);
        }
    }

    /* ==================== ورود با ایمیل (OTP) ==================== */
    if ($a === 'email_otp_start') {
        if (st('email_otp_on', '1') !== '1') out(['ok' => false, 'error' => 'ورود با ایمیل غیرفعاله'], 403);
        if (!human_ok()) out(['ok' => false, 'error' => 'اول تایید کن که ربات نیستی'], 403);
        if (!rate('otp_start', 5, 3600)) out(['ok' => false, 'error' => 'تلاش زیاد، یک ساعت دیگه'], 429);
        if (is_likely_bot()) { ip_rep_update(-10, 'fail'); out(['ok' => false, 'error' => 'دسترسی نامعتبر'], 403); }
        $email = strtolower(trim((string)($b['email'] ?? '')));
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) out(['ok' => false, 'error' => 'ایمیل معتبر نیست'], 400);
        if (mb_strlen($email) > 150) out(['ok' => false, 'error' => 'ایمیل خیلی طولانی'], 400);
        // بلاک ایمیل‌های موقت
        if (st('block_disp', '1') === '1') {
            $disposable = ['tempmail', '10minutemail', 'guerrillamail', 'mailinator', 'throwaway', 'yopmail', 'temp-mail', 'fakeinbox', 'sharklasers', 'getnada', 'dispostable'];
            $dom = substr(strrchr($email, '@'), 1);
            foreach ($disposable as $d) if (stripos($dom, $d) !== false) out(['ok' => false, 'error' => 'ایمیل‌های موقت قبول نمی‌شن'], 400);
        }
        // چک واقعی وجود دامنه ایمیل (MX/A)
        if (function_exists('checkdnsrr') && st('mx_check', '1') === '1') {
            $dom0 = substr(strrchr($email, '@'), 1);
            $dnsOk = @checkdnsrr('gmail.com.', 'MX');
            if ($dnsOk && !@checkdnsrr($dom0 . '.', 'MX') && !@checkdnsrr($dom0 . '.', 'A')) out(['ok' => false, 'error' => 'دامنه این ایمیل وجود ندارد؛ یک ایمیل درست وارد کن'], 400);
        }
        // چک کاربر مسدود
        $u = $db->prepare('SELECT blocked FROM users WHERE email=?'); $u->execute([$email]);
        $uRow = $u->fetch(PDO::FETCH_ASSOC);
        if ($uRow && (int)$uRow['blocked']) out(['ok' => false, 'error' => 'حساب شما مسدود شده'], 403);
        // اگه ثبت‌نام بسته‌ست و کاربر جدیده
        if (!$uRow && st('allow_reg', '1') === '0') out(['ok' => false, 'error' => 'ثبت‌نام بسته است'], 403);

        // محدودیت برای هر ایمیل (جلوگیری از بمباران ایمیل کسی)
        $lc = $db->prepare('SELECT COUNT(*) c, MAX(ts) m FROM email_otp WHERE email=? AND purpose=? AND ts>?');
        $lc->execute([$email, 'login', time() - 3600]);
        $lr = $lc->fetch(PDO::FETCH_ASSOC);
        if ((int)$lr['m'] > time() - 45) out(['ok' => false, 'error' => 'چند ثانیه صبر کن و دوباره امتحان کن'], 429);
        if ((int)$lr['c'] >= 6) out(['ok' => false, 'error' => 'برای این ایمیل درخواست زیاد بوده، بعداً تلاش کن'], 429);
        // بدون SMTP، فقط وقتی ادمین «حالت دمو» را روشن کرده کد نمایش داده می‌شود (ناامن، فقط برای تست)
        if (!smtp_ready() && st('otp_demo', '0') !== '1') out(['ok' => false, 'error' => 'ارسال ایمیل هنوز تنظیم نشده؛ به ادمین اطلاع بده'], 503);
        $code = otp_create($email, 'login');
        if (!smtp_ready()) {
            logev('email_otp_sent', 'دمو: ' . $email);
            out(['ok' => true, 'demo' => true, 'demo_code' => $code, 'message' => 'حالت دمو — کد نمایش داده شد']);
        }
        $res = send_otp_email($email, $code);
        if (!$res['ok']) {
            logev('email_otp_fail', $res['error'] ?? '');
            out(['ok' => false, 'error' => 'ارسال ایمیل ناموفق: ' . ($res['error'] ?? 'خطای نامشخص')], 500);
        }
        logev('email_otp_sent', $email);
        out(['ok' => true, 'message' => 'کد به ایمیل شما ارسال شد']);
    }

    if ($a === 'email_otp_verify') {
        if (st('email_otp_on', '1') !== '1') out(['ok' => false, 'error' => 'ورود با ایمیل غیرفعاله'], 403);
        if (!rate('otp_verify', 20, 3600)) out(['ok' => false, 'error' => 'تلاش زیاد'], 429);
        $email = strtolower(trim((string)($b['email'] ?? '')));
        $code = trim((string)($b['code'] ?? ''));
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) out(['ok' => false, 'error' => 'ایمیل معتبر نیست'], 400);
        $v = otp_verify($email, $code, 'login');
        if (!$v['ok']) {
            logev('email_otp_fail', $email);
            ip_rep_update(-3, 'fail');
            out(['ok' => false, 'error' => $v['error']], 400);
        }
        $r = loginUser($email, 'email');
        if ($r === true) {
            logev('email_login', $email);
            out(['ok' => true, 'email' => $email]);
        } elseif (is_array($r) && !empty($r['need_2fa'])) {
            out(['ok' => false, 'need_2fa' => true, 'email' => $email, 'message' => 'کد 2FA رو وارد کن']);
        } else {
            out(['ok' => false, 'error' => $r], 403);
        }
    }

    /* ==================== تایید 2FA در ورود ==================== */
    if ($a === 'user_2fa_login') {
        $em = $_SESSION['pending_2fa_email'] ?? '';
        if (!$em) out(['ok' => false, 'error' => 'جلسه منقضی شده، دوباره وارد شو'], 400);
        if (time() - (int)($_SESSION['pending_2fa_time'] ?? 0) > 600) {
            unset($_SESSION['pending_2fa_email'], $_SESSION['pending_2fa_method'], $_SESSION['pending_2fa_name'], $_SESSION['pending_2fa_avatar'], $_SESSION['pending_2fa_time']);
            out(['ok' => false, 'error' => 'جلسه منقضی شده، دوباره وارد شو'], 400);
        }
        if (!rate('u2fa_login', 10, 600)) out(['ok' => false, 'error' => 'تلاش زیاد'], 429);
        $code = preg_replace('/[^A-Za-z0-9]/', '', (string)($b['code'] ?? ''));
        if (!user_2fa_verify_code($em, $code)) {
            ip_rep_update(-10, 'fail');
            logev('2fa_fail_login');
            audit('2fa_fail_login', $em, 'warn');
            $_SESSION['pending_2fa_fails'] = (int)($_SESSION['pending_2fa_fails'] ?? 0) + 1;
            // هشدار ایمیلی (حداکثر یک‌بار در ساعت)
            $rc = $db->prepare("SELECT COUNT(*) FROM audit_log WHERE action='2fa_fail_alert' AND detail=? AND ts>?");
            $rc->execute([$em, time() - 3600]);
            if ((int)$rc->fetchColumn() === 0) {
                audit('2fa_fail_alert', $em, 'warn');
                security_mail($em, 'تلاش ناموفق برای ورود به حساب شما', '⚠️ کد تایید دو مرحله‌ای اشتباه وارد شد',
                    '<p style="margin:0">کسی با رمز یک‌بارمصرف درست وارد مرحله تایید دو مرحله‌ای حساب شما شد اما کد دوم را اشتباه زد. اگر شما نبودید، نگران نباشید؛ بدون کد دوم وارد نمی‌شود، ولی بهتر است نشست‌ها را بررسی کنید.</p>', [], true);
            }
            if ((int)$_SESSION['pending_2fa_fails'] >= 5) {
                unset($_SESSION['pending_2fa_email'], $_SESSION['pending_2fa_method'], $_SESSION['pending_2fa_name'], $_SESSION['pending_2fa_avatar'], $_SESSION['pending_2fa_time'], $_SESSION['pending_2fa_fails']);
                out(['ok' => false, 'error' => 'تلاش بیش از حد؛ دوباره وارد شو', 'restart' => true], 429);
            }
            out(['ok' => false, 'error' => 'کد اشتباه است'], 400);
        }
        $m = $_SESSION['pending_2fa_method'] ?? 'google';
        $name = $_SESSION['pending_2fa_name'] ?? '';
        $avatar = $_SESSION['pending_2fa_avatar'] ?? '';
        unset($_SESSION['pending_2fa_email'], $_SESSION['pending_2fa_method'], $_SESSION['pending_2fa_name'], $_SESSION['pending_2fa_avatar'], $_SESSION['pending_2fa_time']);
        guest_to_user($em);
        session_regenerate_id(true);
        $_SESSION['email'] = $em;
        $_SESSION['initial_ip'] = ip();
        $db->prepare('INSERT OR IGNORE INTO users(email,method,first,last,logins,blocked,name,avatar) VALUES(?,?,?,?,0,0,?,?)')->execute([$em, $m, time(), time(), $name, $avatar]);
        $db->prepare('UPDATE users SET last=?,logins=logins+1 WHERE email=?')->execute([time(), $em]);
        $isNewDev = !login_known_device($em);
        unset($_SESSION['pending_2fa_fails']);
        logev('login_2fa', $em);
        ip_rep_update(5, 'success');
        audit('login_2fa', $em, 'info');
        session_register();
