            if (!function_exists('mp_name')) {
                function mp_name($email) { global $db; $s = $db->prepare('SELECT name FROM users WHERE email=?'); $s->execute([$email]); $n = trim((string)$s->fetchColumn()); if ($n === '') $n = substr($email, 0, 3) . '***'; return mb_substr($n, 0, 16); }
                function mp_new_state($g) { if ($g === 'xo') return ['b' => array_fill(0, 9, 0)]; if ($g === 'c4') return ['b' => array_fill(0, 42, 0), 'last' => -1]; return ['p' => [0, 0], 's' => [0, 0], 'round' => 1, 'last' => null]; }
                function mp_you($r, $me) { return $r['p1'] === $me ? 1 : ($r['p2'] === $me ? 2 : 0); }
                function mp_c4win($b, $idx) {
                    $r = intdiv($idx, 7); $c = $idx % 7; $p = $b[$idx];
                    foreach ([[0, 1], [1, 0], [1, 1], [1, -1]] as $d) {
                        $n = 1;
                        foreach ([1, -1] as $s) { $rr = $r + $d[0] * $s; $cc = $c + $d[1] * $s; while ($rr >= 0 && $rr < 6 && $cc >= 0 && $cc < 7 && $b[$rr * 7 + $cc] === $p) { $n++; $rr += $d[0] * $s; $cc += $d[1] * $s; } }
                        if ($n >= 4) return true;
                    }
                    return false;
                }
