                    'sub' => vpn_sub_url($s['token']), 'alt' => vpn_sub_url_alt($s['token']), 'used' => $used, 'limit' => $lim, 'pct' => $lim > 0 ? min(100, round($used / $lim * 100, 1)) : 0,
