function csv_cell($v) { $v = (string)$v; if ($v !== '' && strpos('=+-@', $v[0]) !== false) $v = "'" . $v; return '"' . str_replace('"', '""', $v) . '"'; }
function pf($do, $f, $label, $cls = '', $conf = '') {
    $h = '<form method="post" style="display:inline"' . ($conf ? ' onsubmit="return confirm(\'' . e($conf) . '\')"' : '') . '><input type="hidden" name="do" value="' . e($do) . '"><input type="hidden" name="csrf" value="' . e($_SESSION['csrf']) . '">';
    foreach ($f as $k => $v) $h .= '<input type="hidden" name="' . e($k) . '" value="' . e($v) . '">';
    return $h . '<button class="sm ' . $cls . '">' . e($label) . '</button></form>';
}
function pager($total, $per, $p, $url) {
    $n = max(1, (int)ceil($total / $per)); if ($n < 2) return '';
    $h = '<div class="pg">';
    for ($i = max(1, $p - 3); $i <= min($n, $p + 3); $i++) $h .= '<a class="' . ($i == $p ? 'on' : '') . '" href="' . e($url . '&p=' . $i) . '">' . $i . '</a>';
    return $h . '</div>';
}
function chart($days) {
    $max = 1; foreach ($days as $d) $max = max($max, $d[1], $d[2]);
    $w = 700; $h = 190; $bw = ($w - 30) / count($days);
    $s = '<svg viewBox="0 0 ' . $w . ' ' . ($h + 26) . '" style="width:100%;height:auto"><line x1="20" y1="' . $h . '" x2="' . $w . '" y2="' . $h . '" stroke="#2a2f5e"/>';
    foreach ($days as $i => $d) {
        $x = 24 + $i * $bw; $h1 = $d[1] / $max * ($h - 14); $h2 = $d[2] / $max * ($h - 14);
        $s .= '<rect x="' . round($x + 2, 1) . '" y="' . round($h - $h1, 1) . '" width="' . round($bw / 2 - 3, 1) . '" height="' . round($h1, 1) . '" rx="3" fill="#7c5cff"></rect>';
        $s .= '<rect x="' . round($x + $bw / 2, 1) . '" y="' . round($h - $h2, 1) . '" width="' . round($bw / 2 - 3, 1) . '" height="' . round($h2, 1) . '" rx="3" fill="#27d3c3"></rect>';
        $s .= '<text x="' . round($x + $bw / 2, 1) . '" y="' . ($h + 16) . '" font-size="10" fill="#9aa0cf" text-anchor="middle">' . e($d[0]) . '</text>';
    }
    return $s . '</svg>';
}
function admin_pw_ok($pw) {
    global $ADMIN_PASSWORD;
    $h = st('admin_hash');
    return $h !== '' ? password_verify($pw, $h) : hash_equals($ADMIN_PASSWORD, $pw);
}

/* ===================== ربات مادر (از پنل مدیریت) ===================== */
function a2_bot_bindings($d1, $bt, $sec, $apiUrl, $apiSec, $ownerId) {
    global $PANEL_VERSION, $ADMIN_SLUG;
    $siteBase = rtrim((string)st('site_url', ''), '/');
    if ($siteBase === '') $siteBase = rtrim((string)vpn_base_url(), '/');
    $adminUrl = preg_replace('#/index\.php$#i', '', $siteBase) . '/index.php?' . $ADMIN_SLUG;
    return [
        ['type' => 'd1', 'name' => 'BOT_DB', 'id' => $d1],
        ['type' => 'secret_text', 'name' => 'BOT_TOKEN', 'text' => $bt],
        ['type' => 'secret_text', 'name' => 'WEBHOOK_SECRET', 'text' => $sec],
        ['type' => 'secret_text', 'name' => 'PANEL_API', 'text' => $apiUrl],
        ['type' => 'secret_text', 'name' => 'PANEL_API_SECRET', 'text' => $apiSec],
        ['type' => 'secret_text', 'name' => 'BOT_OWNER_ID', 'text' => (string)$ownerId],
        ['type' => 'secret_text', 'name' => 'BOT_VERSION', 'text' => (string)$PANEL_VERSION],
        ['type' => 'secret_text', 'name' => 'ADMIN_URL', 'text' => $adminUrl],
    ];
}
function a2_bot_api_url() {
    $base = rtrim((string)st('site_url', ''), '/');
    if ($base === '') { $base = rtrim((string)vpn_base_url(), '/'); setst('site_url', $base); }
    return (preg_match('#/index\.php$#i', $base) ? $base : $base . '/index.php') . '?tg_api=1';
}
function a2_bot_deploy($cfIn, $bt, $accIn, $ownerIn) {
    global $db, $PANEL_VERSION;
    if (!preg_match('/^[A-Za-z0-9_\-]{30,100}$/', $cfIn)) return ['ok' => false, 'msg' => 'Cloudflare API Token معتبر نیست.'];
    if (!preg_match('/^\d{6,12}:[A-Za-z0-9_\-]{30,100}$/', $bt)) return ['ok' => false, 'msg' => 'Bot Token معتبر نیست.'];
    if (!preg_match('/^-?\d{5,15}$/', $ownerIn)) return ['ok' => false, 'msg' => 'Owner ID تلگرام معتبر نیست.'];
    $me = http('https://api.telegram.org/bot' . $bt . '/getMe');
    if (!is_array($me) || empty($me['ok'])) return ['ok' => false, 'msg' => 'توکن ربات معتبر نیست.'];
    $ar = cf_req($cfIn, 'GET', '/accounts'); $accounts = $ar['result'] ?? [];
    if (empty($ar['success']) || !is_array($accounts) || !count($accounts)) return ['ok' => false, 'msg' => 'توکن Cloudflare حساب‌ها را نخواند: ' . cf_err($ar)];
    $picked = null;
    foreach ($accounts as $aa) { if ($accIn !== '' && (string)($aa['id'] ?? '') === $accIn) { $picked = $aa; break; } }
    if (!$picked) $picked = $accounts[0];
    $accId = (string)$picked['id']; $accName = (string)($picked['name'] ?? $accId);
    $subR = cf_req($cfIn, 'GET', '/accounts/' . rawurlencode($accId) . '/workers/subdomain');
    $sub = (string)($subR['result']['subdomain'] ?? '');
    if ($sub === '') {
        $cand = 'demon-' . strtolower(bin2hex(random_bytes(3)));
        $sr = cf_req($cfIn, 'PUT', '/accounts/' . rawurlencode($accId) . '/workers/subdomain', ['subdomain' => $cand]);
        if (!empty($sr['success'])) $sub = $cand;
    }
    if ($sub === '') return ['ok' => false, 'msg' => 'workers.dev این حساب فعال نشد: ' . cf_err($subR)];
    $dn = 'demon-teacher-' . strtolower(bin2hex(random_bytes(3)));
    $dr = cf_req($cfIn, 'POST', '/accounts/' . rawurlencode($accId) . '/d1/database', ['name' => 'demon-teacher-' . date('ymd-His')]);
    $d1 = (string)($dr['result']['uuid'] ?? '');
    if (empty($dr['success']) || $d1 === '') return ['ok' => false, 'msg' => 'ساخت دیتابیس D1 ناموفق بود: ' . cf_err($dr)];
    $sec = bin2hex(random_bytes(32));
    $apiUrl = a2_bot_api_url();
    $apiSec = trim((string)st('tg_security_token', ''));
    if ($apiSec === '') { $apiSec = bin2hex(random_bytes(32)); setst('tg_security_token', $apiSec); }
    $up = cf_worker_upload($cfIn, $accId, $dn, cf_template('tg_teacher'), a2_bot_bindings($d1, $bt, $sec, $apiUrl, $apiSec, $ownerIn), ['secret_text'], '');
    if (empty($up['success'])) return ['ok' => false, 'msg' => 'ساخت Worker ربات ناموفق بود: ' . cf_err($up)];
    $en = cf_req($cfIn, 'POST', '/accounts/' . rawurlencode($accId) . '/workers/scripts/' . rawurlencode($dn) . '/subdomain', ['enabled' => true, 'previews_enabled' => false]);
    if (empty($en['success'])) return ['ok' => false, 'msg' => 'فعال‌سازی workers.dev ناموفق بود: ' . cf_err($en)];
    $hook = 'https://' . $dn . '.' . $sub . '.workers.dev/';
    $wh = http('https://api.telegram.org/bot' . $bt . '/setWebhook', ['Content-Type' => 'application/x-www-form-urlencoded'],
        http_build_query(['url' => $hook, 'secret_token' => $sec, 'allowed_updates' => json_encode(['message', 'callback_query', 'chat_member']), 'drop_pending_updates' => 'true']));
    if (!is_array($wh) || empty($wh['ok'])) return ['ok' => false, 'msg' => 'Webhook ربات فعال نشد: ' . (is_array($wh) ? ($wh['description'] ?? 'خطا') : 'ارتباط ناموفق')];
    $uname = (string)($me['result']['username'] ?? '');
    $db->exec("CREATE TABLE IF NOT EXISTS teacher_bot_config(id INTEGER PRIMARY KEY CHECK(id=1),cf_token_enc TEXT,bot_token_enc TEXT,account_id TEXT,account_name TEXT,d1_id TEXT,worker_name TEXT,worker_url TEXT,bot_username TEXT,status TEXT DEFAULT 'off',error TEXT,updated INTEGER DEFAULT 0,bot_version TEXT DEFAULT '5.21.0',owner_id TEXT DEFAULT '7323216202')");
    $db->prepare("REPLACE INTO teacher_bot_config(id,cf_token_enc,bot_token_enc,account_id,account_name,d1_id,worker_name,worker_url,bot_username,status,error,updated,bot_version,owner_id) VALUES(1,?,?,?,?,?,?,?,?,?,?,?,?,?)")
        ->execute([aes_encrypt($cfIn), aes_encrypt($bt), $accId, $accName, $d1, $dn, $hook, $uname, 'on', '', time(), (string)$PANEL_VERSION, $ownerIn]);
    d1_q($cfIn, $accId, $d1, "CREATE TABLE IF NOT EXISTS settings(k TEXT PRIMARY KEY,v TEXT)");
    d1_q($cfIn, $accId, $d1, "REPLACE INTO settings(k,v) VALUES(?,?)", ['bot_enabled', '1']);
    setst('tg_bot_on', '1'); setst('tg_bot_username', $uname); setst('tg_teacher_worker', $dn); setst('tg_teacher_d1', $d1);
    setst('tg_teacher_url', $hook); setst('tg_teacher_version', (string)$PANEL_VERSION); setst('tg_owner_id', $ownerIn);
    audit('teacher_bot_deploy', $dn, 'info');
    return ['ok' => true, 'msg' => 'ربات مادر روشن شد' . ($uname !== '' ? ' · @' . $uname : '') . '.'];
}
function a2_bot_diag() {
    $tc = teacher_bot_config_row();
    if (empty($tc['bot_token_enc']) || empty($tc['worker_url'])) return ['ok' => false, 'msg' => 'ربات مادر نصب نشده است.'];
    $bt = aes_decrypt((string)$tc['bot_token_enc']);
    $wi = http('https://api.telegram.org/bot' . $bt . '/getWebhookInfo');
    $info = is_array($wi) ? ($wi['result'] ?? []) : [];
    $url = (string)($info['url'] ?? '');
    $err = (string)($info['last_error_message'] ?? '');
    $pending = (int)($info['pending_update_count'] ?? 0);
    $wkTxt = trim((string)http_raw((string)$tc['worker_url'], [], null));
    $ok = $url !== '' && $err === '' && $wkTxt !== '';
    return ['ok' => $ok, 'msg' => 'Webhook: ' . ($url !== '' ? $url : 'تنظیم نشده') . ' · در صف: ' . $pending . ' · آخرین خطای تلگرام: ' . ($err !== '' ? $err : 'ندارد') . ' · پاسخ Worker: ' . ($wkTxt !== '' ? mb_substr($wkTxt, 0, 80) : 'بدون پاسخ')];
}
function a2_force_resolve($link) {
    if (!preg_match('#^https://t\.me/([A-Za-z0-9_]{5,64})/?$#i', trim((string)$link), $m)) return ['ok' => false, 'msg' => 'لینک عمومی کانال معتبر نیست؛ مثلاً https://t.me/channelname (لینک‌های خصوصی پشتیبانی نمی‌شوند).'];
    $row = teacher_bot_config_row();
    if (empty($row['bot_token_enc'])) return ['ok' => false, 'msg' => 'ابتدا ربات مادر را نصب کن.'];
    $bt = aes_decrypt((string)$row['bot_token_enc']);
    $me = http('https://api.telegram.org/bot' . $bt . '/getMe');
    $botId = (string)($me['result']['id'] ?? '');
    if ($botId === '') return ['ok' => false, 'msg' => 'توکن ربات خوانده نشد.'];
    $chat = http('https://api.telegram.org/bot' . $bt . '/getChat', ['Content-Type' => 'application/json'], json_encode(['chat_id' => '@' . $m[1]]));
    if (empty($chat['ok'])) return ['ok' => false, 'msg' => 'کانال پیدا نشد: ' . ($chat['description'] ?? 'خطا')];
    $cid = (string)$chat['result']['id'];
    $title = (string)($chat['result']['title'] ?? $m[1]);
    $cm = http('https://api.telegram.org/bot' . $bt . '/getChatMember', ['Content-Type' => 'application/json'], json_encode(['chat_id' => $cid, 'user_id' => (int)$botId]));
    if (!in_array((string)($cm['result']['status'] ?? ''), ['administrator', 'creator'], true)) return ['ok' => false, 'msg' => 'ربات باید در این کانال ادمین باشد، بعد دوباره تلاش کن.'];
    return ['ok' => true, 'id' => $cid, 'title' => $title, 'url' => 'https://t.me/' . $m[1]];
}
function a2_notify_owner($html, $kb = null) {
    $row = teacher_bot_config_row();
    $owner = trim((string)st('tg_owner_id', ''));
    if (empty($row['bot_token_enc']) || $owner === '') { setst('notify_last', json_encode(['at' => time(), 'ok' => false, 'desc' => 'مالک یا توکن ربات تنظیم نشده']) ); return; }
    $bt = aes_decrypt((string)$row['bot_token_enc']);
    if ($bt === '') { setst('notify_last', json_encode(['at' => time(), 'ok' => false, 'desc' => 'توکن ربات خوانده نشد']) ); return; }
    $res = tg_send_safe($bt, ['chat_id' => $owner, 'text' => $html, 'parse_mode' => 'HTML', 'disable_web_page_preview' => true, 'reply_markup' => $kb ? ['inline_keyboard' => $kb] : null]); if (false) http('https://api.telegram.org/bot' . $bt . '/sendMessage', ['Content-Type' => 'application/json'],
        json_encode(array_filter(['chat_id' => $owner, 'text' => $html, 'parse_mode' => 'HTML', 'disable_web_page_preview' => true, 'reply_markup' => $kb ? ['inline_keyboard' => $kb] : null], function ($v) { return $v !== null; }), JSON_UNESCAPED_UNICODE));
    setst('notify_last', json_encode(['at' => time(), 'ok' => !empty($res['ok']), 'desc' => (string)($res['description'] ?? (is_array($res) ? '' : 'بدون پاسخ از تلگرام'))]));
}
function a2_user_email($chat) { return 'tg_' . ltrim(preg_replace('/[^0-9\-]/', '', (string)$chat), '-') . '@telegram.local'; }
function a2_user_set_ban($chat, $ban) {
    global $db;
    $chat = preg_replace('/[^0-9\-]/', '', (string)$chat);
    if ($chat === '') return 'شناسه نامعتبر است.';
    $db->exec("CREATE TABLE IF NOT EXISTS tg_users(chat_id TEXT PRIMARY KEY,email TEXT UNIQUE,username TEXT,first_name TEXT,created INTEGER,last_seen INTEGER,banned INTEGER DEFAULT 0)");
    $db->prepare("INSERT INTO tg_users(chat_id,email,created,last_seen,banned) VALUES(?,?,?,?,?) ON CONFLICT(chat_id) DO UPDATE SET banned=excluded.banned")
        ->execute([$chat, a2_user_email($chat), time(), time(), $ban ? 1 : 0]);
    $row = teacher_bot_config_row();
    if (!empty($row['d1_id']) && !empty($row['account_id'])) {
        $cf = aes_decrypt((string)$row['cf_token_enc']);
        if ($cf !== '') d1_q($cf, $row['account_id'], $row['d1_id'], "UPDATE users SET banned=? WHERE chat_id=?", [$ban ? 1 : 0, $chat]);
    }
    return $ban ? 'کاربر بن شد.' : 'بن کاربر برداشته شد.';
}
function a2_user_delete_panels($chat) {
    global $db;
    $q = $db->prepare("SELECT * FROM vpn_services WHERE email=?"); $q->execute([a2_user_email($chat)]);
    $n = 0;
    foreach ($q->fetchAll(PDO::FETCH_ASSOC) as $svc) {
        $sid = (int)$svc['id'];
        foreach (vpn_nodes_of($sid) as $nd) { try { vpn_node_destroy($nd, $svc); } catch (Throwable $e) {} }
        $db->prepare("DELETE FROM vpn_nodes WHERE service_id=?")->execute([$sid]);
        $db->prepare("DELETE FROM vpn_services WHERE id=?")->execute([$sid]);
        $n++;
    }
    return $n ? $n . ' پنل این کاربر حذف شد.' : 'پنلی برای این کاربر پیدا نشد.';
}
function a2_panel_delete($id) {
    global $db;
    $q = $db->prepare('SELECT * FROM panel_records WHERE id=?'); $q->execute([(int)$id]);
    $p = $q->fetch(PDO::FETCH_ASSOC);
    if (!$p) return 'پنل پیدا نشد.';
    $cf = aes_decrypt((string)($p['cf_token_enc'] ?? ''));
    $msgs = [];
    if ($cf !== '' && !empty($p['account_id'])) {
        if (!empty($p['worker'])) { $r = cf_req($cf, 'DELETE', '/accounts/' . rawurlencode($p['account_id']) . '/workers/scripts/' . rawurlencode($p['worker'])); $msgs[] = !empty($r['success']) ? 'Worker حذف شد' : 'حذف Worker ناموفق'; }
        if (!empty($p['d1_id'])) { $r = cf_req($cf, 'DELETE', '/accounts/' . rawurlencode($p['account_id']) . '/d1/database/' . rawurlencode($p['d1_id'])); $msgs[] = !empty($r['success']) ? 'D1 حذف شد' : 'حذف D1 ناموفق'; }
    }
    $db->prepare('DELETE FROM panel_records WHERE id=?')->execute([(int)$id]);
    return 'پنل «' . $p['worker'] . '» حذف شد.' . ($msgs ? ' ' . implode(' · ', $msgs) . '.' : '');
}
function ub_table() { global $db; $db->exec("CREATE TABLE IF NOT EXISTS user_bots(id INTEGER PRIMARY KEY AUTOINCREMENT,owner_chat TEXT,acc_id INTEGER,bot_token_enc TEXT,bot_username TEXT,account_id TEXT,d1_id TEXT,worker_name TEXT,worker_url TEXT,status TEXT DEFAULT 'on',created INTEGER)"); }
function ub_accounts($tgEmail) { global $db; $q = $db->prepare("SELECT id,account_id FROM cf_accts WHERE email=? AND status='ok' ORDER BY id"); $q->execute([$tgEmail]); return $q->fetchAll(PDO::FETCH_ASSOC); }
function ub_list($chat) { global $db; ub_table(); $q = $db->prepare("SELECT id,bot_username,status FROM user_bots WHERE owner_chat=? ORDER BY id DESC"); $q->execute([(string)$chat]); return $q->fetchAll(PDO::FETCH_ASSOC); }
function ub_create($chat, $tgEmail, $accId, $bt) {
    global $db;
    ub_table();
    if (!preg_match('/^\d{6,12}:[A-Za-z0-9_\-]{30,100}$/', $bt)) return ['ok' => false, 'error' => 'توکن ربات معتبر نیست.'];
    $q = $db->prepare("SELECT * FROM cf_accts WHERE id=? AND email=? AND status='ok'"); $q->execute([(int)$accId, $tgEmail]); $ac = $q->fetch(PDO::FETCH_ASSOC);
    if (!$ac) return ['ok' => false, 'error' => 'حساب Cloudflare پیدا نشد.'];
    $cf = aes_decrypt((string)$ac['token_enc']); $acc = (string)$ac['account_id'];
    if ($cf === '') return ['ok' => false, 'error' => 'توکن حساب خوانده نشد.'];
    $me = http('https://api.telegram.org/bot' . $bt . '/getMe');
    if (!is_array($me) || empty($me['ok'])) return ['ok' => false, 'error' => 'توکن ربات معتبر نیست یا تلگرام در دسترس نیست.'];
    $uname = (string)($me['result']['username'] ?? '');
    $subR = cf_req($cf, 'GET', '/accounts/' . rawurlencode($acc) . '/workers/subdomain'); $sub = (string)($subR['result']['subdomain'] ?? '');
    if ($sub === '') { $cand = 'ub-' . strtolower(bin2hex(random_bytes(3))); $sr = cf_req($cf, 'PUT', '/accounts/' . rawurlencode($acc) . '/workers/subdomain', ['subdomain' => $cand]); if (!empty($sr['success'])) $sub = $cand; }
    if ($sub === '') return ['ok' => false, 'error' => 'workers.dev این حساب فعال نشد.'];
    $dr = cf_req($cf, 'POST', '/accounts/' . rawurlencode($acc) . '/d1/database', ['name' => 'ub-db-' . date('ymd-His')]);
    $d1 = (string)($dr['result']['uuid'] ?? '');
    if (empty($dr['success']) || $d1 === '') return ['ok' => false, 'error' => 'ساخت دیتابیس ناموفق: ' . cf_err($dr)];
    foreach (["CREATE TABLE IF NOT EXISTS users(chat_id TEXT PRIMARY KEY,username TEXT,first_name TEXT,created INTEGER,last_seen INTEGER,banned INTEGER DEFAULT 0)", "CREATE TABLE IF NOT EXISTS relay(owner_msg_id INTEGER PRIMARY KEY,user_chat TEXT)", "CREATE TABLE IF NOT EXISTS settings(k TEXT PRIMARY KEY,v TEXT)", "REPLACE INTO settings(k,v) VALUES('bot_enabled','1')"] as $stm) d1_q($cf, $acc, $d1, $stm);
    $secret = bin2hex(random_bytes(32)); $name = 'ub-bot-' . bin2hex(random_bytes(3));
    $up = cf_worker_upload($cf, $acc, $name, cf_template('tg_userbot'), [
        ['type' => 'd1', 'name' => 'BOT_DB', 'id' => $d1],
        ['type' => 'secret_text', 'name' => 'BOT_TOKEN', 'text' => $bt],
        ['type' => 'secret_text', 'name' => 'WEBHOOK_SECRET', 'text' => $secret],
        ['type' => 'secret_text', 'name' => 'BOT_OWNER_ID', 'text' => (string)$chat],
    ], [], '');
    if (empty($up['success'])) return ['ok' => false, 'error' => 'ساخت Worker ناموفق: ' . cf_err($up)];
    $en = cf_req($cf, 'POST', '/accounts/' . rawurlencode($acc) . '/workers/scripts/' . rawurlencode($name) . '/subdomain', ['enabled' => true, 'previews_enabled' => false]);
    if (empty($en['success'])) return ['ok' => false, 'error' => 'فعال‌سازی workers.dev ناموفق: ' . cf_err($en)];
    $hook = 'https://' . $name . '.' . $sub . '.workers.dev/';
    $wh = http('https://api.telegram.org/bot' . $bt . '/setWebhook', ['Content-Type' => 'application/x-www-form-urlencoded'],
        http_build_query(['url' => $hook, 'secret_token' => $secret, 'allowed_updates' => json_encode(['message', 'callback_query']), 'drop_pending_updates' => 'true']));
    if (!is_array($wh) || empty($wh['ok'])) return ['ok' => false, 'error' => 'Webhook ناموفق: ' . (is_array($wh) ? ($wh['description'] ?? 'خطا') : 'ارتباط ناموفق')];
    $db->prepare("INSERT INTO user_bots(owner_chat,acc_id,bot_token_enc,bot_username,account_id,d1_id,worker_name,worker_url,status,created) VALUES(?,?,?,?,?,?,?,?,?,?)")
        ->execute([(string)$chat, (int)$ac['id'], aes_encrypt($bt), $uname, $acc, $d1, $name, $hook, 'on', time()]);
    $newId = (int)$db->lastInsertId();
    $ownerId = trim((string)st('tg_owner_id', ''));
    if ($ownerId !== '') pv_send($ownerId, "<b>🤖 ربات جدید ساخته شد</b>\n\nربات: @" . e($uname) . "\nکاربر سازنده: " . e($chat) . "\nحساب Cloudflare: " . e($acc) . "\nWorker: " . e($hook) . "\nزمان: " . date('Y-m-d H:i'));
    return ['ok' => true, 'username' => $uname, 'url' => 'https://t.me/' . $uname, 'id' => $newId];
}
function ub_row_for($chat,$id) { global $db; ub_table(); $q=$db->prepare("SELECT * FROM user_bots WHERE id=? AND owner_chat=?"); $q->execute([(int)$id,(string)$chat]); return $q->fetch(PDO::FETCH_ASSOC) ?: null; }
function ub_cf_of($row) { global $db; $t=$db->prepare("SELECT token_enc FROM cf_accts WHERE id=?"); $t->execute([(int)$row['acc_id']]); return aes_decrypt((string)$t->fetchColumn()); }
function ub_delete($chat, $id) {
    global $db;
    $b = ub_row_for($chat, $id); if (!$b) return ['ok' => false, 'error' => 'ربات پیدا نشد.'];
    $cf = ub_cf_of($b); $bt = aes_decrypt((string)$b['bot_token_enc']);
    if ($bt !== '') http('https://api.telegram.org/bot' . $bt . '/deleteWebhook');
    if ($cf !== '') {
        cf_req($cf, 'DELETE', '/accounts/' . rawurlencode($b['account_id']) . '/workers/scripts/' . rawurlencode($b['worker_name']));
        if (!empty($b['d1_id'])) cf_req($cf, 'DELETE', '/accounts/' . rawurlencode($b['account_id']) . '/d1/database/' . rawurlencode($b['d1_id']));
    }
    $db->prepare("DELETE FROM user_bots WHERE id=?")->execute([(int)$b['id']]);
    return ['ok' => true];
}
function ub_update_token($chat, $id, $bt) {
    global $db, $PANEL_VERSION;
    $b = ub_row_for($chat, $id); if (!$b) return ['ok' => false, 'error' => 'ربات پیدا نشد.'];
    if (!preg_match('/^\d{6,12}:[A-Za-z0-9_\-]{30,100}$/', $bt)) return ['ok' => false, 'error' => 'توکن معتبر نیست.'];
    $me = http('https://api.telegram.org/bot' . $bt . '/getMe');
    if (!is_array($me) || empty($me['ok'])) return ['ok' => false, 'error' => 'توکن ربات معتبر نیست یا تلگرام در دسترس نیست.'];
    $cf = ub_cf_of($b); if ($cf === '') return ['ok' => false, 'error' => 'توکن حساب Cloudflare خوانده نشد.'];
    $secret = bin2hex(random_bytes(32));
    $up = cf_worker_upload($cf, $b['account_id'], $b['worker_name'], cf_template('tg_userbot'), [
        ['type' => 'd1', 'name' => 'BOT_DB', 'id' => $b['d1_id']],
        ['type' => 'secret_text', 'name' => 'BOT_TOKEN', 'text' => $bt],
        ['type' => 'secret_text', 'name' => 'WEBHOOK_SECRET', 'text' => $secret],
        ['type' => 'secret_text', 'name' => 'BOT_OWNER_ID', 'text' => (string)$chat],
    ], [], '');
    if (empty($up['success'])) return ['ok' => false, 'error' => 'به‌روزرسانی Worker ناموفق: ' . cf_err($up)];
    $hook = (string)$b['worker_url'];
    $wh = http('https://api.telegram.org/bot' . $bt . '/setWebhook', ['Content-Type' => 'application/x-www-form-urlencoded'],
        http_build_query(['url' => $hook, 'secret_token' => $secret, 'allowed_updates' => json_encode(['message', 'callback_query']), 'drop_pending_updates' => 'true']));
    if (!is_array($wh) || empty($wh['ok'])) return ['ok' => false, 'error' => 'Webhook ناموفق: ' . (is_array($wh) ? ($wh['description'] ?? 'خطا') : 'ارتباط ناموفق')];
    $db->prepare("UPDATE user_bots SET bot_token_enc=?,bot_username=? WHERE id=?")->execute([aes_encrypt($bt), (string)($me['result']['username'] ?? ''), (int)$b['id']]);
    return ['ok' => true];
}
function ub_diag($chat, $id) {
    $b = ub_row_for($chat, $id); if (!$b) return ['ok' => false, 'error' => 'ربات پیدا نشد.'];
    $bt = aes_decrypt((string)$b['bot_token_enc']);
    $wi = http('https://api.telegram.org/bot' . $bt . '/getWebhookInfo');
    $info = is_array($wi) ? ($wi['result'] ?? []) : [];
    $wk = trim((string)http_raw((string)$b['worker_url'] . '?probe=1', [], null));
    $txt = 'وب‌هوک: ' . (($info['url'] ?? '') !== '' ? $info['url'] : 'تنظیم نشده') . "\n"
         . 'در صف: ' . (int)($info['pending_update_count'] ?? 0) . "\n"
         . 'آخرین خطای تلگرام: ' . (($info['last_error_message'] ?? '') !== '' ? $info['last_error_message'] : 'ندارد') . "\n"
         . 'پاسخ Worker: ' . ($wk !== '' ? mb_substr($wk, 0, 80) : 'بدون پاسخ');
    return ['ok' => true, 'text' => $txt];
}
function pv_ensure() { global $db; try { $db->exec("ALTER TABLE vpn_services ADD COLUMN panel_version TEXT DEFAULT ''"); } catch (Throwable $e) {} }
function pv_chat_of_email($email) { return preg_match('/^tg_(-?\d+)@telegram\.local$/', (string)$email, $m) ? $m[1] : ''; }
function pv_send($chat, $html, $kb = null) {
    $row = teacher_bot_config_row(); $bt = aes_decrypt((string)($row['bot_token_enc'] ?? ''));
    if ($bt === '' || $chat === '') return false;
    $body = ['chat_id' => $chat, 'text' => $html, 'parse_mode' => 'HTML', 'disable_web_page_preview' => true];
    if ($kb) $body['reply_markup'] = ['inline_keyboard' => $kb];
    $r = tg_send_safe($bt, $body);
    return is_array($r) && !empty($r['ok']);
}
function pv_announce_update() {
    global $db, $PANEL_VERSION;
    pv_ensure();
    $q = $db->prepare("SELECT id,name,email FROM vpn_services WHERE active=1 AND (panel_version IS NULL OR panel_version<>?)"); $q->execute([(string)$PANEL_VERSION]);
    $sent = 0; $failed = 0;
    foreach ($q->fetchAll(PDO::FETCH_ASSOC) as $svc) {
        $chat = pv_chat_of_email($svc['email']);
        $ok = pv_send($chat, "<b>🔄 نسخهٔ جدید پنل منتشر شد</b>\n\nپنل: " . e($svc['name']) . "\nنسخهٔ جدید: <code>" . e((string)$PANEL_VERSION) . "</code>\n\nبا دکمهٔ زیر پنلت را به‌روز کن، یا روی همین نسخه بمان.",
            [[['text' => 'به‌روزرسانی پنل', 'callback_data' => 'upd:' . (int)$svc['id'], 'style' => 'success']], [['text' => 'ماندن روی نسخهٔ فعلی', 'callback_data' => 'updskip']]]);
        $ok ? $sent++ : $failed++;
    }
    return ['sent' => $sent, 'failed' => $failed];
}
function pv_update_service($id, $tgEmail = '') {
    global $db, $PANEL_VERSION, $TELEGRAM_SUPPORT, $TELEGRAM_CHANNEL;
    pv_ensure();
    $q = $db->prepare("SELECT * FROM vpn_services WHERE id=?"); $q->execute([(int)$id]); $svc = $q->fetch(PDO::FETCH_ASSOC);
    if (!$svc) return ['ok' => false, 'error' => 'پنل پیدا نشد.'];
    if ($tgEmail !== '' && $svc['email'] !== $tgEmail) return ['ok' => false, 'error' => 'این پنل متعلق به شما نیست.'];
    $nodes = vpn_nodes_of((int)$id);
    if (!$nodes) return ['ok' => false, 'error' => 'Worker این پنل پیدا نشد.'];
    $src = str_replace(['__SUPPORT__', '__CHANNEL__'], [(string)$TELEGRAM_SUPPORT, (string)$TELEGRAM_CHANNEL], cf_template('vpn'));
    foreach ($nodes as $n) {
        $tk = aes_decrypt((string)($n['token_enc'] ?? ''));
        if ($tk === '') return ['ok' => false, 'error' => 'توکن حساب Cloudflare خوانده نشد.'];
        $acc = (string)$n['account_id'];
        $d1 = (string)($n['d1_id'] ?? '');
        $chk = $d1 !== '' ? cf_req($tk, 'GET', '/accounts/' . rawurlencode($acc) . '/d1/database/' . rawurlencode($d1)) : ['success' => false];
        if (empty($chk['success'])) {
            return ['ok' => false, 'code' => 'db_missing', 'error' => 'دیتابیس این سرویس حذف شده است؛ نمی‌توانی پنل را آپدیت کنی. می‌توانی پنل را حذف کنی.'];
        }
        $up = cf_worker_upload($tk, $n['account_id'], $n['worker'], $src,
            [['type' => 'd1', 'name' => 'DB', 'id' => $d1], ['type' => 'secret_text', 'name' => 'PANEL_VERSION', 'text' => (string)$PANEL_VERSION]],
            ['secret_text', 'plain_text'], '');
        if (empty($up['success'])) return ['ok' => false, 'error' => 'به‌روزرسانی Worker ناموفق: ' . cf_err($up)];
    }
    $db->prepare("UPDATE vpn_services SET panel_version=? WHERE id=?")->execute([(string)$PANEL_VERSION, (int)$id]);
    return ['ok' => true, 'text' => 'پنل به نسخهٔ ' . $PANEL_VERSION . ' به‌روز شد.'];
}
function pv_repair_service($id, $tgEmail = '') {
    global $db;
    pv_ensure();
    $q = $db->prepare("SELECT * FROM vpn_services WHERE id=?"); $q->execute([(int)$id]); $svc = $q->fetch(PDO::FETCH_ASSOC);
    if (!$svc) return ['ok' => false, 'error' => 'پنل پیدا نشد.'];
    if ($tgEmail !== '' && $svc['email'] !== $tgEmail) return ['ok' => false, 'error' => 'این پنل متعلق به شما نیست.'];
    foreach (vpn_nodes_of((int)$id) as $n) {
        $tk = aes_decrypt((string)($n['token_enc'] ?? ''));
        if ($tk === '') return ['ok' => false, 'error' => 'توکن حساب Cloudflare خوانده نشد.'];
        $acc = (string)$n['account_id']; $d1 = (string)($n['d1_id'] ?? '');
        $chk = $d1 !== '' ? cf_req($tk, 'GET', '/accounts/' . rawurlencode($acc) . '/d1/database/' . rawurlencode($d1)) : ['success' => false];
        if (empty($chk['success'])) {
            $dr = cf_req($tk, 'POST', '/accounts/' . rawurlencode($acc) . '/d1/database', ['name' => 'demon-panel-' . bin2hex(random_bytes(4))]);
            $nd = (string)($dr['result']['uuid'] ?? '');
            if ($nd === '') return ['ok' => false, 'error' => 'ساخت دیتابیس جدید ناموفق: ' . cf_err($dr)];
            foreach (explode(';', VPN_D1_SCHEMA) as $stm) { if (trim($stm) !== '') d1_q($tk, $acc, $nd, $stm); }
            $db->prepare("UPDATE vpn_nodes SET d1_id=? WHERE id=?")->execute([$nd, (int)$n['id']]);
        }
    }
    return pv_update_service((int)$id, $tgEmail);
}
function tg_send_safe($bt, $body) {
    $call = function ($b) use ($bt) { return http('https://api.telegram.org/bot' . $bt . '/sendMessage', ['Content-Type' => 'application/json'], json_encode($b, JSON_UNESCAPED_UNICODE)); };
    $r = $call($body);
    if (is_array($r) && empty($r['ok']) && !empty($body['reply_markup']['inline_keyboard'])) {
        $kb = [];
        foreach ($body['reply_markup']['inline_keyboard'] as $row) { $rr = []; foreach ($row as $btn) { unset($btn['style']); $rr[] = $btn; } $kb[] = $rr; }
        $body['reply_markup'] = ['inline_keyboard' => $kb];
        $r = $call($body);
    }
    return $r;
}
function pv_my_panels($tgEmail) {
    global $db, $PANEL_VERSION;
    pv_ensure();
    $q = $db->prepare("SELECT id,name,active,panel_version FROM vpn_services WHERE email=? ORDER BY id DESC"); $q->execute([$tgEmail]);
    $out = [];
    foreach ($q->fetchAll(PDO::FETCH_ASSOC) as $r) {
        $n = vpn_nodes_of((int)$r['id']); $h = (string)($n[0]['host'] ?? '');
        $worker = $h !== '' ? 'https://' . rtrim($h, '/') . '/' . ltrim((string)($n[0]['panel'] ?? 'panel'), '/') : '';
        $out[] = ['id' => (int)$r['id'], 'name' => (string)$r['name'], 'active' => (int)$r['active'], 'version' => (string)$r['panel_version'], 'worker' => $worker, 'outdated' => (string)$r['panel_version'] !== (string)$PANEL_VERSION];
    }
    $asc = array_reverse($out); $num = [];
    foreach ($asc as $i => $p) { $num[$p['id']] = $i + 1; }
    foreach ($out as &$p) { $p['name'] = 'Vex Panel ' . $num[$p['id']]; }
    unset($p);
    return $out;
}
function pv_update_all() {
    global $db, $PANEL_VERSION;
    pv_ensure();
    $q = $db->prepare("SELECT id FROM vpn_services WHERE active=1 AND (panel_version IS NULL OR panel_version<>?)"); $q->execute([(string)$PANEL_VERSION]);
    $ok = 0; $bad = [];
    foreach ($q->fetchAll(PDO::FETCH_COLUMN) as $id) { $r = pv_update_service((int)$id); if (!empty($r['ok'])) $ok++; else $bad[] = $r['error'] ?? 'خطا'; }
    return ['ok' => !$bad, 'text' => 'آپدیت گروهی: ' . $ok . ' موفق' . ($bad ? '، ' . count($bad) . ' ناموفق' : '') . '.', 'error' => $bad ? implode(' | ', array_slice($bad, 0, 3)) : ''];
}
function ub_toggle($chat, $id, $on) {
    global $db;
    ub_table();
    $q = $db->prepare("SELECT * FROM user_bots WHERE id=? AND owner_chat=?"); $q->execute([(int)$id, (string)$chat]); $b = $q->fetch(PDO::FETCH_ASSOC);
    if (!$b) return ['ok' => false, 'error' => 'ربات پیدا نشد.'];
    $t = $db->prepare("SELECT token_enc FROM cf_accts WHERE id=?"); $t->execute([(int)$b['acc_id']]);
    $cf = aes_decrypt((string)$t->fetchColumn());
    if ($cf === '') return ['ok' => false, 'error' => 'توکن حساب خوانده نشد.'];
    $r = d1_q($cf, $b['account_id'], $b['d1_id'], "REPLACE INTO settings(k,v) VALUES(?,?)", ['bot_enabled', $on ? '1' : '0']);
    if (empty($r['success'])) return ['ok' => false, 'error' => 'تغییر وضعیت ناموفق: ' . cf_err($r)];
    $db->prepare("UPDATE user_bots SET status=? WHERE id=?")->execute([$on ? 'on' : 'off', (int)$b['id']]);
    return ['ok' => true];
}
function a2_bot_update() {
    global $db, $PANEL_VERSION;
    $tc = teacher_bot_config_row();
    if (empty($tc['d1_id']) || empty($tc['worker_name'])) return ['ok' => false, 'msg' => 'ربات مادر هنوز نصب نشده است.'];
    $cfU = aes_decrypt((string)$tc['cf_token_enc']); $btU = aes_decrypt((string)$tc['bot_token_enc']);
    if ($cfU === '' || $btU === '') return ['ok' => false, 'msg' => 'توکن‌های ذخیره‌شده خوانده نشدند؛ دوباره نصب کن.'];
    $secU = bin2hex(random_bytes(32));
    $ownerId = trim((string)st('tg_owner_id', (string)($tc['owner_id'] ?? '')));
    $bindU = a2_bot_bindings($tc['d1_id'], $btU, $secU, a2_bot_api_url(), trim((string)st('tg_security_token', '')), $ownerId);
    $upU = cf_worker_upload($cfU, $tc['account_id'], $tc['worker_name'], cf_template('tg_teacher'), $bindU, ['secret_text'], '');
    if (empty($upU['success'])) return ['ok' => false, 'msg' => 'به‌روزرسانی Worker ناموفق: ' . cf_err($upU)];
    cf_req($cfU, 'POST', '/accounts/' . rawurlencode($tc['account_id']) . '/workers/scripts/' . rawurlencode($tc['worker_name']) . '/subdomain', ['enabled' => true, 'previews_enabled' => false]);
    $subR = cf_req($cfU, 'GET', '/accounts/' . rawurlencode($tc['account_id']) . '/workers/subdomain');
    $hookU = 'https://' . $tc['worker_name'] . '.' . (string)($subR['result']['subdomain'] ?? '') . '.workers.dev/';
    $whU = http('https://api.telegram.org/bot' . $btU . '/setWebhook', ['Content-Type' => 'application/x-www-form-urlencoded'],
        http_build_query(['url' => $hookU, 'secret_token' => $secU, 'allowed_updates' => json_encode(['message', 'callback_query', 'chat_member']), 'drop_pending_updates' => 'true']));
    if (!is_array($whU) || empty($whU['ok'])) return ['ok' => false, 'msg' => 'Webhook پس از به‌روزرسانی وصل نشد.'];
    $db->prepare("UPDATE teacher_bot_config SET worker_url=?,error='',updated=?,bot_version=?,owner_id=? WHERE id=1")->execute([$hookU, time(), (string)$PANEL_VERSION, $ownerId]);
    setst('tg_teacher_url', $hookU); setst('tg_teacher_version', (string)$PANEL_VERSION);
    audit('teacher_bot_update', $tc['worker_name'], 'info');
    return ['ok' => true, 'msg' => 'ربات مادر به نسخهٔ ' . $PANEL_VERSION . ' رسید.'];
}
/* ===================== پنل مدیریت پیشرفته (نسخهٔ ۲) ===================== */
function a2_update_panel($id) {
    global $db, $PANEL_VERSION;
    $q = $db->prepare('SELECT * FROM panel_records WHERE id=?'); $q->execute([(int)$id]);
    $p = $q->fetch(PDO::FETCH_ASSOC);
    if (!$p) return ['ok' => false, 'msg' => 'پنل پیدا نشد.'];
    if (empty($p['cf_token_enc']) || empty($p['account_id'])) return ['ok' => false, 'msg' => 'پنل «' . $p['worker'] . '» اطلاعات حساب Cloudflare ندارد و قابل به‌روزرسانی نیست.'];
    $tok = aes_decrypt((string)$p['cf_token_enc']);
    if ($tok === '') return ['ok' => false, 'msg' => 'توکن Cloudflare پنل «' . $p['worker'] . '» خوانده نشد.'];
    $r = cf_worker_upload($tok, (string)$p['account_id'], (string)$p['worker'], cf_template('vpn'),
        [['type' => 'secret_text', 'name' => 'PANEL_VERSION', 'text' => (string)$PANEL_VERSION]], ['d1', 'secret_text']);
    if (empty($r['success'])) return ['ok' => false, 'msg' => 'به‌روزرسانی «' . $p['worker'] . '» ناموفق بود: ' . cf_err($r)];
    $db->prepare('UPDATE panel_records SET panel_version=? WHERE id=?')->execute([(string)$PANEL_VERSION, (int)$id]);
    return ['ok' => true, 'msg' => 'پنل «' . $p['worker'] . '» به نسخهٔ ' . $PANEL_VERSION . ' رسید.'];
}
function a2_update_all() {
    global $db, $PANEL_VERSION;
    $rows = $db->query('SELECT id FROM panel_records WHERE active=1 AND (panel_version IS NULL OR panel_version<>' . $db->quote((string)$PANEL_VERSION) . ') ORDER BY id')->fetchAll(PDO::FETCH_COLUMN);
    if (!$rows) return ['ok' => true, 'msg' => 'همهٔ پنل‌های فعال روی نسخهٔ جدید هستند.'];
    $okN = 0; $bad = [];
    foreach ($rows as $pid) { $r = a2_update_panel((int)$pid); if ($r['ok']) $okN++; else $bad[] = $r['msg']; }
    return ['ok' => !$bad, 'msg' => 'به‌روزرسانی گروهی: ' . $okN . ' موفق' . ($bad ? '، ' . count($bad) . ' ناموفق: ' . implode(' | ', $bad) : '') . '.'];
}
if (isset($_GET[$ADMIN_SLUG])) {
    header('X-Robots-Tag: noindex, nofollow');
    header('Cache-Control: no-store');
    if (empty($_SESSION['csrf'])) $_SESSION['csrf'] = bin2hex(random_bytes(16));
