    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        $do = (string)($_POST['do'] ?? '');
        if (!hash_equals((string)$_SESSION['csrf'], (string)($_POST['csrf'] ?? ''))) {
            $_SESSION['a2flash'] = 'نشست معتبر نیست؛ صفحه را دوباره باز کن.';
        } elseif (!$a2ok && $do === 'login') {
            $pw = (string)($_POST['pw'] ?? '');
            $h = st('admin_hash');
            $okpw = $h !== '' ? password_verify($pw, $h) : hash_equals((string)$ADMIN_PASSWORD, $pw);
            if ($okpw) { session_regenerate_id(true); $_SESSION['adm2'] = 1; $_SESSION['csrf'] = bin2hex(random_bytes(16)); }
            else $_SESSION['a2flash'] = 'رمز اشتباه است.';
        } elseif ($a2ok) {
            if ($do === 'logout') { $_SESSION['adm2'] = 0; }
            elseif ($do === 'toggle') { $db->prepare('UPDATE panel_records SET active=CASE WHEN active=1 THEN 0 ELSE 1 END WHERE id=?')->execute([(int)($_POST['id'] ?? 0)]); $_SESSION['a2flash'] = 'وضعیت پنل تغییر کرد.'; }
            elseif ($do === 'update') { $r = a2_update_panel((int)($_POST['id'] ?? 0)); $_SESSION['a2flash'] = $r['msg']; }
            elseif ($do === 'update_all') { $r = a2_update_all(); $_SESSION['a2flash'] = $r['msg']; }
            elseif ($do === 'bot_deploy') {
                $r = a2_bot_deploy(trim((string)($_POST['cf_token'] ?? '')), trim((string)($_POST['bot_token'] ?? '')), trim((string)($_POST['account_id'] ?? '')), preg_replace('/[^0-9\-]/', '', trim((string)($_POST['owner_id'] ?? ''))));
                $_SESSION['a2flash'] = $r['msg'];
            }
            elseif ($do === 'bot_toggle') {
                $want = ((string)($_POST['bot_state'] ?? '0')) === '1';
                $tr = teacher_bot_set_enabled($want);
                if (empty($tr['ok'])) { $_SESSION['a2flash'] = 'تغییر وضعیت ناموفق: ' . ($tr['error'] ?? 'خطا'); }
                else { $br = teacher_bot_broadcast_state($want); $_SESSION['a2flash'] = ($want ? 'ربات مادر روشن شد' : 'ربات مادر خاموش شد') . ' · اطلاع‌رسانی: ' . (int)$br['sent'] . ' موفق' . ($br['failed'] ? '، ' . (int)$br['failed'] . ' ناموفق' : ''); audit('teacher_bot_toggle', $want ? 'on' : 'off', 'warn'); }
            }
            elseif ($do === 'bot_update') { $r = a2_bot_update(); $_SESSION['a2flash'] = $r['msg']; }
            elseif ($do === 'bot_diag') { $r = a2_bot_diag(); $_SESSION['a2flash'] = $r['msg']; }
            elseif ($do === 'force_add') {
                $r = a2_force_resolve((string)($_POST['link'] ?? ''));
                if (!$r['ok']) { $_SESSION['a2flash'] = $r['msg']; }
                else {
                    $rows = tg_force_channels(); $dup = false;
                    foreach ($rows as $x) { if ((string)$x['id'] === $r['id']) $dup = true; }
                    if ($dup) { $_SESSION['a2flash'] = 'این کانال قبلاً اضافه شده است.'; }
                    else { $rows[] = ['id' => $r['id'], 'url' => $r['url'], 'title' => $r['title'], 'enabled' => 1]; tg_force_save($rows); $_SESSION['a2flash'] = 'کانال «' . $r['title'] . '» به عضویت اجباری اضافه شد.'; }
                }
            }
            elseif ($do === 'panel_delete') { $_SESSION['a2flash'] = a2_panel_delete((int)($_POST['id'] ?? 0)); }
            elseif ($do === 'user_ban' || $do === 'user_unban') { $_SESSION['a2flash'] = a2_user_set_ban((string)($_POST['chat'] ?? ''), $do === 'user_ban'); }
            elseif ($do === 'pv_announce') { $r = pv_announce_update(); $_SESSION['a2flash'] = 'اطلاع‌رسانی نسخهٔ جدید: ' . (int)$r['sent'] . ' موفق' . ((int)$r['failed'] ? '، ' . (int)$r['failed'] . ' ناموفق' : '') . '.'; }
            elseif ($do === 'user_panels_delete') { $_SESSION['a2flash'] = a2_user_delete_panels((string)($_POST['chat'] ?? '')); }
            elseif ($do === 'force_toggle' || $do === 'force_delete') {
                $idx = (int)($_POST['index'] ?? -1); $rows = tg_force_channels();
                if (!isset($rows[$idx])) { $_SESSION['a2flash'] = 'کانال پیدا نشد.'; }
                elseif ($do === 'force_toggle') { $rows[$idx]['enabled'] = $rows[$idx]['enabled'] ? 0 : 1; tg_force_save($rows); $_SESSION['a2flash'] = 'وضعیت کانال تغییر کرد.'; }
                else { array_splice($rows, $idx, 1); tg_force_save($rows); $_SESSION['a2flash'] = 'کانال حذف شد.'; }
            }
            elseif ($do === 'bot_owner') {
                $oid = preg_replace('/[^0-9\-]/', '', trim((string)($_POST['owner_id'] ?? '')));
                if (!preg_match('/^-?\d{5,15}$/', $oid)) { $_SESSION['a2flash'] = 'Owner ID معتبر نیست.'; }
