<style>
/* CloudVPN v6 — advanced controls + cyber animated backdrop */
#cyber-bg {
  position: fixed; inset: 0; z-index: -1; overflow: hidden;
  pointer-events: none; opacity: 0; transition: opacity .35s ease;
  background:
    radial-gradient(circle at 50% 20%, rgba(0,255,170,.08), transparent 38%),
    radial-gradient(circle at 15% 80%, rgba(0,140,255,.06), transparent 35%),
    #050709;
}
body.cyber-bg-on #cyber-bg { opacity: 1; }
#cyber-bg .matrix { position:absolute; inset:-20%; display:flex; gap:26px; transform:rotate(-3deg); }
#cyber-bg .col { flex:1; min-width:18px; color:rgba(0,255,170,.20); font:600 11px/1.65 ui-monospace,SFMono-Regular,Menlo,monospace; white-space:pre; animation: cyberFall linear infinite; text-shadow:0 0 7px rgba(0,255,170,.18); }
#cyber-bg .col:nth-child(2n) { color:rgba(50,170,255,.16); animation-direction:reverse; }
#cyber-bg .col:nth-child(3n) { animation-duration:18s!important; opacity:.55; }
#cyber-bg .terminal {
  position:absolute; width:min(520px,72vw); height:min(310px,36vh);
  left:50%; top:50%; transform:translate(-50%,-50%);
  border:1px solid rgba(0,255,170,.13); border-radius:18px;
  background:linear-gradient(180deg,rgba(8,14,16,.72),rgba(2,7,9,.48));
  box-shadow:0 0 70px rgba(0,255,170,.07), inset 0 0 40px rgba(0,255,170,.025);
  backdrop-filter:blur(2px); opacity:.72;
}
#cyber-bg .terminal:before { content:""; position:absolute; left:0; right:0; top:0; height:34px; border-bottom:1px solid rgba(255,255,255,.06); background:rgba(255,255,255,.025); }
#cyber-bg .dots { position:absolute; top:11px; left:14px; display:flex; gap:6px; }
#cyber-bg .dots i { width:7px;height:7px;border-radius:50%;background:rgba(255,255,255,.18); }
#cyber-bg .screen { position:absolute; inset:48px 18px 18px; color:rgba(116,255,204,.32); font:11px/1.65 ui-monospace,SFMono-Regular,Menlo,monospace; overflow:hidden; }
#cyber-bg .screen span { display:block; animation:cyberText 8s linear infinite; }
#cyber-bg .screen span:nth-child(2){animation-delay:-2s}.screen span:nth-child(3){animation-delay:-4s}.screen span:nth-child(4){animation-delay:-6s}
@keyframes cyberFall { from{transform:translateY(-18%)} to{transform:translateY(18%)} }
@keyframes cyberText { 0%{transform:translateY(70px);opacity:0} 12%,80%{opacity:1} 100%{transform:translateY(-120px);opacity:0} }
body.cyber-bg-on .app, body.cyber-bg-on .page, body.cyber-bg-on .main { position:relative; }
body.cyber-bg-on .card, body.cyber-bg-on .panel, body.cyber-bg-on .modal-card { backdrop-filter:blur(9px); background-color:rgba(12,15,18,.82)!important; }
