<div class="modal" id="settingsModal">
  <div class="dialog small">
    <div class="dhead"><div class="dtitle">تنظیمات پنل<small>تنظیمات ظاهری نسخه دمو</small></div><button class="close" data-close="settingsModal">×</button></div>
    <div class="dbody">
      <div class="section">
        <div class="switchrow"><div><strong>حالت AMOLED</strong><span>پس‌زمینه کاملاً تیره مشابه پنل مرجع</span></div><label class="switch"><input id="amoled" type="checkbox"><i class="slider"></i></label></div>
        <div class="switchrow"><div><strong>پس‌زمینه متحرک</strong><span>افکت بسیار سبک برای صفحه اصلی</span></div><label class="switch"><input id="motion" type="checkbox"><i class="slider"></i></label></div>
        <div class="switchrow"><div><strong>نمایش حالت Demo</strong><span>داده‌های نمونه در مرورگر نگهداری می‌شوند</span></div><label class="switch"><input id="demo" type="checkbox" checked><i class="slider"></i></label></div>
      </div>
      <div class="section"><div class="section-title">درباره</div><div style="font-size:11px;color:var(--muted);line-height:1.9">ساخت و ویرایش سرویس از API واقعی /api/users انجام می‌شود. برای نصب مستقل می‌توان CLOUDVPN_API_BASE و توکن را در localStorage یا تنظیمات محیطی پروژه تعیین کرد.</div></div>
    </div>
  </div>
</div>

<div class="modal" id="configModal">
  <div class="dialog small">
    <div class="dhead"><div class="dtitle">کانفیگ کاربر<small id="configUserTitle"></small></div><button class="close" data-close="configModal">×</button></div>
    <div class="dbody">
      <div class="field"><label>نمونه کانفیگ</label><textarea id="configText" style="height:170px" readonly></textarea></div>
      <div style="display:flex;gap:8px;margin-top:10px"><button class="primary" id="copyConfig">کپی کانفیگ</button><button class="ghost" data-close="configModal">بستن</button></div>
    </div>
  </div>
</div>

<div class="toast" id="toast"></div>
<script>
const demoUsers = [
 {id:24,username:"admin_demo",uuid:"7d1b2e1a-8d41-4e6c-9b5a-01a2c9d4f111",used:8.42,limit:50,expiry:27,online:true,active:true,proto:"VLESS",port:"443",configs:12},
 {id:23,username:"premium_01",uuid:"c31a91a2-1d5b-4e2f-a0bb-91e5d1c3b822",used:42.18,limit:100,expiry:12,online:true,active:true,proto:"VLESS / Trojan",port:"443,2053",configs:24},
 {id:22,username:"test_user",uuid:"2e17b9c0-7a8c-4d11-9b3f-7a5d2e91c333",used:1.08,limit:10,expiry:3,online:false,active:true,proto:"VLESS",port:"443",configs:8},
 {id:21,username:"iphone_client",uuid:"b72d6c4f-5e11-4f8a-9c33-2b7f11a4d444",used:17.61,limit:30,expiry:0,online:true,active:true,proto:"VLESS",port:"443",configs:16},
 {id:20,username:"offline_user",uuid:"f10a1d2c-93aa-4b6f-8d41-0c7e2b5f5555",used:29.7,limit:30,expiry:0,online:false,active:false,proto:"VLESS",port:"80",configs:4},
 {id:19,username:"family_vpn",uuid:"a11c2d3e-4f5a-6789-abcd-123456789666",used:65.23,limit:100,expiry:46,online:true,active:true,proto:"VLESS / SS",port:"443",configs:20}
];
let users = JSON.parse(localStorage.getItem("cloudvpn_demo_users") || "null") || demoUsers;
let editingId = null;

const $ = s => document.querySelector(s);
document.querySelectorAll(".location-card").forEach(card=>card.onclick=()=>{
  document.querySelectorAll(".location-card").forEach(x=>x.classList.remove("selected"));
  card.classList.add("selected");
  $("#uLocation").value=card.dataset.location;
  $("#locationSummary").textContent="Server: "+card.dataset.location;
  updateRouteSummary();
});

function save(){localStorage.setItem("cloudvpn_demo_users",JSON.stringify(users))}
function toast(t){const el=$("#toast");el.textContent=t;el.classList.add("show");clearTimeout(window._toast);window._toast=setTimeout(()=>el.classList.remove("show"),2200)}
function openModal(id){$("#"+id).classList.add("open")}
function closeModal(id){$("#"+id).classList.remove("open")}
document.querySelectorAll("[data-close]").forEach(b=>b.onclick=()=>closeModal(b.dataset.close));

function render(){
 const q=$("#search").value.trim().toLowerCase(), st=$("#statusFilter").value, sort=$("#sort").value;
 let list=users.filter(u=>{
   const match=!q || u.username.toLowerCase().includes(q) || u.uuid.toLowerCase().includes(q);
   if(!match)return false;
   if(st==="active")return u.active && u.expiry!==0;
   if(st==="inactive")return !u.active;
   if(st==="online")return u.online;
   if(st==="offline")return !u.online;
   if(st==="expired")return u.expiry===0 || !u.active;
   return true;
 });
 if(sort==="name")list.sort((a,b)=>a.username.localeCompare(b.username));
 if(sort==="usage-desc")list.sort((a,b)=>b.used-a.used);
 if(sort==="usage-asc")list.sort((a,b)=>a.used-b.used);
 if(sort==="expiry")list.sort((a,b)=>a.expiry-b.expiry);
 if(sort==="newest")list.sort((a,b)=>b.id-a.id);
 $("#usersBody").innerHTML=list.map(u=>{
   const pct=u.limit?Math.min(100,u.used/u.limit*100):0;
   const expired=u.expiry===0 || !u.active;
   return `<tr>
    <td><div class="user-name"><div class="avatar">${u.username.slice(0,1).toUpperCase()}</div><div><div class="uname">${u.username}</div><div class="uuid">${u.uuid}</div></div></div></td>
    <td><span class="status"><i class="dot ${u.online?'online':(u.active?'':'off')}"></i>${u.online?'آنلاین':(u.active?'فعال':'غیرفعال')}</span></td>
    <td><div dir="ltr" style="font-weight:850">${u.used.toFixed(2)} / ${u.limit||'∞'} GB</div><div class="progress" style="width:95px;margin-top:5px"><i style="width:${pct}%;background:${pct>90?'#ef4444':'#16a34a'}"></i></div></td>
    <td><span class="badge ${expired?'bred':u.expiry<7?'bamber':'bgreen'}">${expired?'منقضی':u.expiry+' روز'}</span></td>
    <td><span class="badge bblue">${u.proto}</span> <span style="color:var(--muted);font-size:9px" dir="ltr">${u.port}</span></td>
    <td><span class="badge ${u.configs>20?'bamber':'bgreen'}" dir="ltr">${u.configs}</span></td>
    <td><div class="mini-actions">
      <button class="mini" title="فعال/غیرفعال" onclick="toggleUser(${u.id})">${u.active?'⏻':'▶'}</button>
      <button class="mini" title="ویرایش" onclick="editUser(${u.id})">✎</button>
      <button class="mini" title="کانفیگ" onclick="showConfig(${u.id})">⌁</button>
      <button class="mini" title="حذف" onclick="deleteUser(${u.id})">⌫</button>
    </div></td>
   </tr>`
 }).join("");
 $("#empty").style.display=list.length?"none":"block";
 $("#statUsers").textContent=users.length;
 $("#statOnline").textContent=users.filter(u=>u.online).length;
 $("#statUsage").textContent=users.reduce((s,u)=>s+u.used,0).toFixed(2)+" GB";
 $("#statReads").textContent=(12000+users.length*17).toLocaleString();
 $("#statWrites").textContent=(1100+users.length*5).toLocaleString();
 const cf=18200+users.length*37;$("#statCf").textContent=cf>=1000?(cf/1000).toFixed(1)+"k":cf;
 $("#cfProgress").style.width=Math.min(100,cf/1000)+"%";
}
function resetForm(){
 $("#userForm").reset();
 $("#uUuid").value=newUuid(); document.querySelectorAll(".quick-profile").forEach(x=>x.classList.remove("active"));
 $("#uActive").checked=true;$("#uAds").checked=true;$("#uDirect").checked=true;$("#uTls").checked=true;
 $("#uWorkerDirect").checked=true;$("#uMultiLocation").checked=false;
 $("#uRoutePriority").value="auto";$("#uUuidMode").value="random";$("#uDns").value="auto";
 $("#uDevices").value=2;$("#uConnLimit").value=2;
 document.querySelectorAll(".location-card").forEach(x=>x.classList.remove("selected"));
 const firstLocation=document.querySelector('.location-card[data-location="DE Frankfurt"]');
 if(firstLocation) firstLocation.classList.add("selected");
 $("#uLocation").value="DE Frankfurt";$("#locationSummary").textContent="Server: DE Frankfurt";
 $("#routeSummary").textContent="Route: Worker Direct (Auto)";
 document.querySelectorAll(".tab").forEach(x=>x.classList.remove("active"));document.querySelector('[data-tab="info"]').classList.add("active");
 document.querySelectorAll(".tabpane").forEach(x=>x.style.display="none");$("#tab-info").style.display="block";
}
function openCreate(){
 editingId=null;resetForm();$("#modalTitle").textContent="ایجاد کاربر جدید";$("#saveUser").textContent="✓ ایجاد کاربر";openModal("userModal");
}
function editUser(id){
 const u=users.find(x=>x.id===id);if(!u)return;editingId=id;resetForm();
 $("#modalTitle").textContent="ویرایش کاربر";$("#saveUser").textContent="✓ ذخیره تغییرات";
 $("#uName").value=u.username;$("#uUuid").value=u.uuid||newUuid();$("#uLimit").value=u.limit||"";$("#uExpiry").value=u.expiry||"";$("#uActive").checked=u.active;$("#uProxy").checked=false;openModal("userModal");
}
function toggleUser(id){const u=users.find(x=>x.id===id);u.active=!u.active;if(!u.active)u.online=false;save();render();toast(u.active?"کاربر فعال شد":"کاربر غیرفعال شد")}
function deleteUser(id){const u=users.find(x=>x.id===id);if(!u)return;if(confirm("حذف کاربر «"+u.username+"»؟")){users=users.filter(x=>x.id!==id);save();render();toast("کاربر حذف شد")}}
function showConfig(id){const u=users.find(x=>x.id===id);$("#configUserTitle").textContent=u.username;$("#configText").value=`vless://${u.uuid}@demo.cloudvpn.local:${u.port.split(",")[0]}?security=tls&type=tcp#${encodeURIComponent(u.username)}\n\n// Demo config — اتصال واقعی ندارد`;openModal("configModal")}
$("#copyConfig").onclick=()=>navigator.clipboard?.writeText($("#configText").value).then(()=>toast("کانفیگ کپی شد"));
$("#addUserBtn").onclick=openCreate;
$("#refreshBtn").onclick=()=>{render();toast("اطلاعات دمو بروزرسانی شد")};
$("#search").oninput=render;$("#statusFilter").onchange=render;$("#sort").onchange=render;

document.querySelectorAll(".tab").forEach(btn=>btn.onclick=()=>{
 document.querySelectorAll(".tab").forEach(x=>x.classList.remove("active"));btn.classList.add("active");
 document.querySelectorAll(".tabpane").forEach(x=>x.style.display="none");$("#tab-"+btn.dataset.tab).style.display="block";
});


const CLOUDVPN_API_BASE = localStorage.getItem("cloudvpn_api_base") || "";
const CLOUDVPN_TOKEN = localStorage.getItem("cloudvpn_token") || "";

function updateRouteSummary(){
  const ips = $("#uIps")?.value.trim();
  const priority = $("#uRoutePriority")?.value || "auto";
  const direct = $("#uWorkerDirect")?.checked !== false;
  let route = ips ? "Clean IP" : (direct ? "Worker Direct" : "Auto");
  if(priority === "clean-ip" && ips) route = "Clean IP";
  if(priority === "direct") route = "Worker Direct";
  $("#routeSummary").textContent = "Route: " + route;
}

$("#uIps").addEventListener("input", updateRouteSummary);
$("#uWorkerDirect").addEventListener("change", updateRouteSummary);
$("#uRoutePriority").addEventListener("change", updateRouteSummary);

async function apiRequest(path,method,payload){
 const headers={"Content-Type":"application/json"};
 if(CLOUDVPN_TOKEN)headers.Authorization="Bearer "+CLOUDVPN_TOKEN;
 const r=await fetch((CLOUDVPN_API_BASE||"")+path,{method,headers,credentials:"include",body:payload?JSON.stringify(payload):undefined});
 let d={};try{d=await r.json()}catch(_){}
 if(!r.ok)throw new Error(d.error||("HTTP "+r.status));
 return d;
}
function setSaveButtonLoading(loading, text="در حال ساخت سرویس..."){
  const btn=$("#saveUser");
  if(!btn) return;
  if(loading){
    btn.dataset.originalHtml = btn.innerHTML;
    btn.setAttribute("aria-busy","true");
    btn.disabled=true;
    btn.innerHTML='<span class="btn-loading"><i class="btn-spinner"></i><span>'+text+'</span></span>';
  }else{
    btn.removeAttribute("aria-busy");
    btn.disabled=false;
    btn.innerHTML=btn.dataset.originalHtml || "✓ ایجاد کاربر";
  }
}

async function apiCreateUser(payload){
  const url = (CLOUDVPN_API_BASE || "") + "/api/users";
  const headers = {"Content-Type":"application/json"};
  if(CLOUDVPN_TOKEN) headers.Authorization = "Bearer " + CLOUDVPN_TOKEN;
  const response = await fetch(url,{method:"POST",headers,credentials:"include",body:JSON.stringify(payload)});
  let data = {};
  try{ data = await response.json(); }catch(_){}
  if(!response.ok) throw new Error(data.error || ("HTTP "+response.status));
  return data;
}

function newUuid(){ return crypto.randomUUID ? crypto.randomUUID() : ([1e7]+-1e3+-4e3+-8e3+-1e11).replace(/[018]/g,c=>(c^crypto.getRandomValues(new Uint8Array(1))[0]&15>>c/4).toString(16)); }
function updateBuilderSummary(){
 const q=$("#uLimit").value.trim(); const ex=$("#uExpiry").value.trim(); const dev=$("#uDevices").value.trim(); const sp=$("#uSpeed").value;
 $("#sumQuota").textContent=q?`${q} GB`:"∞"; $("#sumExpiry").textContent=ex?`${ex} روز`:"∞"; $("#sumDevices").textContent=dev||"1"; $("#sumSpeed").textContent=sp==="unlimited"?"∞":`${sp}M`;
}
const profileValues={
 basic:{limit:30,expiry:30,devices:2,speed:'20'},
 premium:{limit:100,expiry:60,devices:5,speed:'100'},
 gaming:{limit:50,expiry:30,devices:3,speed:'100'}
};
document.querySelectorAll('.quick-profile').forEach(btn=>btn.addEventListener('click',()=>{
 const v=profileValues[btn.dataset.profile]; if(!v)return;
 document.querySelectorAll('.quick-profile').forEach(x=>x.classList.remove('active')); btn.classList.add('active');
 $("#uLimit").value=v.limit; $("#uExpiry").value=v.expiry; $("#uDevices").value=v.devices; $("#uSpeed").value=v.speed;
 if(btn.dataset.profile==='gaming'){ $("#uTls").checked=true; $("#uFirst").checked=false; }
 updateBuilderSummary();
}));
$("#regenUuid").onclick=()=>{ $("#uUuid").value=newUuid(); toast('UUID جدید تولید شد'); };
["#uLimit","#uExpiry","#uDevices","#uSpeed"].forEach(id=>$(id).addEventListener('input',updateBuilderSummary));
$("#uSpeed").addEventListener('change',updateBuilderSummary);
if($("#uUuid")) $("#uUuid").value=newUuid(); updateBuilderSummary();

$("#userForm").onsubmit=async e=>{
 e.preventDefault(); if($("#saveUser").disabled)return;
 const name=$("#uName").value.trim();
 if(!/^[a-zA-Z0-9_-]+$/.test(name)){toast("نام کاربری فقط انگلیسی، عدد، - و _ باشد");return}
 const ports=[...document.querySelectorAll('input[name="port"]:checked')].map(x=>x.value);
 if($("#uCustomPort").value.trim())ports.push(...$("#uCustomPort").value.trim().split(/\s+/));
 const protos=[...document.querySelectorAll(".proto:checked")].map(x=>x.value.toUpperCase()).join(" / ")||"VLESS";
 const cleanIps=$("#uIps").value.trim(), workerDirect=!cleanIps;
 const old=editingId?users.find(u=>u.id===editingId):null;
 const payload={
  username:name,uuid:old?.uuid||$("#uUuid").value.trim()||newUuid(),
  limit_gb:Number($("#uLimit").value)||null,expiry_days:Number($("#uExpiry").value)||null,
  limit_req:Number($("#uReq").value)||null,ip_limit:Number($("#uIpLimit").value)||Number($("#uConnLimit").value)||null,
  ips:cleanIps,ip_operator:"all",ip_count:Number($("#uIpCount").value)||15,
  auto_rotate_ip:$("#uRotate").checked?1:0,rotate_time:Number($("#uRotateTime").value)||5,
  fingerprint:$("#uFingerprint").value,block_ads:$("#uAds").checked?1:0,block_porn:0,
  port:ports.join(",")||"443",tls:$("#uTls").checked?"on":"off",connection_type:$("#uConnection").value||"vless",
  enable_direct:(workerDirect&&$("#uWorkerDirect").checked)?1:0,
  user_socks5:$("#uProxy").checked?($("#uProxyUrl").value.trim()||null):null,
  auto_rotate_user_proxy:$("#uAutoProxy").checked?1:0,
  auto_reset_vol_days:Number($("#uResetVol").value)||0,auto_reset_req_days:Number($("#uResetReq").value)||0,
  frag_len:$("#uFrag").value.trim(),frag_int:"",start_on_first_connect:$("#uFirst").checked?1:0,
  location:$("#uLocation").value,locations:$("#uAllowedLocations").value.trim(),multi_location:$("#uMultiLocation").checked?1:0,
  speed:$("#uSpeed").value,max_devices:Number($("#uDevices").value)||1,
  worker_route:workerDirect?"worker_direct":"clean_ip",route_priority:$("#uRoutePriority").value,
  host:$("#uHost").value.trim(),dns:$("#uDns").value,custom_dns:$("#uCustomDns").value.trim(),
  daily_request_limit:Number($("#uDailyReq").value)||0
 };
 setSaveButtonLoading(true,editingId?"در حال ذخیره...":"در حال ساخت سرویس...");
 try{
  if(editingId){
    await apiRequest("/api/users/"+encodeURIComponent(old.username),"PUT",payload);
  }else{
    await apiCreateUser(payload);
  }
  const local={id:editingId||Date.now(),username:name,used:old?.used||0,limit:Number($("#uLimit").value)||0,expiry:Number($("#uExpiry").value)||0,online:false,active:$("#uActive").checked,proto:protos,port:ports.join(",")||"443",configs:Math.max(3,ports.length*protos.split(" / ").length*3),uuid:payload.uuid,location:payload.location,cleanIps,speed:payload.speed,devices:payload.max_devices,workerRoute:workerDirect?"Worker Direct":"Clean IP"};
  if(editingId)Object.assign(old,local,{id:old.id,used:old.used});else users.unshift(local);
  save();render();closeModal("userModal");
  toast(workerDirect?"✅ کاربر مستقیم روی Worker ساخته شد":"✅ سرویس با Clean IP ساخته شد");
 }catch(err){toast("❌ ساخت سرویس ناموفق بود: "+err.message)}
 finally{setSaveButtonLoading(false)}
};

$("#themeBtn").onclick=()=>{document.documentElement.classList.toggle("dark");localStorage.setItem("cloudvpn_theme",document.documentElement.classList.contains("dark")?"dark":"light");$("#themeBtn").textContent=document.documentElement.classList.contains("dark")?"🌙":"☀️"};
