<script>
(function(){
  function val(id, fallback=''){ const e=document.getElementById(id); return e ? e.value : fallback; }
  function checked(id, fallback=false){ const e=document.getElementById(id); return e ? !!e.checked : fallback; }

  window.getCloudVpnAdvancedPayload = function(){
    const cleanEl = document.getElementById('uCleanIp');
    const cleanRaw = cleanEl ? cleanEl.value.trim() : '';
    const cleanIps = cleanRaw ? cleanRaw.split(/\r?\n|,/).map(x=>x.trim()).filter(Boolean) : [];
    const hasClean = cleanIps.length > 0;
    return {
      location: val('uLocation','auto'),
      clean_ips: cleanIps,
      ips: cleanIps.join('\n'),
      worker_route: hasClean ? 'clean-ip' : 'worker-direct',
      direct_worker: !hasClean,
      route_mode: hasClean ? 'clean-ip' : 'worker-direct',
      advanced_enabled: checked('advancedEnabled',false),
      protocol: val('advProtocol','auto'),
      port: Number(val('advPort','443')) || 443,
      host: val('advHost',''),
      dns: val('advDns',''),
      daily_request_limit: Number(val('advDailyReq','0')) || 0,
      concurrent_connection_limit: Number(val('advConcurrent','0')) || 0,
      tls: checked('advTls',true),
      enable_direct: checked('advDirect',true)
    };
  };

  window.applyWorkerDirectDefaults = function(){
    const cleanEl = document.getElementById('uCleanIp');
    if(!cleanEl) return;
    const raw = cleanEl.value.trim();
    const summary = document.getElementById('routeSummary');
    const direct = !raw;
    if(summary) summary.textContent = direct ? 'Worker Direct (Auto) — بدون IP' : 'Clean IP — مسیر سفارشی';
    const loc = document.getElementById('uLocation');
    if(loc && !loc.value) loc.value='auto';
  };

  function bind(){
    const c=document.getElementById('uCleanIp');
    if(c) c.addEventListener('input',window.applyWorkerDirectDefaults);
    const adv=document.getElementById('advancedEnabled'), opts=document.getElementById('advancedOptions');
    function sync(){ if(opts) opts.style.opacity = adv && adv.checked ? '1' : '.55'; }
    if(adv){adv.addEventListener('change',sync);sync();}
    window.applyWorkerDirectDefaults();
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',bind); else bind();

  // Add a compact background toggle to existing settings/theme area if there is a settings button.
  window.toggleCyberBackground = function(on){
    document.body.classList.toggle('cyber-bg-on', !!on);
    localStorage.setItem('cloudvpn_cyber_bg', on ? '1':'0');
  };
  const boot=()=>{ const on=localStorage.getItem('cloudvpn_cyber_bg')==='1'; document.body.classList.toggle('cyber-bg-on',on); };
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',boot); else boot();
})();
</script>

