<script>
(function(){
  function $(id){return document.getElementById(id);}
  function val(id, fallback){var e=$(id);return e?e.value:(fallback||'');}

  function extract(obj, keys){
    if(!obj || typeof obj!=='object') return '';
    for(var i=0;i<keys.length;i++){
      var parts=keys[i].split('.'), cur=obj;
      for(var j=0;j<parts.length && cur!=null;j++) cur=cur[parts[j]];
      if(typeof cur==='string' && cur.trim()) return cur.trim();
    }
    return '';
  }

  function fallbackConfig(payload){
    var uuid=payload.uuid || val('uUuid','');
    var host=val('uHost','');
    var ports=[].slice.call(document.querySelectorAll('input[name="port"]:checked')).map(function(x){return x.value;});
    var port=val('uCustomPort','').trim() || ports[0] || '443';
    var name=payload.username || val('uName','user');
    return 'vless://'+encodeURIComponent(uuid)+'@'+(host||'server')+':'+port+
      '?type=tcp&security='+(val('uTls','')?'tls':'none')+
      (host?'&host='+encodeURIComponent(host):'')+
      '#'+encodeURIComponent(name);
  }

  function fallbackSub(payload){
    return 'cloudvpn://subscribe/'+encodeURIComponent(payload.username||val('uName','user'))+
      '?uuid='+encodeURIComponent(payload.uuid||val('uUuid',''));
  }

  function showResult(data,payload){
    var root=(data&&data.data&&typeof data.data==='object')?data.data:(data||{});
    var config=extract(root,['config','vless','vless_url','vlessUrl','config_url','configUrl','result.config','user.config']) || fallbackConfig(payload);
    var sub=extract(root,['subscription','subscription_url','subscriptionUrl','sub','sub_url','subUrl','subscription_link','subscriptionLink','result.subscription','user.subscription']) || fallbackSub(payload);

    $('resultConfig').value=config;
    $('resultSub').value=sub;
    $('serviceResultUser').textContent='کاربر: '+(payload.username||'-');

    var img=$('resultQrImage'), ph=$('resultQrPlaceholder');
    img.src='https://quickchart.io/qr?size=240&text='+encodeURIComponent(sub);
    img.style.display='inline-block';
    ph.style.display='none';

    ['resultQrPane','resultConfigPane','resultSubPane'].forEach(function(id){$(id).style.display='none';});
    $('resultQrPane').style.display='block';

    var m=$('serviceResultModal');
    if(m){
      m.classList.add('open');
      m.style.display='flex';
    }
  }

  // Keep the original apiCreateUser request exactly as-is; only observe its successful result.
  if(typeof window.apiCreateUser==='function' && !window.__cloudvpnWrappedCreate){
    window.__cloudvpnWrappedCreate=true;
    var originalCreate=window.apiCreateUser;
    window.apiCreateUser=async function(payload){
      var result=await originalCreate(payload);
      // Result dialog is only shown after the real API call succeeds.
      setTimeout(function(){showResult(result,payload);},0);
      return result;
    };
  }

  function copyField(id){
    var e=$(id); if(!e)return;
    var s=e.value||'';
    if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(s).then(function(){
        if(typeof toast==='function')toast('📋 کپی شد');
      });
    }else{
      e.focus();e.select();document.execCommand('copy');
    }
  }

  if($('resultQrTab'))$('resultQrTab').onclick=function(){
    $('resultQrPane').style.display='block';
    $('resultConfigPane').style.display='none';
    $('resultSubPane').style.display='none';
  };
  if($('resultConfigTab'))$('resultConfigTab').onclick=function(){
    $('resultQrPane').style.display='none';
    $('resultConfigPane').style.display='block';
    $('resultSubPane').style.display='none';
  };
  if($('resultSubTab'))$('resultSubTab').onclick=function(){
    $('resultQrPane').style.display='none';
    $('resultConfigPane').style.display='none';
    $('resultSubPane').style.display='block';
  };
  if($('copyResultConfig'))$('copyResultConfig').onclick=function(){copyField('resultConfig');};
  if($('copyResultSub'))$('copyResultSub').onclick=function(){copyField('resultSub');};

  // Quick create uses the original form submit, so it uses the exact original API/payload.
  function quickCreate(){
    if(typeof openCreate==='function')openCreate();
    setTimeout(function(){
      var name=$('uName'), limit=$('uLimit'), expiry=$('uExpiry'), devices=$('uDevices');
      if(name && !name.value)name.value='user_'+Math.random().toString(36).slice(2,8);
      if(limit && !limit.value)limit.value='30';
      if(expiry && !expiry.value)expiry.value='30';
      if(devices && !devices.value)devices.value='2';
      if(typeof updateBuilderSummary==='function')updateBuilderSummary();
      var form=$('userForm');
      if(form){
        if(form.requestSubmit)form.requestSubmit();
        else form.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));
      }
    },120);
  }
  if($('quickCreateTopBtn'))$('quickCreateTopBtn').onclick=quickCreate;
})();
</script>



